window.__D={"items":[{"id":16009,"s":"Lowy Interpreter","sz":"T1","t":"AUKUS: Is there a Dickie Williams in the building?","th":"AUKUS: Van itt Dickie Williams?","u":"https://www.lowyinstitute.org/the-interpreter/aukus-is-there-a-dickie-williams-in-the-building","d":"2026-11-27","x":"A cikk az AUKUS szövetség kritikáját tárgyalja, különös figyelmet fordítva Chris Barrie, Ausztrália volt védelmi vezérkari főnökének véleményére. Barrie a nukleáris meghajtású tengeralattjáró programot megkérdőjelezve arra figyelmeztet, hogy a politikai elköteleződések nem helyettesíthetik a nemzeti védelmi igények világos értékelését. A történelmi példák, mint Richard","dom":"MDO","br":"Tüzér és tűztámogatás","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Australia","United Kingdom","United States"],"p":7,"cm":1,"cid":16009},{"id":15985,"s":"ASPI The Strategist","sz":"T1","t":"More details, please. The case for Australian SSNs is incomplete","th":"További részletek, kérem. Az ausztrál SSN-ek ügye hiányos","u":"https://www.aspistrategist.org.au/more-details-please-the-case-for-australian-ssns-is-incomplete/","d":"2026-11-27","x":"Az ausztrál kormány még mindig magyarázattal tartozik az AUKUS tengeralattjáró programmal kapcsolatban. Két indoklás, a visszatartás és a kereskedelem védelme, hiányosságokat mutat. A program költségei 30 év alatt akár 368 milliárd ausztrál dollárra is rúghatnak. A tengeralattjárók beszerzése mellett más alternatívák, például repülőgépek vagy a hazai termelés támogatása is szóba jöhet. A tengeralattjárók szerepe a kereskedelem védelmében korlátozott, és a költségek, valamint a késlekedések figyelembevételével a stratégiai előnyöket alaposan meg kell fontolni.","dom":"MAR","br":"Tengeralattjárók","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Australia","United States","United Kingdom"],"p":7,"cm":1,"cid":15985},{"id":16284,"s":"Army Technology","sz":"T2","t":"Lincad to supply LIPS 18 lithium-ion military batteries to UK MoD","th":"Lincad lítium-ion katonai akkumulátorokat szállít az Egyesült Királyság Védelmi Minisztériumának","u":"https://www.army-technology.com/news/lincad-lips-18-battery-uk/","d":"2026-11-26","x":"A Lincad új LIPS 18 lítium-ion akkumulátorának szállítására szerződést kötött az Egyesült Királyság Védelmi Minisztériuma. Az új akkumulátor a korábbi LIPS 8 modellt váltja fel a katonai felszerelésekben. A fejlesztés célja a katonai eszközök energiaellátásának javítása és a modernizáció elősegítése. Az akkumulátorok a szárazföldi haderő számára készülnek, és várhatóan növelik a haditechnikai kapacitásokat. A szerződés aláírása fontos lépés a brit hadsereg modernizációs programjában.","dom":"LAND","br":"Lövész és gépesített lövész csapatok","sp":["Lőszer és védelmi ipari kapacitás","Haderő-modernizáció és erőszerkezet"],"oc":["United Kingdom"],"p":7,"cm":1,"cid":16284},{"id":16195,"s":"Naval News","sz":"T2","t":"UK MOD Awards Babcock Record £8.7B ‘Gateway’ Submarine Support Deal","th":"Az Egyesült Királyság Védelmi Minisztériuma rekord 8,7 milliárd fontos tengeralattjáró támogatási megállapodást kötött a Babcockkal","u":"https://www.navalnews.com/naval-news/2026/11/uk-mod-awards-babcock-record-8-7b-gateway-submarine-support-deal/","d":"2026-11-26","x":"A Babcock nemrégiben rekord 8,7 milliárd fontos Gateway megállapodást írt alá az Egyesült Királyság Védelmi Minisztériumával, amely a tengeralattjáró támogatási és karbantartási szolgáltatásokra vonatkozik. A megállapodás célja a brit tengeralattjáró program és a folyamatos tengeri elrettentés támogatása, beleértve a Vanguard osztályú nukleáris tengeralattjárók Dreadnought osztályúra való átállását. Az új megállapodás 2026. december 1-jén lép életbe, és öt évre szól, de akár 15 évre is meghosszabbítható. A megállapodás 8,500 munkahelyet véd meg, és 3,000 új munkalehetőséget teremt, emellett több mint 2,500 gyakornoki és diplomás lehetőséget is támogat. A Babcock folyamatos programjai és a Gateway megállapodás együttesen erősítik az Egyesült Királyság védelmi képességeit és ipari bázisát.","dom":"MAR","br":"Tengeralattjárók","sp":["Hajóépítés és haditengerészet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United Kingdom"],"p":9,"cm":1,"cid":16195,"sp2":73,"ind":"Jelentőség 5/5, újdonság 4/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Rekord összegű szerződés a brit tengeralattjáró program támogatására."},{"id":16194,"s":"Naval News","sz":"T2","t":"French Startup Arsenals Unveils Modular AUV Designed for Rapid Production","th":"Francia startup, az Arsenals bemutatja moduláris AUV-ját, amelyet gyors gyártásra terveztek","u":"https://www.navalnews.com/naval-news/2026/11/euronaval-2026-french-startup-arsenals-unveils-modular-auv/","d":"2026-11-26","x":"Az Arsenals, egy francia védelmi startup, bemutatta moduláris autonóm víz alatti járművét (AUV) az Euronaval 2026 rendezvényen. A Harpoon névre keresztelt jármű egy közös platformra épül, amely lehetővé teszi a plug-and-play payload moduláris felépítést, beleértve a keresőfejeket, robbanófejeket és érzékelőket. A rendszer célja a gyorsaság, állóképesség, kommunikáció és autonóm navigáció biztosítása a GNSS utáni környezetekben. Az Arsenals a platformot mint attritív erőszorzót pozicionálja, amely képes fenntartani a taktikai mélységet a hagyományos haditengerészeti flották előtt. A cég célja, hogy óránként egy AUV-t gyártson, lehetővé téve 100 jármű előállítását 100 óra alatt.","dom":"MAR","br":"Tengeralattjárók","sp":["Drónok és drónelhárítás","Hajóépítés és haditengerészet"],"oc":["France"],"p":8,"cm":1,"cid":16194},{"id":16196,"s":"Naval News","sz":"T2","t":"Lockheed Martin Unveils Weapons Suite for Gibbs \u0026 Cox’s International Class Frigate","th":"Lockheed Martin bemutatja a fegyverzetet a Gibbs \u0026 Cox nemzetközi osztályú fregattjához","u":"https://www.navalnews.com/naval-news/2026/11/lockheed-martin-weapons-suite-international-class-frigate/","d":"2026-11-26","x":"A Lockheed Martin bemutatta a közepes hatótávolságú fegyverzetét a Gibbs \u0026 Cox nemzetközi osztályú fregatt tervezetéhez az Euronaval 2026 rendezvényen. A fregatt moduláris függőleges indítócellákkal és közös légi-földi rakéta quad indítókkal van felszerelve. A 4000 tonnás felszíni harci hajó általános célú küldetésekre lett tervezve, és több ország, köztük a Fülöp-szigetek, Horvátország és az Egyesült Államok érdeklődését felkeltette. A Lockheed Martin rendszereit a fregatt koncepcióba való integrálásra szánták, hogy megfeleljenek a globális felszíni harci hajók iránti növekvő igényeknek. A fregatt célja a kísérő, tengeralattjáró-elhárító és felszíni harci feladatok ellátása.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Lőszer és védelmi ipari kapacitás"],"oc":["Philippines","Croatia","Egypt","Romania","Bahrain","Greece","Sweden","Kuwait","United States"],"p":8,"cm":1,"cid":16196},{"id":16069,"s":"Modern War Institute","sz":"T1","t":"Five Questions for a General: General Shawn Bratton","th":"Öt kérdés egy tábornoknak: Shawn Bratton tábornok","u":"https://mwi.westpoint.edu/five-questions-for-a-general-general-shawn-bratton/","d":"2026-11-26","x":"Shawn Bratton tábornok, az Egyesült Államok Űrhaderőjének alelnöke, közel négy évtizedes katonai szolgálatáról beszél. Tapasztalatait Irakban, valamint az innovatív katonai technológiák bevezetésére tett erőfeszítéseit osztja meg. Bratton tábornok hangsúlyozza a fiatal tisztek és a magas rangú altisztek szerepét a katonai szervezetek építésében és a tehetség fejlesztésében. Kiemeli a multidomain műveletek közötti kölcsönhatást, valamint az űrhaderő felelősségét az űrbeli fölény biztosításában. Az epizód végén Bratton tábornok saját kérdéseket is feltesz a cadet interjúalanyának.","dom":"SPA","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","MI és autonómia"],"oc":["United States"],"p":7,"cm":1,"cid":16069},{"id":16247,"s":"SpaceNews","sz":"T2","t":"The ‘bare-knuckled’ future of life in space with Tim Marshall","th":"A 'meztelen ököl' jövője az űrben Tim Marshall-lal","u":"https://spacenews.com/the-bare-knuckled-future-of-life-in-space-with-tim-marshall/","d":"2026-11-26","x":"Tim Marshall újságíróval beszélget Mike Gruss, ahol a háború Ukrajnában felhívta a figyelmet arra, hogyan kezelik a fenyegetéseket Európában és az Egyesült Államokban. A beszélgetés során szóba kerül, hogy az űr mindig is a hadviselés fontos eleme lesz a jövőben, és hogy új szabályokra van szükség az emberiség űrkutatásának és gyarmatosításának irányításához. A Space-Comm Expo Europe esemény keretében a legnagyobb kereskedelmi űr- és védelmi rendezvény kerül megrendezésre, amely összeköti az ipart a kormányzati és katonai vezetőkkel.","dom":"SPA","br":"Világűr- és műholdképességek","sp":["Hajóépítés és haditengerészet","Világűr- és műholdképességek"],"oc":["United States","Ukraine"],"p":7,"cm":1,"cid":16247},{"id":16198,"s":"Naval News","sz":"T2","t":"French Navy Trains with Philippine Coast Guard Ship from Taiwan","th":"Francia Haditengerészet Képzése a Fülöp-szigetek Parti Őrségével","u":"https://www.navalnews.com/naval-news/2026/11/french-navy-trains-with-philippine-coast-guard-ship-from-taiwan/","d":"2026-11-26","x":"A Francia Haditengerészet a Fülöp-szigetek Parti Őrségének új, Tajvanból származó járőrhajójával közösen végzett képzést a Sulu-tengeren. A gyakorlat során a BRP Sarangani (6177) hajó a FS Vendémiaire (F734) és a BRP Diego Silang (FFG-7) fregattokkal együtt hajtott végre különböző feladatokat, beleértve a helikopteres és a látogatás, ellenőrzés, keresés és lefoglalás (VBSS) gyakorlatokat. Az esemény a Fülöp-szigetek és Franciaország közötti védelmi partnerség erősödését jelzi, amely a közös védelmi megállapodás, a Visiting Forces Agreement ratifikálásával vált lehetővé. A BRP Sarangani a leggyorsabb járőrhajó a Parti Őrség flottájában, amely lehetővé teszi a kínai hajók hatékonyabb megfigyelését a térségben.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["France","Philippines","Taiwan"],"p":7,"cm":1,"cid":16198},{"id":15823,"s":"RUSI","sz":"T1","t":"Views from Ukraine on Digitalised Warfare","th":"Ukrajna nézőpontjai a digitalizált hadviselésről","u":"https://www.rusi.org/explore-our-research/publications/commentary/views-ukraine-digitalised-warfare","d":"2026-11-26","x":"A cikk az ukrán hadsereg digitalizált hadviselésének tapasztalatait elemzi, hangsúlyozva, hogy a mesterséges intelligencia (AI) és az automatizálás nem bizonyult olyan meghatározónak, mint a rendszerek és adatok integrálása. Az ukrán hadsereg nem tekinthető teljesen automatizáltnak, mivel a feladatok automatizálása nem elterjedt. A DELTA platform példája bemutatja, hogyan integrálják a helyzetérzékelő és parancsnoki rendszereket, ami fontos tanulságokat hordoz a NATO számára is. A cikk rávilágít a digitális struktúrák érettségének és az adatok minőségének fontosságára a jövőbeli AI alkalmazások sikeressége szempontjából. Az ukrán tapasztalatok alapján a modernizációs kezdeményezések során figyelembe kell venni a rendszerek közötti interoperabilitást és a gyors frissítési lehetőségeket.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Drónok és drónelhárítás","Vezetés-irányítás és ISR (C2/ISR)","Haderő-modernizáció és erőszerkezet"],"oc":["Ukraine","United Kingdom"],"p":8,"cm":1,"cid":15823,"sp2":45,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Ukrajna digitalizált hadviselési tapasztalatai."},{"id":15984,"s":"ASPI The Strategist","sz":"T1","t":"Kasandigan – the Philippines is pivotal to Australian strategy as never before","th":"Kasandigan – a Fülöp-szigetek kulcsszerepet játszik az ausztrál stratégiában","u":"https://www.aspistrategist.org.au/kasandigan-the-philippines-is-pivotal-to-australian-strategy-as-never-before/","d":"2026-11-27","x":"A Fülöp-szigetek növekvő jelentősége az ausztrál stratégiában kiemelkedő fejlemény, amely a legutóbbi Kasandigan nyilatkozatban is megnyilvánult. Az ausztrál és a fülöp-szigeteki védelmi kapcsolatok szorosabbra fűzése, különösen a 2023-as stratégiai partnerség óta, célja a védelmi együttműködés erősítése és a regionális hatalmi egyensúly fenntartása. A nyilatkozat hangsúlyozza a közös védelem és a regionális biztonsági érdekek védelmét, valamint a Fülöp-szigetek kulcsszerepét a katonai stratégiában, különösen Kína növekvő nyomásának fényében. A két ország közötti védelmi együttműködés modernizálása és a közös gyakorlatok bővítése is szerepet kap a Kasandigan keretében.","dom":"MDO","br":"Többdomainű és ágazatközi","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Australia","Philippines","United States","Japan"],"p":8,"cm":1,"cid":15984,"sp2":45,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Fülöp-szigetek szerepe az ausztrál stratégiában."},{"id":15986,"s":"ASPI The Strategist","sz":"T1","t":"Mutually reinforcing and wrong: military AI agents in the agentic interspace","th":"Kölcsönösen erősítő és téves: katonai AI ügynökök az ügynöki interspacében","u":"https://www.aspistrategist.org.au/mutually-reinforcing-and-wrong-military-ai-agents-in-the-agentic-interspace/","d":"2026-11-26","x":"A katonai AI ügynökök közötti interakciók során felmerülő problémákra hívja fel a figyelmet a cikk. Az AI ügynökök közötti információcsere során a hibák és torzítások felhalmozódhatnak, ami hamis konszenzushoz vezethet. A cikk hangsúlyozza, hogy a hagyományos biztosítási módszerek nem képesek kezelni az ügynöki interspacében fellépő kockázatokat. A szerző javasolja, hogy a katonai szervezetek teszteljék az AI ügynökök közötti kapcsolatok megbízhatóságát, nem csupán az egyes ügynökökét. Az átláthatóság és az auditálható naplók bevezetése segíthet a döntéshozatali folyamatok nyomon követésében.","dom":"CYB","br":"Híradó és informatikai csapatok (CIS)","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Australia"],"p":8,"cm":1,"cid":15986,"sp2":45,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. AI ügynökök közötti interakciók problémái."},{"id":16197,"s":"Naval News","sz":"T2","t":"Euronaval 2026: Euroatlas and EvoLogics Move Greyshark AUV into Series Production","th":"Euronaval 2026: Euroatlas és EvoLogics a Greyshark AUV sorozatgyártásába lép","u":"https://www.navalnews.com/event-news/euronaval-2026/2026/11/euronaval-2026-euroatlas-evologics-greyshark-uuv-series-production/","d":"2026-11-26","x":"Az Euroatlas és az EvoLogics bejelentette, hogy a Greyshark akkumulátoros változata a prototípus fázisból a sorozatgyártásba lépett, és az első szállítmányok 2026 végén kezdődnek. A Greyshark AUV két változata, a S1-Bravo és a S1-Foxtrot, különböző képességekkel rendelkezik, beleértve az anti-tengeralattjáró hadviselést és a bányamentesítést. A Greyshark tervezése során figyelembe vették a tengeri környezet kihívásait, és a jármű képes hosszú távú műveletek végrehajtására is. A sorozatgyártás során számos fejlesztést hajtottak végre, beleértve az ipari szabványú víz alatti meghajtókat és a merülési síneket. A Greyshark AUV a jövőben további fejlesztések lehetőségét is magában hordozza.","dom":"MAR","br":"Tengeralattjárók","sp":["Hajóépítés és haditengerészet","Drónok és drónelhárítás"],"oc":["Germany","Portugal"],"p":8,"cm":1,"cid":16197},{"id":15266,"s":"ASPI The Strategist","sz":"T1","t":"Fault Lines – USFK’s reach, ASEAN deadlock, Cook Islands minerals","th":"USFK helikopterek Japánban","u":"https://www.aspistrategist.org.au/fault-lines-usfks-reach-asean-deadlock-cook-islands-minerals/","d":"2026-11-25","x":"A Koreai Egyesült Államok Erői (USFK) 2026. november 23-án bejelentették, hogy a 2. Harci Repülőszázaduk támadó és hasznos helikopterei Japánba kerültek telepítésre légi élő tűzgyakorlat és expedíciós kiképzés céljából. Ez a lépés a régió védelmi képességeinek növelését célozza, és a USFK stratégiájának részeként értelmezhető, amely a Koreai-félszigetről való erőprojekciót hangsúlyozza. A közelmúltban a USFK erői már részt vettek más hadgyakorlatokon is a térségben, például a Fülöp-szigeteken zajló Balikatan gyakorlaton. A dél-koreai hadsereg folyamatosan fejleszti képességeit, hogy átvegye a háborús operatív irányítást az Egyesült Államokkal közösen végzett védelemben.","dom":"AIR","br":"Hadsereg-repülők és helikopterek","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["South Korea","Japan","United States"],"p":7,"cm":1,"cid":15266},{"id":15434,"s":"Breaking Defense","sz":"T2","t":"Delivery of first MV-75 for testing officially delayed amid funding setbacks: Army","th":"Az első MV-75 tesztelésének szállítása hivatalosan késlekedik a finanszírozási problémák miatt","u":"https://breakingdefense.com/2026/11/delivery-of-first-mv-75-for-testing-officially-delayed-amid-funding-setbacks-army/","d":"2026-11-25","x":"Az Egyesült Államok Hadserege bejelentette, hogy a következő generációs MV-75 többcélú függőleges emelő repülőgép, a Cheyenne II néven ismert helikopter, nem érkezik meg a tervezett időpontban tesztelésre. A program finanszírozási hiányosságai miatt a szállítási célok nem teljesülnek, és a Hadsereg jelenleg a Bell céggel dolgozik a program ütemtervének frissítésén. A Cheyenne II kétszer olyan gyorsan és kétszer olyan messzire képes repülni, mint a meglévő helikopterek, és fokozatosan felváltja a UH-60 Black Hawk flottát. A program prioritás a Hadsereg számára, és elkötelezettek a repülőgép mielőbbi átadása mellett.","dom":"AIR","br":"Hadsereg-repülők és helikopterek","sp":["Haderő-modernizáció és erőszerkezet","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":7,"cm":1,"cid":15434},{"id":15450,"s":"The War Zone","sz":"T2","t":"Drone Threats Prompt RAF To Install Netting At Bases To Protect Aircraft: Reports","th":"Dronfenyegetések miatt hálókat telepít a RAF az alapjain, hogy megvédje a repülőgépeket","u":"https://www.twz.com/news-features/drone-threats-prompt-raf-to-install-netting-at-bases-to-protect-aircraft-reports","d":"2026-11-25","x":"A Királyi Légierő (RAF) a drónokkal szembeni növekvő fenyegetések miatt passzív védelmi intézkedéseket vezet be, beleértve a védőháló telepítését a repülőgépek számára, amelyek nem helyezhetők el hangárokban. Az intézkedés az iráni fenyegetések következményeként jött létre, amelyek megnövelt biztonsági intézkedéseket és az amerikai repülőgépek evakuálását eredményezték. A RAF éjszaka hangárokba helyezi repülőgépeit a drónfenyegetés miatt, és a brit védelmi minisztérium 470 millió fontot fektet a katonai helyszínek biztonságának megerősítésébe. Az amerikai légierő is érintett lehet, de a konkrét intézkedésekről nem adtak tájékoztatást.","dom":"AIR","br":"Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)","sp":["Drónok és drónelhárítás","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United Kingdom","United States","Iran","Germany"],"p":7,"cm":1,"cid":15450},{"id":15451,"s":"The War Zone","sz":"T2","t":"Final KC-46 Tankers Under Original Contract With Boeing Ordered By USAF","th":"Az USAF megrendelte az utolsó KC-46 tankereket az eredeti Boeing szerződés keretein belül","u":"https://www.twz.com/air/final-kc-46-tankers-under-original-contract-with-boeing-ordered-by-usaf","d":"2026-11-25","x":"Az Egyesült Államok Légierője leadta az utolsó megrendelését a KC-46A Pegasus tankerekre a 2011-ben aláírt eredeti szerződés keretein belül. A Boeing jelenleg is dolgozik a KC-46 technikai hiányosságainak megoldásán, különösen a távoli látórendszeren. A Pentagon és a Boeing bejelentette, hogy 15 új KC-46 gyártásáról szóló megállapodást kötöttek, amelynek értéke meghaladja a 2,81 milliárd dollárt. Az Air Force tervezi, hogy 75 további Pegasus tankert vásárol, de ezt a megállapodást csak a hiányosságok megoldása után véglegesítik. A jövőbeni tankerek fejlesztése érdekében az Air Force új lehetőségeket vizsgál az Advanced Tanker Systems program keretein belül.","dom":"AIR","br":"Légi szállítás és utántöltés","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Japan","Israel"],"p":8,"cm":5,"cid":15437},{"id":15551,"s":"Defense News","sz":"T2","t":"US Air Force buys final KC-46 lot under Boeing’s original tanker deal","th":"Az Egyesült Államok Légierője megvásárolja a KC-46 utolsó tételét a Boeing eredeti tanker megállapodása keretében","u":"https://www.defensenews.com/industry/techwatch/2026/11/25/us-air-force-buys-final-kc-46-lot-under-boeings-original-tanker-deal/","d":"2026-11-25","x":"A Pentagon bejelentette, hogy 2,82 milliárd dolláros szerződést kötött a Boeinggal 15 KC-46A Pegasus tanker megvásárlására, amely az eredeti 2011-es szerződés keretében az utolsó gyártási tétel. Az új tétel várhatóan 2030 közepére készül el, míg a korábbi tétel 2029 közepére. Az Egyesült Államok Légierője eddig 116 KC-46A-t kapott, és összesen 203 van szerződésben vagy szolgálatban világszerte. A légierő célja 263 KC-46A beszerzése, amelyek teljes mértékben helyettesítik a 1950-es és 1960-as években gyártott KC-135-ösöket. A Boeing a program során jelentős veszteségeket könyvelt el, több mint 7 milliárd dollárt, és a fő problémák között szerepel a légi utántöltő rendszer megbízhatósága és az alkatrészhiány.","dom":"AIR","br":"Légi szállítás és utántöltés","sp":["Haderő-modernizáció és erőszerkezet","Beszerzés és védelmi költségvetés"],"oc":["United States","Japan","Israel"],"p":8,"cm":5,"cid":15437},{"id":15581,"s":"Military Times","sz":"T2","t":"US Air Force buys final KC-46 lot under Boeing’s original tanker deal","th":"Az Egyesült Államok Légierője megvásárolja az utolsó KC-46-os tételt a Boeing eredeti tanker megállapodása keretében","u":"https://www.militarytimes.com/news/your-military/2026/11/25/us-air-force-buys-final-kc-46-lot-under-boeings-original-tanker-deal/","d":"2026-11-25","x":"A Pentagon bejelentette, hogy 2,82 milliárd dolláros szerződést kötött a Boeinggal 15 KC-46A Pegasus tanker megvásárlására, amely az eredeti 2011-es szerződés keretében az utolsó gyártási tétel. Az Egyesült Államok Légierője eddig 116 KC-46A-t kapott, és világszerte 203 van szerződésben vagy szolgálatban. A légierő célja, hogy 263 KC-46A-t szerezzen be, amelyek teljes mértékben helyettesítik a 1950-es és 1960-as években épült KC-135-öket. A Boeing a program során több mint 7 milliárd dolláros veszteséget könyvelt el, és a légierő a tanker megbízhatósági problémáira hivatkozva halasztotta el a további beszerzéseket. A KC-46 program modernizációja folytatódik, és a légierő várhatóan 2027 nyarára tervezi az új rendszer bevezetését.","dom":"AIR","br":"Légi szállítás és utántöltés","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["United States","Japan","Israel"],"p":8,"cm":5,"cid":15437},{"id":15475,"s":"Naval News","sz":"T2","t":"Australia Receives First Virginia-Class Submarine Simulator at HMAS Stirling","th":"Ausztrália megkapta első Virginia-osztályú tengeralattjáró szimulátorát a HMAS Stirlingnél","u":"https://www.navalnews.com/naval-news/2026/11/australia-first-virginia-class-submarine-simulator-hmas-stirling/","d":"2026-11-25","x":"Ausztrália megkapta első Virginia-osztályú tengeralattjáró képzési rendszereit, beleértve a Virginia Ship Control Operations Trainer (VSCOT) szimulátort a HMAS Stirlingnél, az AUKUS keretében. A szimulátor lehetővé teszi a személyzet számára, hogy valósághű és kontrollált környezetben képezze magát a tengeralattjáró manőverezésében és operatív eljárásaiban. A képzési központ célja, hogy támogassa a jövőbeli tengeralattjáró legénység fejlesztését, és erősítse az integrációt Ausztrália és AUKUS-partnerei között. A képzési rendszerek szállítása összetett logisztikai művelet keretében valósult meg, amely magában foglalta a tengeri szállítást és a nehéz emelőkről való munkát. Ez a létesítmény nemcsak a képzés színvonalát emeli, hanem a két ország közötti együttműködést is erősíti.","dom":"MAR","br":"Tengeralattjárók","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Australia","United States"],"p":8,"cm":1,"cid":15475,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Ausztrália új tengeralattjáró szimulátort kapott."},{"id":15484,"s":"Defense One","sz":"T2","t":"Defense Business Brief: Building warships; Drones; Neighborhood watch; and more...","th":"Hadiipari Hírek: Hadihajók építése; Drónok; Szomszédsági megfigyelés; és még sok más...","u":"https://www.defenseone.com/business/2026/11/defense-business-brief-building-warships-drones-neighborhood-watch-and-more/417441/","d":"2026-11-25","x":"A cikk a hadihajók építésével és a haditengerészet dróntechnológiájának fejlesztésével foglalkozik. A Kongresszus sürgeti a haditengerészetet, hogy dolgozzon ki egy stratégiát a külföldi partneri képességek hatékony felhasználására, miközben aggályokat fogalmaznak meg a külföldi hajógyárak alkalmazásával kapcsolatban. A haditengerészet célja, hogy gyorsabban építsen új hajókat, beleértve egy új fregattot is. A cikk említi a nem-földi képek készítésének fontosságát is, amely lehetővé teszi a katonai tevékenységek megfigyelését az űrben. A haditengerészet drónokkal kapcsolatos késlekedései szintén aggasztóak, mivel ezek a technológiák nem kerültek megfelelően beépítésre a flotta doktrínájába.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Drónok és drónelhárítás"],"oc":["United States","South Korea","Italy","Russia"],"p":8,"cm":1,"cid":15484,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Általános hírek hadihajókról és drónokról."},{"id":15552,"s":"Defense News","sz":"T2","t":"Japan to use Indian ranges for long-range missile training under new pact","th":"Japán indiai lőtereket használ hosszú hatótávolságú rakétás kiképzéshez az új megállapodás keretében","u":"https://www.defensenews.com/global/asia-pacific/2026/11/25/japan-to-use-indian-ranges-for-long-range-missile-training-under-new-pact/","d":"2026-11-25","x":"Japán először használhat indiai lőtereket élő tűzgyakorlatokhoz, hogy tesztelje hosszú hatótávolságú rakétaképességeit, beleértve a felszíni hajó elleni rakétákat. A megállapodást a két ország védelmi minisztereinek találkozóján írták alá. A japán hadsereg a korlátozott hely miatt keresi a külföldi kiképzési lehetőségeket. A megállapodás célja a Japán és India közötti védelmi együttműködés elmélyítése, valamint a közös védelmi technológiai együttműködés felgyorsítása. A két ország közötti együttműködés a jövőbeli hadgyakorlatok bonyolultságának növelésére is kiterjed, beleértve a drónok alkalmazását is.","dom":"LAND","br":"Tüzér és tűztámogatás","sp":["Rakéták és hiperszonikus fegyverek","Haderő-modernizáció és erőszerkezet"],"oc":["Japan","India"],"p":8,"cm":1,"cid":15552,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Japán és India közötti új katonai megállapodás."},{"id":15563,"s":"Army Technology","sz":"T2","t":"Kongsberg, Ukraine develop Desna air defence system","th":"Kongsberg és Ukrajna kifejlesztette a Desna légvédelmi rendszert","u":"https://www.army-technology.com/news/kongsberg-ukraine-desna-defence/","d":"2026-11-25","x":"A Kongsberg Gruppen légvédelmi rendszert fejlesztett ki Desna néven, amelyet norvég és ukrán hatóságok, valamint az ukrán ipar közreműködésével hoztak létre. A rendszer már működik, és célja, hogy védelmet nyújtson az emberek és a kritikus infrastruktúra számára drónok és egyéb légi fenyegetések ellen. A Desna ukrán gyártású légvédelmi rakétákat és indító egységeket kombinál a Kongsberg tűzparancsnoki és irányító központjával. A rendszer kiegészíti a NASAMS-t, amely 2022 óta működik Ukrajnában. A Kongsberg vezérigazgatója, Eirik Lie elmondta, hogy a Desna fontos kiegészítése a teljes légvédelmi megoldások fejlesztésének.","dom":"AIR","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás"],"oc":["Norway","Ukraine","Germany"],"p":8,"cm":1,"cid":15563,"sp2":65,"ind":"Jelentőség 4/5, újdonság 4/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új légvédelmi rendszer Ukrajna és Norvégia együttműködésében.","hu":["közvetett","A Desna légvédelmi rendszer fejlesztése közvetett relevanciával bírhat Magyarország számára, mivel a Kongsberg által fejlesztett NASAMS rendszer már része a Magyar Honvédség légvédelmi arzenáljának [HU-11]. A Desna rendszer kiegészíti a NASAMS-t, amely Magyarországon is beszerzésre került, így a Desna fejlesztése potenciálisan befolyásolhatja a NASAMS rendszer jövőbeli fejlesztéseit és integrációját a magyar légvédelemben.","ok"]},{"id":15553,"s":"Defense News","sz":"T2","t":"Buried in Italy’s budget, officials see Rome meeting NATO spending target","th":"Olaszország teljesíti a NATO költségvetési célját","u":"https://www.defensenews.com/global/europe/2026/11/25/buried-in-italys-budget-officials-see-rome-meeting-nato-spending-target/","d":"2026-11-25","x":"Olaszország 2026-os védelmi költségvetése elérte a 2,8%-os GDP arányt, amely megfelel a NATO által kitűzött céloknak. A költségvetés elemzése alapján a védelmi kiadások 2,1%-ot, míg a belső biztonsági kiadások 0,7%-ot tesznek ki. Az összesített védelmi költségvetés 48,31 milliárd euróra nőtt, ami 2,1%-os GDP arányt jelent. A költségvetés tartalmazza a hadsereg, légierő és haditengerészet kiadásait, valamint a különböző védelmi programokhoz kapcsolódó beszerzéseket is. A kormány forrásai szerint a belső biztonsági kiadások körülbelül 16,1 milliárd eurót tesznek ki, amelyek a határvédelemre és a terrorizmus elleni küzdelemre vonatkoznak.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["Italy"],"p":7,"cm":1,"cid":15553},{"id":15564,"s":"Army Technology","sz":"T2","t":"ARX Robotics links UGV to British Army’s ASGARD targeting network","th":"ARX Robotics összekapcsolja az UGV-t a brit hadsereg ASGARD célzó hálózatával","u":"https://www.army-technology.com/news/arx-ugv-british-army-asgard/","d":"2026-11-25","x":"Az ARX Robotics bejelentette, hogy egy pilóta nélküli földi járművet integrált a brit hadsereg ASGARD digitális célzó hálózatába egy kenyai gyakorlat során. Ez volt az első sikeres integrációja egy pilóta nélküli földi rendszernek az ASGARD-dal. A jármű érzékelői célpontokat azonosítottak és információt továbbítottak a hadsereg szélesebb felderítési és célzási folyamatába. Az integráció jelentős, mivel összekapcsolja a jármű harctéri adatait egy meglévő hadsereg célzó hálózattal, így a GEREON jármű nem csupán távoli megfigyelő eszközként működött, hanem közvetlen információt nyújtott a fenyegetésekre adott válaszok támogatásához.","dom":"LAND","br":"Felderítő csapatok (RSTA)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["United Kingdom","Kenya"],"p":8,"cm":1,"cid":15564,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. UGV integráció a brit hadsereg hálózatába."},{"id":15578,"s":"Military Times","sz":"T2","t":"Army conducts controlled detonation of lead-based explosives stockpile in Iowa","th":"Az amerikai hadsereg kontrollált robbantást hajtott végre ólom alapú robbanóanyag készletének megsemmisítésére Iowa államban","u":"https://www.militarytimes.com/news/2026/11/25/army-conducts-controlled-detonation-of-lead-based-explosives-stockpile-in-iowa/","d":"2026-11-25","x":"Az Egyesült Államok kormánya kontrollált robbantást hajtott végre egy elöregedett ólom alapú robbanóanyag készlet megsemmisítésére az Iowa Army Ammunition Plant területén. A robbantás célja az volt, hogy elkerüljék a veszélyes helyzetet, amelyet a romló kémiai hordók önálló robbanása jelentett volna. A hadsereg közel 5 tonna instabil ólom-azidot robbantott fel, miközben a környező lakosságot arra kérték, hogy maradjanak otthonaikban a robbanás által kibocsátott mérgező por miatt. A robbantás után a lakosokat figyelmeztették, hogy kövessék az EPA biztonsági irányelveit, amíg a hatóságok nem adják meg a zöld lámpát a kijárásra.","dom":"LAND","br":"Tüzér és tűztámogatás","sp":[],"oc":["United States"],"p":6,"cm":1,"cid":15578},{"id":15440,"s":"Breaking Defense","sz":"T2","t":"First Dark Eagle hypersonic battery ‘fully fielded,’ Lozano says","th":"Az első Dark Eagle hiperszonikus üteg teljesen hadrendbe állt","u":"https://breakingdefense.com/2026/11/first-dark-eagle-hypersonic-battery-fully-fielded-lozano-says/","d":"2026-11-25","x":"A hadsereg hivatalosan hadrendbe állította első Long Range Hypersonic Weapon (LRHW) ütegét. A rendszer globálisan telepíthető és alkalmazható harci képességet biztosít. A hadsereg kezdetben 2023-ra tervezte az üteg hadrendbe állítását, de különböző tesztelési problémák miatt ez késlekedett. A Dark Eagle program a hadsereg és a haditengerészet közötti együttműködés eredménye, és a hiperszonikus fegyverek iránti növekvő érdeklődés tükrözi a globális biztonsági kihívásokat. A hadsereg már dolgozik a második és harmadik üteg hadrendbe állításán is.","dom":"LAND","br":"Tüzér és tűztámogatás","sp":["Rakéták és hiperszonikus fegyverek","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":15440,"sp2":73,"ind":"Jelentőség 5/5, újdonság 4/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Első hiperszonikus üteg hadrendbe állítása."},{"id":15437,"s":"Breaking Defense","sz":"T2","t":"Air Force issues Boeing $2.8 billion for more KC-46s","th":"Az Egyesült Államok Légierője 2,8 milliárd dollárt ítélt meg a Boeingnek több KC-46-osért","u":"https://breakingdefense.com/2026/11/air-force-issues-boeing-2-8-billion-for-more-kc-46s/","d":"2026-11-25","x":"Az Egyesült Államok Légierője 2,8 milliárd dolláros megbízást adott a Boeingnek, hogy újabb KC-46 Pegasus légi utántöltőket gyártson. A megbízás a 13. gyártási tételre vonatkozik, amely 15 repülőgépet foglal magában, és a munkálatok várhatóan 2030 júniusáig befejeződnek. A KC-46 a Boeing 767-es kereskedelmi repülőgépre épül, és az Egyesült Államok legújabb légi utántöltője, amelyet az elöregedett KC-135 Stratotanker flottájának fokozatos korszerűsítésére vásárolnak. A Légierő további 75 repülőgép megrendelését tervezi a program kiterjesztésével, de a jövőbeli gépek ára emelkedni fog. A szolgáltatás elkötelezte magát amellett, hogy nem lép tovább a kiterjesztési tervvel, amíg a gép fennmaradó problémáit nem oldják meg.","dom":"AIR","br":"Légi szállítás és utántöltés","sp":["Haderő-modernizáció és erőszerkezet","Beszerzés és védelmi költségvetés"],"oc":["United States","Japan","Israel","Qatar"],"p":8,"cm":5,"cid":15437,"sp2":68,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 5/5 (5 forrás), forrásszint 3/5. Újabb KC-46-os beszerzés, de nem új típus."},{"id":15474,"s":"Naval News","sz":"T2","t":"Indonesian Navy Takes Delivery of 58-Knot Missile-Capable USV","th":"Indonéz Haditengerészet Átvette az 58 Csomós Rakétaképességű USV-t","u":"https://www.navalnews.com/naval-news/2026/11/indonesian-navy-ksr-x33-missile-usv/","d":"2026-11-26","x":"2026. november 25-én az indonéz PT Lundin Industry Invest, más néven North Sea Boats, átadta az első KSR X33 Light Attack Craft-ot az indonéz Haditengerészetnek. A 20 méter hosszú, szénszálas hajó manőverezhető pilótával és pilóta nélkül is, és a TNI AL szolgálatában az első hivatalosan hadihajónak minősülő USV. A hajó 58 csomós sebességet ért el a tengeri próbák során, és 12,7 mm-es távirányítású fegyverzettel van felszerelve, valamint képes két hosszú hatótávolságú rakéta szállítására is. A KSR X33 tervezése a parti és littorális hadviselésre összpontosít, különösen a stratégiai tengeri útvonalakon.","dom":"MAR","br":"Tengeri pilóta nélküli rendszerek","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Indonesia"],"p":8,"cm":1,"cid":15474,"sp2":65,"ind":"Jelentőség 4/5, újdonság 4/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Indonéz haditengerészet új USV átvétele."},{"id":15478,"s":"Naval News","sz":"T2","t":"Poland Lays Keel for Third Miecznik Frigate, Signs CAMM-MR Missile Deal with UK","th":"Lengyelország letette a harmadik Miecznik fregatt alapkövét, aláírta a CAMM-MR rakétaszerződést az Egyesült Királysággal","u":"https://www.navalnews.com/naval-news/2026/11/poland-lays-keel-third-miecznik-frigate-huragan/","d":"2026-11-25","x":"Lengyelország letette a harmadik Miecznik-osztályú fregatt, az ORP Huragan (276) alapkövét Gdyniában, miközben Varsó és London megállapodást írt alá a CAMM-MR rakéta közös fejlesztéséről. A Miecznik program keretében három fregatt egyidejű gyártása zajlik, amely a hazai hajógyártás fellendítését is szolgálja. A CAMM-MR rakéta várhatóan meghaladja a 100 kilométeres hatótávolságot, és integrálva lesz a fregattok Mk 41 függőleges indítórendszereibe. A program értéke meghaladja a 15 milliárd PLN-t, és a PGZ-MIECZNIK Konzorcium irányítja. A fregattok gyártása 2028-ra várható, a szállítás pedig 2031 végére.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Lőszer és védelmi ipari kapacitás"],"oc":["Poland","United Kingdom"],"p":8,"cm":1,"cid":15478,"sp2":65,"ind":"Jelentőség 4/5, újdonság 4/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Lengyelország új fregatt és rakétaszerződés."},{"id":15349,"s":"Modern War Institute","sz":"T1","t":"For Want of Nitroguanidine, the Artillery Was Lost: The Critical Chemicals Essential to Military Manufacturing","th":"A nitroguanidin hiánya miatt elveszett a tüzérség: A katonai gyártáshoz elengedhetetlen kritikus vegyszerek","u":"https://mwi.westpoint.edu/for-want-of-nitroguanidine-the-artillery-was-lost-the-critical-chemicals-essential-to-military-manufacturing/","d":"2026-11-25","x":"A modern hadviselés során a katonai gyártás nemcsak alapanyagokra, hanem kritikus vegyszerekre is támaszkodik. Az iráni háború rávilágított arra, hogy a vegyi anyagok hiánya megakadályozhatja a fegyverek előállítását. Az Egyesült Államok hadserege már azonosította a fontos vegyi anyagokat, és a nitroguanidin hazai termelésének beindítása is folyamatban van. A gyártási kapacitások helyreállítása érdekében a hadsereg különböző vegyi anyagokat vizsgál, amelyek nélkülözhetetlenek a lőszerek előállításához. A gyártási láncok zökkenőmentes működése érdekében elengedhetetlen a megfelelő vegyszerek biztosítása, mivel egyetlen összetevő hiánya is leállíthatja a termelést.","dom":"MDO","br":"Tüzér és tűztámogatás","sp":["Lőszer és védelmi ipari kapacitás","Beszerzés és védelmi költségvetés"],"oc":["United States","Iran","China","Ukraine"],"p":8,"cm":1,"cid":15349,"sp2":58,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Vegyi anyagok fontossága a katonai gyártásban.","hu":["közvetett","A hír a kritikus vegyszerek, például a nitroguanidin hiányának hatását tárgyalja a katonai gyártásra, ami közvetett módon releváns lehet Magyarország számára is. A magyar védelmi ipar, különösen a várpalotai lőszergyár, amely a Magyar Honvédség számára szállít lőszert, szintén függhet ilyen kritikus vegyi anyagoktól [HU-04]. A gyártási láncok zökkenőmentes működése érdekében Magyarország számára is fontos lehet a vegyszerek biztosítása a lőszerek előállításához.","ok"]},{"id":15436,"s":"Breaking Defense","sz":"T2","t":"Israel increases defense budget by $5 billion as concerns continue over future funding","th":"Izrael 5 milliárd dollárral növeli védelmi költségvetését a jövőbeni finanszírozás aggodalmai mellett","u":"https://breakingdefense.com/2026/11/israel-increases-defense-budget-by-5-billion-as-concerns-continue-over-future-funding/","d":"2026-11-25","x":"Izrael védelmi költségvetése 5 milliárd dollárral nőtt, amit a Védelmi Költségvetési Bizottság hagyott jóvá. A költségvetés növelése lehetővé teszi az IDF képességeinek megerősítését és a jövőbeni beszerzések előmozdítását, beleértve a légi védelem és a támadó helikopterek területét. A költségvetési növekedés azonban nem oldja meg a hosszú távú finanszírozási problémákat, amelyek 2027-ig elhúzódhatnak. A költségvetés emelését részben más minisztériumok költségvetéséből való átcsoportosítással finanszírozták. A védelmi miniszter hangsúlyozta, hogy folytatni fogják Izrael katonai fölényének biztosítását.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["Israel"],"p":8,"cm":1,"cid":15436,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Izrael védelmi költségvetésének növelése."},{"id":15438,"s":"Breaking Defense","sz":"T2","t":"The US is racing to fix its missile production challenge. Will it work, and can partners help?","th":"Az Egyesült Államok versenyt fut a rakéta gyártási kihívásának megoldásáért","u":"https://breakingdefense.com/2026/11/the-us-is-racing-to-fix-its-missile-production-challenge-will-it-work-and-can-partners-help/","d":"2026-11-25","x":"Az Egyesült Államoknak sürgősen meg kell oldania a rakéta gyártási kihívásait, mivel a globális kereslet a rakéták és rakétavédelmi rendszerek iránt folyamatosan növekszik. A Pentagon követelményeinek teljesítése érdekében az Egyesült Államoknak elegendő felszerelést kell előállítania, nem beszélve a külföldi partnerekről, akik az amerikai rendszerekre támaszkodnak. Bár vannak erőfeszítések a termelés növelésére, még mindig kérdések merülnek fel azzal kapcsolatban, hogy ez elegendő-e az ipar gyorsabb működésének elősegítésére. A cikk a rakéták és rakétavédelmek gyártási kihívásait elemzi.","dom":"AIR","br":"Rakéták és hiperszonikus fegyverek","sp":["Rakéták és hiperszonikus fegyverek","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":8,"cm":1,"cid":15438,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Az USA rakétagyártási kihívásai."},{"id":15452,"s":"The War Zone","sz":"T2","t":"Ship-Killing ARRW Hypersonic Missile Variant Struggling To Get Full Support From Lawmakers","th":"Hajógyilkos ARRW hiperszonikus rakéta változat nehezen kap támogatást a törvényhozóktól","u":"https://www.twz.com/air/ship-killing-arrw-hypersonic-missile-variant-struggling-to-get-full-support-from-lawmakers","d":"2026-11-25","x":"A Boeing által fejlesztett hajógyilkos ARRW hiperszonikus rakéta új változata, az ARRW Increment 2, nehezen kapja meg a szükséges támogatást a törvényhozóktól. Az Egyesült Államok Légierője 2027-es költségvetési javaslata 296,269 millió dollárt kér az ARRW Increment 2-re, de a szenátusi költségvetési bizottság jelentősen csökkentette a kért összeget. Az ARRW rakétát a B-52 és B-1 bombázókra integrálják, és a célja, hogy képes legyen mozgó célpontok, különösen ellenséges hadihajók megsemmisítésére. A hiperszonikus fegyverek fejlesztése kulcsfontosságú képesség a jövőbeli konfliktusokban, különösen Kína ellen. Az ARRW program sorsa az utóbbi években folyamatosan változott, és a közelmúltban a gyártás megkezdődött.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Rakéták és hiperszonikus fegyverek","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":15452,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. ARRW hiperszonikus rakéta támogatási nehézségei."},{"id":15453,"s":"The War Zone","sz":"T2","t":"China’s Cargo Drones Keep Getting Bigger With New W8000","th":"Kína új W8000 teherdrónja egyre nagyobbá válik","u":"https://www.twz.com/air/chinas-cargo-drones-keep-getting-bigger-with-new-w8000","d":"2026-11-25","x":"Kína ambíciói a nagyobb, pilóta nélküli teherrepülőgépek kifejlesztésére növekednek, a legújabb W8000 drón nyolc tonna teher szállítására lett tervezve. A W8000 a W5000 kisebb változatának bemutatása előtt debütált, amely már repülési teszteken van. A W8000 célja, hogy a hagyományos, legénységgel rendelkező szállító repülőgépek kategóriájába lépjen, és a Kínai Népi Felszabadító Hadsereg számára is jelentős légi szállítási lehetőségeket kínálhat. A drónok fejlesztése különösen fontos lehet a távoli területek logisztikájában és katonai szállítási feladatokban, ahol a hagyományos légiközlekedés nem mindig elérhető. A W8000 bemutatása a nagyobb pilóta nélküli teherrepülőgépek iránti kereslet növekedését is jelzi.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["China"],"p":8,"cm":1,"cid":15453,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Kína új teherdrón fejlesztése."},{"id":15517,"s":"DefenseScoop","sz":"T2","t":"Coast Guard’s updated Force Design plan includes Maven Smart System, other digital advancements","th":"A Parti Őrség frissített Haderőtervezési terve magában foglalja a Maven Smart Systemet és más digitális fejlesztéseket","u":"https://defensescoop.com/2026/11/25/coast-guard-force-design-update-digital-modernization/","d":"2026-11-25","x":"Az Egyesült Államok Parti Őrsége legújabb haderőtervezési frissítése tartalmazza a Maven Smart System mesterséges intelligencia eszközt, amelyet a Pentagon is elfogadott. A rendszer célja, hogy javítsa a felhasználók döntéshozatali képességeit, és gyorsabb, pontosabb döntéseket tegyenek. A frissített dokumentum szerint a Coastal Sentinel rendszer fejlesztése 2027-ben kezdődik, amely a tengeri domén tudatosság növelésére szolgál. A Parti Őrség emellett a Digitális Seabag technológia bevezetését is tervezi, amely mobil eszközöket biztosít a szolgálati tagok számára, hogy hatékonyabban végezhessék el feladataikat. A modernizációs erőfeszítésekhez 24,6 milliárd dolláros finanszírozás áll rendelkezésre, de további forrásokra is szükség lesz a jövőbeli fejlesztésekhez.","dom":"MAR","br":"Tengerészgyalogság és kétéltű erők","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":8,"cm":1,"cid":15517,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Parti Őrség új digitális fejlesztései."},{"id":15542,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"Pentagon Asks Congress for Stopgap Help with Golden Dome, MQ-9 Fleet","th":"A Pentagon sürgősségi segítséget kér a Kongresszustól a Golden Dome és az MQ-9 flottához","u":"https://www.airandspaceforces.com/pentagon-congress-help-with-golden-dome-mq-9/","d":"2026-11-25","x":"A Fehér Ház sürgősségi finanszírozást kér a Kongresszustól a Golden Dome rakétavédelmi program fenntartására, valamint az Air Force MQ-9 drónflottájának feltöltésére. A Pentagon figyelmeztetett, hogy a költségvetési korlátozások miatt a program nem kap új finanszírozást, ami veszélyezteti a működési képességeket. Az MQ-9 drónok elvesztése a konfliktusok során jelentős mértékben csökkentette a flotta kapacitását, és a Fehér Ház sürgeti a gyorsabb pénzkiadást a helyzet javítása érdekében. A Pentagon a Massed Modular Aircraft program gyorsítását tervezi, hogy alacsony költségű MQ-9 helyettesítőt fejlesszen ki, de ez évekbe telik. A helyzet sürgőssége miatt a Kongresszusnak gyors döntéseket kell hoznia a védelmi képességek fenntartása érdekében.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":15542,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Sürgősségi finanszírozás a Pentagon számára."},{"id":15544,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"Pentagon Elevates Air Force Program Using AI for Classification Decisions","th":"A Pentagon felemeli a Légierő programját, amely mesterséges intelligenciát használ a klasszifikációs döntésekhez","u":"https://www.airandspaceforces.com/pentagon-elevates-air-force-program-ai-classification/","d":"2026-11-25","x":"A Pentagon egy új Légierő programot indít, amely mesterséges intelligencia eszközöket alkalmaz a dokumentumok és adatok klasszifikációs szintjeinek meghatározására. A Battering Ram néven ismert kezdeményezés célja, hogy hatékonyabban kezelje a több mint 4000 biztonsági klasszifikációs útmutatót. Az ACME néven ismert rendszer automatikus munkafolyamatokat ígér, hogy felgyorsítsa a lassú, emberi erőforrást igénylő információbiztonsági folyamatokat. A program célja a klasszifikációs szintek meghatározásának megkönnyítése, ugyanakkor figyelmeztetéseket is megfogalmaznak a kibertámadások kockázataira. A Pentagon évente akár 15 milliárd dollárt is költ nyilvántartás-kezelésre, így a program jelentős költségmegtakarítást ígérhet.","dom":"AIR","br":"Légvédelem és rakétavédelem (IAMD)","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":8,"cm":1,"cid":15544,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új AI program a Légierő számára."},{"id":15554,"s":"Defense News","sz":"T2","t":"Czech jet engine maker eyes growing role as US supplier in drones, missiles","th":"Cseh jetmotor-gyártó növekvő szerepet kíván betölteni az Egyesült Államok beszállítói között drónokban és rakétákban","u":"https://www.defensenews.com/global/europe/2026/11/25/czech-jet-engine-maker-eyes-growing-role-as-us-supplier-in-drones-missiles/","d":"2026-11-25","x":"A cseh PBS Aerospace jetmotor-gyártó célja, hogy növelje amerikai gyártási kapacitását, legalább kétszeresére. A vállalat a drónok és cirkáló rakéták iránti növekvő kereslet miatt bővíti a termelést az Egyesült Államokban. A cég tervei között szerepel, hogy a Roswell-i üzemének éves termelését 10,000 és 20,000 motor közé emelje a következő három évben. A PBS Aerospace az amerikai piacra gyárt, és a Lockheed Martin és Pratt \u0026 Whitney cégekkel működik együtt. A növekvő kereslet kielégítése érdekében a cég körülbelül 100 millió dollárt kíván befektetni a kapacitás növelésére Roswellben.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Lőszer és védelmi ipari kapacitás"],"oc":["Czech Republic","United States"],"p":8,"cm":1,"cid":15554,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Cseh jetmotor-gyártó amerikai bővítése."},{"id":15574,"s":"Military Times","sz":"T2","t":"Air Force expands training with EARL, an AI-enhanced simulator","th":"A légierő bővíti a képzést az EARL, egy MI-támogatott szimulátor segítségével","u":"https://www.militarytimes.com/news/your-military/2026/11/25/air-force-expands-training-with-earl-an-ai-enhanced-simulator/","d":"2026-11-25","x":"Az Egyesült Államok Légierője célja, hogy csökkentse a képzési forgatókönyvek üzemanyagköltségeit egy virtuális valóság rendszeren keresztül, az Experiential Air Refueling Lightweight (EARL) szimulátorral. A rendszer, amelyet a Specular Theory fejlesztett ki, már nyolc operatív szárny és parancsnokság által alkalmazott, beleértve a Légierő Globális Ütőerejét és a Légierő Tartalék Parancsnokságot. Az EARL valósághű repülési környezetet teremt, amely lehetővé teszi a légi személyzet számára, hogy gyakorolja a légi utántöltést. A rendszer mesterséges intelligenciát használ a lépésről lépésre történő útmutatáshoz, és lehetővé teszi a pilóták számára, hogy valós időben együtt gyakoroljanak különböző virtuális repülőgépeken. Az Légierő szándéka, hogy tovább bővítse a szimulátorok használatát és fejlessze a szoftvereket magas nyomású harci forgatókönyvekhez.","dom":"AIR","br":"Légi szállítás és utántöltés","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":8,"cm":1,"cid":15574,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új MI-támogatott szimulátor a Légierő számára."},{"id":15103,"s":"RUSI","sz":"T1","t":"Russia's New Cruise Missiles and the Rapid Iteration Trap","th":"Oroszország új cirkálórakétái és a gyors iteráció csapdája","u":"https://www.rusi.org/explore-our-research/publications/commentary/russias-new-cruise-missiles-and-rapid-iteration-trap","d":"2026-11-25","x":"Oroszország új, jet-meghajtású mini cirkálórakétái felülmúlták Ukrajna olcsó interceptor drónjait. A gyors iteráció fontos, de a sebesség végső soron a hosszú évek alatt felépített szuverén mérnöki képességtől függ. Ukrajna jelentős átalakulást indított el a NATO beszerzési gondolkodásában, amelynek során a gyors szállítás és a platformok folyamatos fejlesztése vált a háború meghatározó tanulságává. Az orosz 'jet drónok' használata, amelyeket a Geran 2 képvisel, a gyors alkalmazkodás példájaként jelent meg, de valójában évek óta tartó katonai-ipari stratégiát tükröz. Az orosz mini cirkálórakéták és drónok folyamatos fejlesztése komoly kihívás elé állította Ukrajnát, amelynek válasza a költséghatékony megoldások keresése volt.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Rakéták és hiperszonikus fegyverek","Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Russia","Ukraine"],"p":8,"cm":1,"cid":15103,"sp2":45,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Általános elemzés az orosz rakéták és NATO beszerzési tanulságokról."},{"id":15254,"s":"OSW","sz":"T1","t":"Ukraine is launching attacks in the Baltic and the Mediterranean. Day 1735 of the war","th":"Ukrajna támadásokat indít a Balti-tengeren és a Földközi-tengeren","u":"https://www.osw.waw.pl/en/publikacje/analyses/2026-11-24/ukraine-launching-attacks-baltic-and-mediterranean-day-1735-war","d":"2026-11-24","x":"Ukrajna a Balti-tengeren és a Földközi-tengeren indít támadásokat. A háború 1735. napján az orosz erők fokozzák műveleteiket a Kramatorsk környékén, míg az ukrán ellentámadások a Dobropillia déli részén nagyrészt sikertelenek voltak. A legutóbbi orosz rakétatámadások során 122-123 ballisztikus és cirkáló rakétát használtak, amelyek közül többet sikerült megsemmisíteni. A támadások célpontjai között szerepeltek a kritikus infrastruktúrák, valamint a logisztikai és közlekedési létesítmények. A legfrissebb jelentések szerint a támadások következtében több ember életét vesztette, és jelentős károk keletkeztek az energiahálózatban és a közlekedési infrastruktúrában. Az ukrán erők folyamatosan próbálnak helyreállítani bizonyos területeket, miközben a harcok intenzitása továbbra is magas.","dom":"LAND","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Drónok és drónelhárítás","Lőszer és védelmi ipari kapacitás","Haderő-modernizáció és erőszerkezet"],"oc":["Ukraine","Russia","Poland"],"p":8,"cm":1,"cid":15254,"sp2":45,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Általános hír az ukrán támadásokról, kevés újdonsággal."},{"id":15325,"s":"War on the Rocks","sz":"T1","t":"The Contract Was the Easy Part: How Accelerator Day Put the Pentagon on the Clock","th":"A szerződés volt a könnyű rész: Hogyan tette az Accelerator Day a Pentagonot időnyomás alá","u":"https://warontherocks.com/cogs-of-war/the-contract-was-the-easy-part-how-accelerator-day-put-the-pentagon-on-the-clock/","d":"2026-11-25","x":"A Pentagon sürgősséget követel az ipartól, miközben saját döntései elhúzódnak. Az Accelerator Day célja, hogy a kormányt határidő alá vonja, és felelőssé tegye a következő lépésekért. A rendezvény során 15 döntős kapott támogatást, és a cél az volt, hogy gyorsabb módokat találjanak a kereskedelmi technológiák értékelésére. Az esemény tapasztalatai rávilágítanak arra, hogy a kormány képes-e fenntartani a sürgősséget a rendezvény után is, amikor a koordináció nehézzé válik. A gyors döntéshozatal elengedhetetlen a haditechnikai fejlesztések sikeréhez.","dom":"MDO","br":"Különleges műveleti erők","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":15325,"sp2":45,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Általános elemzés a Pentagon és ipar kapcsolatáról."},{"id":15580,"s":"Military Times","sz":"T2","t":"AI models easily coaxed into identifying military targets, study finds","th":"AI modellek könnyen rávehetők katonai célpontok azonosítására, állítja egy tanulmány","u":"https://www.militarytimes.com/news/your-military/2026/11/25/ai-models-easily-coaxed-into-identifying-military-targets-study-finds/","d":"2026-11-25","x":"Egy új jelentés szerint a mesterséges intelligencia modellek nem rendelkeznek megfelelő védelmi mechanizmusokkal, amelyek megakadályoznák őket abban, hogy katonai célpontokat azonosítsanak képek alapján. A kutatók 14 különböző modellt teszteltek, és megállapították, hogy a modellek többsége, ha játék formájában kérdezték őket, hajlandó volt katonai célpontokat megnevezni, beleértve civileket és mentőautókat is. A kutatás során a modellek a valóságból származó és mesterségesen generált képeket is nehezen tudták megkülönböztetni. A kutatók hangsúlyozták, hogy a megfelelő védelmi intézkedések hiánya súlyos kockázatokat jelenthet az autonóm fegyverek fejlesztésében. A jelentés javasolja, hogy a cégek vezessenek be automatikus szűrőket a katonai célpontokkal kapcsolatos kérések kezelésére.","dom":"CYB","br":"Híradó és informatikai csapatok","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Iran"],"p":8,"cm":1,"cid":15580,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. AI modellek katonai célpontok azonosítására."},{"id":15264,"s":"ASPI The Strategist","sz":"T1","t":"For its own good, Australia should help strengthen the US nuclear umbrella","th":"Ausztráliának segítenie kellene az Egyesült Államok nukleáris védőernyőjének megerősítésében","u":"https://www.aspistrategist.org.au/for-its-own-good-australia-should-help-strengthen-the-us-nuclear-umbrella/","d":"2026-11-26","x":"Ausztrália elrettentési stratégiája hiányos, mivel nem veszi figyelembe a lehetséges kínai nukleáris fenyegetést. Az ország számára fontos, hogy megerősítse az Egyesült Államok nukleáris védőernyőjét, hogy elriassza Kínát. A cikk hangsúlyozza, hogy Ausztráliának aktívan részt kell vennie a nukleáris elrettentési stratégiák koordinálásában szövetségeseivel, és nyíltan támogatnia kell az amerikai nukleáris erőket. A nukleáris elrettentés kérdése már nem csak mások ügye, Ausztráliának is foglalkoznia kell vele.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Nukleáris elrettentés","Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Australia","China","United States"],"p":8,"cm":1,"cid":15264,"sp2":32,"ind":"Jelentőség 1/5, újdonság 1/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Politikai vélemény Ausztrália elrettentési stratégiájáról."},{"id":15479,"s":"Naval News","sz":"T2","t":"Elbit to Supply Aqua Marine EW Suite for Germany’s F128 Frigates","th":"Elbit Aqua Marine elektronikai harcászati rendszert szállít a német F128 fregattokhoz","u":"https://www.navalnews.com/naval-news/2026/11/elbit-to-supply-aqua-marine-ew-suite-for-germanys-f128-frigates/","d":"2026-11-25","x":"Az Elbit Systems Deutschland Aqua Marine elektronikai harcászati rendszert szállít a TKMS F128 fregattjaihoz. A német védelmi beszerzési hatóság, a BAAINBw által aláírt második tétel keretében a rendszer a sűrű tengeri elektromágneses környezetekhez lett tervezve, támogatva a fenyegetés figyelmeztetést, elektronikus hírszerzési gyűjtést és a haditengerészeti platformok közötti interoperabilitást. Az Aqua Marine moduláris felépítése lehetővé teszi az elektronikai támogatás és a ellentámadási elemek testreszabását az egyes hajók követelményeihez. A rendszer 360 fokos azonnali lefedettséget és automatikus emitter azonosítást biztosít, valamint képes a radarjelek hosszú távú észlelésére is.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Germany"],"p":8,"cm":1,"cid":15479,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Német fregattok új elektronikai rendszert kapnak."},{"id":15476,"s":"Naval News","sz":"T2","t":"Italian Navy’s First ‘Full’ PPA Giovanni delle Bande Nere Demonstrates BMD Capabilities","th":"Az olasz haditengerészet első 'teljes' PPA hajója, a Giovanni delle Bande Nere bemutatja a BMD képességeit","u":"https://www.navalnews.com/naval-news/2026/11/italian-navy-bmd-ppa-bande-nere/","d":"2026-11-25","x":"Az olasz haditengerészet első 'teljes' MPCS/PPA hajója, a Giovanni delle Bande Nere, sikeresen észlelte, nyomkövette és elfogta a ballisztikus fenyegetést. A hajó a Thaon di Revel-osztály negyedik egysége, amely az Aster 30 rakétát használta a ballisztikus rakéta elfogására. Ez a sikeres művelet a hajó hat hónapos indopacifikus hadműveleti bevetése során zajlott, és az olasz haditengerészetet a ballisztikus fenyegetések tengerből történő kezelésére képes haditengerészetek elit csoportjába emeli. A hajó a legújabb harci és fegyverrendszer-képességekkel rendelkezik, beleértve az integrált légvédelmi és rakétavédelmi rendszereket is. A sikeres elfogás a hajó legújabb technológiáinak és a legmagasabb szintű hadműveleti tervezésnek köszönhető.","dom":"MAR","br":"Felszíni harci hajók","sp":["Rakéták és hiperszonikus fegyverek","Haderő-modernizáció és erőszerkezet"],"oc":["Italy"],"p":9,"cm":1,"cid":15476,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új képesség bemutatása az olasz haditengerészet számára."},{"id":15543,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"Air Force Gives Boeing $2.8B Contract for More KC-46s, as Price Rises","th":"Légierő 2,8 milliárd dolláros szerződést ad a Boeingnek több KC-46 tankert vásárlására","u":"https://fonts.googleapis.com","d":"2026-11-25","x":"Az Egyesült Államok Légierője 2,82 milliárd dolláros szerződésmódosítást adott a Boeing Defense, Space and Security számára, hogy 15 új KC-46A Pegasus légi utántöltő tankert vásároljon. A KC-46 ára több mint 14%-kal emelkedett az utolsó szerződés 2025-ös megkötése óta. A fejlesztés a légierő modernizációs törekvéseinek része.","dom":"AIR","br":"Légi szállítás és utántöltés","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":7,"cm":5,"cid":15437},{"id":15565,"s":"Army Technology","sz":"T2","t":"US Army seeks contractors for Middle East bunkers","th":"Az Egyesült Államok hadserege vállalkozókat keres a közel-keleti bunkerekhez","u":"https://www.army-technology.com/news/us-army-seeks-contractors-for-middle-east-bunkers/","d":"2026-11-25","x":"Az Egyesült Államok hadserege 17 előregyártott betonbunker építésére keres vállalkozókat Szaúd-Arábiában, Izraelben és Libanonban, hogy védelmet nyújtson az amerikai és szövetséges személyzet számára. A bunkerek standardizált egységek, amelyek a nem megfelelő menedékhelyeket és szállítókonténereket váltják fel. A szerződések 45 napos teljesítési időtartamot tartalmaznak, és a kivitelezőknek a tervezési szakaszok során be kell nyújtaniuk a terveiket. Az építkezés célja a fokozott regionális fenyegetések elleni védelem megerősítése.","dom":"LAND","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","Beszerzés és védelmi költségvetés"],"oc":["United States","Saudi Arabia","Israel","Lebanon"],"p":7,"cm":1,"cid":15565},{"id":14223,"s":"House of Commons Library","sz":"T1","t":"Timeline of British military assistance to Ukraine (2022 to present)","th":"A brit katonai segítségnyújtás idővonala Ukrajnának (2022-től napjainkig)","u":"https://commonslibrary.parliament.uk/research-briefings/cbp-9914/","d":"2026-11-24","x":"A cikk a brit katonai segítségnyújtás idővonalát mutatja be Ukrajnának 2022-től napjainkig. Részletezi, hogy milyen katonai támogatást nyújt az Egyesült Királyság Ukrajnának a konfliktus során. A brit haderő modernizációs és beszerzési intézkedései kiemelt szerepet játszanak a támogatásban. A cikk célja, hogy átfogó képet adjon a brit katonai hozzájárulásról és annak hatásairól.","dom":"LAND","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","Beszerzés és védelmi költségvetés"],"oc":["United Kingdom","Ukraine"],"p":7,"cm":1,"cid":14223},{"id":14317,"s":"Atlantic Council","sz":"T1","t":"The Coast Guard offers a model for defending US critical infrastructure against cyberattacks","th":"A Parti Őrség modellje az Egyesült Államok kritikus infrastruktúrájának védelmére a kibertámadások ellen","u":"https://www.atlanticcouncil.org/dispatches/the-coast-guard-offers-a-model-for-defending-us-critical-infrastructure-against-cyberattacks/","d":"2026-11-24","x":"A Parti Őrség egyre fontosabb szerepet játszik az Egyesült Államok kibervédelmében, különösen a tengeri szállítási szektorban. A cikk bemutatja, hogy a kibertámadások célpontjai lehetnek a hajók és a kikötők, amelyek működését komolyan veszélyeztethetik. A Parti Őrség már több mint egy évtizede erősíti kibervédelmi képességeit, és szoros együttműködést alakított ki a tengeri iparággal. A 2025-ös szabályozások kötelező kibervédelmi terveket írnak elő az amerikai zászló alatt közlekedő hajók számára. A cikk hangsúlyozza, hogy a kibervédelem közös felelősség, és a kormányzati és magánszektor közötti információmegosztás erősítése elengedhetetlen a hatékony védelem érdekében.","dom":"CYB","br":"Híradó és informatikai csapatok (CIS)","sp":["Vezetés-irányítás és ISR (C2/ISR)","MI és autonómia"],"oc":["United States"],"p":8,"cm":1,"cid":14317,"sp2":53,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Kibervédelmi szerep növekedése, de nem új információ."},{"id":14318,"s":"Atlantic Council","sz":"T1","t":"Ukraine is now a drone superpower at sea, on land, and in the air","th":"Ukrajna most drónszuperhatalom a tengeren, a szárazföldön és a levegőben","u":"https://www.atlanticcouncil.org/blogs/ukrainealert/ukraine-is-now-a-drone-superpower-at-sea-on-land-and-in-the-air/","d":"2026-11-24","x":"Ukrajna drónszuperhatalommá vált a tengeren, a szárazföldön és a levegőben. A közelmúltban ukrán tengeri drónok sikeresen támadtak meg orosz hadihajókat, demonstrálva Ukrajna növekvő katonai képességeit. A dróntechnológiák gyors fejlődése lehetővé tette, hogy Ukrajna hatékonyan reagáljon Oroszország katonai fölényére. Az ukrán drónipar robbanásszerű növekedése és a drónok innovatív használata a harctéren új megközelítéseket hozott a modern hadviselésben. A hosszú hatótávolságú drónok stratégiai bombázási kampányokat folytatnak Oroszország területén, jelentős hatással a háború alakulására.","dom":"MDO","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Ukraine","Russia"],"p":9,"cm":1,"cid":14318,"sp2":66,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Ukrajna drónképességei jelentősek, de a hír nem teljesen új."},{"id":14538,"s":"ASPI The Strategist","sz":"T1","t":"American scandal: Nvidia chips away at our national security","th":"Amerikai botrány: Az Nvidia veszélyezteti nemzeti biztonságunkat","u":"https://www.aspistrategist.org.au/american-scandal-nvidia-chips-away-at-our-national-security/","d":"2026-11-25","x":"Az Nvidia vezérigazgatójának, Jensen Huang-nak a visszaállítása nem csupán vállalati ügy, hanem nemzeti biztonsági fenyegetés is. A cikk rávilágít arra, hogy a cég kereskedelmi érdekei hogyan befolyásolják az Egyesült Államok nemzeti biztonsági döntéseit, különösen Kínával kapcsolatban. Az Nvidia által gyártott fejlett chipek Kínába történő exportja hozzájárulhat a kínai katonai modernizációhoz, kibertámadási képességekhez és mesterséges intelligencia fejlesztésekhez. A helyzet komolyságát tükrözi, hogy a kongresszus vizsgálatokat indított az exportellenőrzések megszegése miatt. Az Egyesült Államoknak fel kell ismernie a technológiai és katonai fölényének megőrzését célzó stratégiáját, és meg kell akadályoznia, hogy a kereskedelmi érdekek aláássák ezt a célt.","dom":"CYB","br":"Híradó és informatikai csapatok","sp":["Kiberműveletek","MI és autonómia"],"oc":["United States","China","Australia","United Kingdom"],"p":8,"cm":1,"cid":14538,"sp2":45,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Politikai kommentár Nvidia szerepéről, nem technikai hír."},{"id":14540,"s":"ASPI The Strategist","sz":"T1","t":"To help themselves and US, Australia and Japan should service missiles together","th":"Ausztráliának és Japánnak közösen kellene karbantartania a rakétákat","u":"https://www.aspistrategist.org.au/to-help-themselves-and-us-australia-and-japan-should-service-missiles-together/","d":"2026-11-25","x":"Ausztráliának és Japánnak közös létesítményt kellene létrehoznia a rakéták karbantartására, amely erősítené katonai műveleteik fenntartásának képességét és fokozná a Kínával szembeni elrettentést. A létesítmény a Raytheon SM-2 és SM-6 tengeri rakéták karbantartására összpontosítana, és segítene enyhíteni az Egyesült Államok ipari terheit. A közös karbantartási központ létrehozása a három ország közötti együttműködést is erősítené, és hozzájárulna a szövetségesek rakétakészleteinek fenntartásához. A központ létrehozása sürgető, mivel a közeljövőben az Egyesült Államok védelmi termelése korlátozott. A létesítmény a földrajzi távolságot operatív készenlétre és stratégiai tartósságra fordíthatja.","dom":"MDO","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Lőszer és védelmi ipari kapacitás","Haderő-modernizáció és erőszerkezet"],"oc":["Australia","Japan","United States"],"p":8,"cm":1,"cid":14540,"sp2":53,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Közös karbantartási javaslat, de még nem megvalósult."},{"id":14599,"s":"War on the Rocks","sz":"T1","t":"Battlefield Power Is Running Short","th":"A harctéri energiaforrások kimerülése","u":"https://warontherocks.com/cogs-of-war/battlefield-power-is-running-short/","d":"2026-11-24","x":"A modern hadviselés során a drónok, drónelhárító rendszerek, elektronikus hadviselés és a perem számítási technológiák mind energiaigényesek. A katonák számára egyre több energiára van szükségük, távolabb a hagyományos ellátási vonalaiktól. A cikkben a hadsereg energiaellátásának jövőbeli megoldásait, a közös energia szabványok iránti igényt és a szoftverek szerepét vizsgálják az energia kezelésében. A cél, hogy a parancsnokok az energiát hasonlóan kezeljék, mint a lőszert, és bemutatják, hogy egy jól működő zászlóalj hogyan közelítheti meg az energiaellátást öt év múlva.","dom":"LAND","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Drónok és drónelhárítás","MI és autonómia"],"oc":["United States"],"p":7,"cm":1,"cid":14599},{"id":14712,"s":"Breaking Defense","sz":"T2","t":"UK’s MI5 warns local defense firms of Russian sabotage risk","th":"Az MI5 figyelmezteti a brit védelmi cégeket az orosz szabotázs kockázatára","u":"https://breakingdefense.com/2026/11/uks-mi5-warns-local-defense-firms-of-russian-sabotage-risk/","d":"2026-11-24","x":"A brit MI5 hírszerző ügynökség figyelmeztetést adott ki a brit védelmi cégek és a katonai segélyt nyújtó helyi beszállítók számára, hogy orosz szabotázs és gyújtogatás támadások célpontjaivá válhatnak. Az ügynökség közleménye szerint Oroszország fokozta a szabotázs kísérleteit európai védelmi létesítmények ellen, amelyeket alacsony szintű szabotázs módszerekkel, például gyújtogatással hajtanak végre. A figyelmeztetés hangsúlyozza, hogy a katonai beszerzést támogató szervezetek potenciális célpontokká válhatnak, és sürgeti az ipart, hogy csökkentse a támadók számára elérhető információkat és javítsa a biztonsági intézkedéseket.","dom":"COG","br":"Híradó és informatikai csapatok (CIS)","sp":["Információs műveletek és dezinformáció","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United Kingdom","Ukraine","Russia","Estonia","Germany"],"p":7,"cm":1,"cid":14712},{"id":14713,"s":"Breaking Defense","sz":"T2","t":"The Army has told us how it fights. We can’t do that in an analog tank.","th":"A hadsereg elmondta, hogyan harcol. Ezt nem tudjuk analóg tankban megtenni.","u":"https://breakingdefense.com/2026/11/the-army-has-told-us-how-it-fights-we-cant-do-that-in-an-analog-tank/","d":"2026-11-24","x":"A hadsereg közzétette, hogyan harcol, amely négy alapelvre épít: konvergencia, csapás, közeli harc és kitartás, mindez egy többdomainű (MDO) környezetben. Az M1E3 tank, amely a hadsereg új harci irányelveinek megfelelően készült, jelentős fejlesztéseket ígér, beleértve az integrált aktív védelmi rendszert és a moduláris nyílt rendszerek architektúráját. A tank súlyának csökkentése és a hibrid dízel-elektromos hajtáslánc bevezetése lehetővé teszi a fenntarthatóság javítását és a harci képességek fokozását. Az M1E3 célja, hogy a tank ne csak egy önálló egység legyen, hanem egy hálózati csomópont, amely gyorsan reagál a harctéri eseményekre.","dom":"LAND","br":"Harckocsizó (páncélos) csapatok","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás","Lőszer és védelmi ipari kapacitás"],"oc":["United States"],"p":9,"cm":1,"cid":14713,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új tankfejlesztés részletei, de nem teljesen új információ."},{"id":14714,"s":"Breaking Defense","sz":"T2","t":"Investment firm Cerberus to buy space business of US Airbus arm","th":"A Cerberus befektetési cég megvásárolja az Airbus amerikai űripari üzletágát","u":"https://breakingdefense.com/2026/11/investment-firm-cerberus-to-buy-space-business-of-us-airbus-arm/","d":"2026-11-24","x":"A Cerberus Capital Management bejelentette, hogy megvásárolja az Airbus U.S. Space \u0026 Defense űripari üzletágát az év végéig. Az Airbus Space Systems Floridában található létesítményeiben gyárt műholdakat. A Cerberus célja, hogy fejlessze az űripari üzletág mérnöki szervezetét és termékportfólióját, valamint az amerikai ellátási láncot, hogy egy vezető, független amerikai tulajdonú műholdplatformot építsenek. A volt Űrerő vezető, Jay Raymond hangsúlyozta az űr fontosságát az Egyesült Államok és szövetségesei nemzetbiztonsága szempontjából. Az Airbus U.S. az autonóm repülőgépek képességeinek bővítésére összpontosít, hogy reagálni tudjon a védelmi piacon megjelenő új lehetőségekre.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Világűr- és műholdképességek"],"oc":["United States"],"p":8,"cm":1,"cid":14714,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Űripari üzletág eladása, de nem technológiai újdonság."},{"id":14715,"s":"Breaking Defense","sz":"T2","t":"White House seeks funding exemptions for Golden Dome, Trump battleship in next funding stopgap","th":"Fehér Ház finanszírozási kivételeket kér a Golden Dome és Trump csatahajó számára","u":"https://breakingdefense.com/2026/11/white-house-seeks-funding-exemptions-for-golden-dome-trump-battleship-in-next-funding-stopgap/","d":"2026-11-24","x":"A Fehér Ház a Golden Dome és a Trump-osztályú csatahajó számára kér finanszírozási kivételeket, hogy további pénzt vagy más hatásköröket biztosítson, ha a Kongresszus elfogad egy újabb átmeneti finanszírozási törvényt. A Golden Dome program számára 5 milliárd dollárt kérnek, mivel a jelenlegi finanszírozási keret alatt nincs új pénz. A Pentagon célja a fegyvergyártás felgyorsítása, amelyet a kivételek nélkül késlekedések fenyegetnek. A Fehér Ház figyelmeztetett, hogy a munitions programok késlekedései magasabb egységköltségeket eredményezhetnek, csökkentve a vásárlóerőt. A Trump-osztályú csatahajó fejlesztéséhez is kérnek előzetes beszerzési hatásköröket, hogy elkerüljék a késedelmeket és a költségnövekedést.","dom":"MAR","br":"Felszíni harci hajók","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":14715,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Politikai finanszírozási kérés, nem technikai hír."},{"id":14716,"s":"Breaking Defense","sz":"T2","t":"How a small Army team built a lightweight battle planning app: Odin","th":"Hogyan épített egy kis hadsereg csapat egy könnyűsúlyú harci tervező alkalmazást: Odin","u":"https://breakingdefense.com/2026/11/how-a-small-army-team-built-a-lightweight-battle-planning-app-odin/","d":"2026-11-24","x":"Az Odin nevű taktikai tervező alkalmazás célja, hogy a térképadatokat színkódolt ábrázolásokká alakítsa, amelyek megmutatják a járható terepet, a tilos zónákat és az akadályokat. Az alkalmazás az amerikai hadsereg C5ISR központjában készült, és a célja, hogy hidat képezzen a magasabb szintű tervezési képességek és a harci egységek szintje között. Az Odin integrálva van a hadsereg hivatalos harci hálózati programjába, és a jövőbeni frissítések során a csapat célja, hogy továbbfejlessze a funkciókat, beleértve az AI-alapú javaslatokat is a biztonságos útvonalak és a manőverezési tervek kidolgozásához. Az alkalmazás lehetővé teszi a frontvonalbeli csapatok számára, hogy elektronikus úton cseréljék ki a részletes parancsokat és térképi grafikákat.","dom":"MDO","br":"Híradó és informatikai csapatok (CIS)","sp":["Vezetés-irányítás és ISR (C2/ISR)","MI és autonómia"],"oc":["United States"],"p":8,"cm":1,"cid":14716,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új taktikai alkalmazás fejlesztése, de nem áttörés."},{"id":14719,"s":"Breaking Defense","sz":"T2","t":"LaNeve’s campaign plan aims for top-down guidance, flipping ‘transformation in contact’ era","th":"LaNeve kampányterve a felsőbb szintű irányításra összpontosít, megfordítva a 'kapcsolatban történő átalakulás' korszakát","u":"https://breakingdefense.com/2026/11/laneves-campaign-plan-aims-for-top-down-guidance-flipping-transformation-in-contact-era/","d":"2026-11-24","x":"Christopher LaNeve tábornok, az amerikai hadsereg vezetője, a 'Fighting Army' kampányterv bevezetésével a felsőbb szintű irányításra helyezi a hangsúlyt, elmozdulva a korábbi 'Folyamatos Átalakulás' koncepciótól. Az új irányelv célja, hogy egységesítse a hadsereg harci és kiképzési megközelítését, biztosítva a különböző szintek közötti összhangot. A 'Fighting Army' kampányterv a hadsereg hivatalos irányelve lesz, amely a modernizáció és kísérletezés új megközelítését képviseli. A cél, hogy a hadsereg elkerülje a statikus hadviselést, és a közelharci műveletekre összpontosítson. Az új irányelv bevezetése a hadsereg átalakulásának fontos lépése, amely a jövőbeli harci képességek fejlesztését célozza meg.","dom":"LAND","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":8,"cm":1,"cid":14719,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Vezetési irányelv változás, nem technikai hír."},{"id":14729,"s":"The War Zone","sz":"T2","t":"FireAnt Mini Uncrewed Ground Vehicles Deploy Drone Detection Sensors In U.S. Army Test","th":"FireAnt Mini Pilóta Nélküli Földi Járművek Drónészlelő Szenzorokat Telepítenek az Egyesült Államok Hadseregének Tesztjén","u":"https://www.twz.com/land/fireant-mini-uncrewed-ground-vehicles-deploy-drone-detection-sensors-in-u-s-army-test","d":"2026-11-24","x":"A FireAnt pilóta nélküli földi járművet (UGV) használtak drónészlelő szenzorok telepítésére egy nemrégiben végrehajtott amerikai hadsereg tesztgyakorlat során. Az UGV-k gyorsan létrehozhatnak helyi szenzorhálózatokat, amelyek növelhetik a hadsereg egységeinek helyzetfelismerését a levegőben és a földön jelentkező potenciális fenyegetésekkel kapcsolatban. A teszt célja a félautonóm képességek értékelése volt, amelyek kiterjesztik a C-UAS (ellen-drón rendszerek) lefedettségét. A FireAntok képesek lehetnek a földi szenzorok telepítésére, amelyek segíthetnek a drónfenyegetések észlelésében, valamint a harci helyzetek kezelésében. A teszt során a szenzorok különböző módokon képesek lehetnek a drónok észlelésére, beleértve a passzív jelek érzékelését is.","dom":"LAND","br":"Felderítő csapatok (RSTA)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["United States","Morocco"],"p":8,"cm":1,"cid":14729,"sp2":65,"ind":"Jelentőség 4/5, újdonság 4/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új UGV teszt, jelentős fejlemény."},{"id":14752,"s":"Naval News","sz":"T2","t":"U.S. Navy Taps Raytheon to Advance SLCM-N Nuclear Cruise Missile","th":"Az Egyesült Államok Haditengerészete a Raytheont választotta az SLCM-N nukleáris cirkálórakéta fejlesztésére","u":"https://www.navalnews.com/naval-news/2026/11/u-s-navy-taps-raytheon-to-advance-slcm-n-nuclear-cruise-missile/","d":"2026-11-24","x":"Az Egyesült Államok Haditengerészete szerződést kötött a Raytheonnal a Nukleáris Fegyverrel Felszerelt Tengeralattjáróról Indítható Cirkálórakéta (SLCM-N) fejlesztésének előmozdítására. A szerződés keretében a Raytheon fejlett technológiai csapata a korai koncepciótól a fejlesztési fázisra lép, amely magában foglalja a rendszer tervezésének érését és a kulcsfontosságú alrendszerek integrálását. A Raytheon munkája az SLCM-N-en a vállalat ipari bázisának bővítését is tükrözi, hogy gyorsan szállíthasson fejlett képességeket. A fejlesztés célja a nukleáris elrettentés megerősítése és a felmerülő fenyegetésekre való válaszlehetőségek bővítése.","dom":"MAR","br":"Tengeralattjárók","sp":["Rakéták és hiperszonikus fegyverek","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":14752,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új nukleáris rakéta fejlesztése, de még korai fázis."},{"id":14753,"s":"Naval News","sz":"T2","t":"Bayraktar AKINCI Conducts First ORKA Torpedo Release Test","th":"Bayraktar AKINCI első ORKA torpedó tesztje","u":"https://www.navalnews.com/naval-news/2026/11/bayraktar-akinci-conducts-first-orka-torpedo-release-test/","d":"2026-11-24","x":"A Baykar Bayraktar AKINCI pilóta nélküli harci repülőgép sikeresen végrehajtotta az ORKA következő generációs könnyű torpedó levegőből történő indítási tesztjét. A teszt során az AKINCI a törökországi Çorlu repülési és teszt központból emelkedett a levegőbe, és a torpedót a Saros-öbölben biztonságosan elengedte. Az ORKA torpedó a tengeralattjárók elleni harcra lett kifejlesztve, és a teszt fontos lépés a platform-fegyver integráció terén. A teszt eredményei azt mutatják, hogy a pilóta nélküli repülőgépek szerepe a tengeri hadviselésben egyre bővül, különösen a hosszú távú felderítési és megfigyelési feladatok mellett.","dom":"MAR","br":"Tengeri pilóta nélküli rendszerek","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás"],"oc":["Turkey"],"p":8,"cm":1,"cid":14753,"sp2":65,"ind":"Jelentőség 4/5, újdonság 4/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új torpedó teszt, jelentős fejlemény."},{"id":14754,"s":"Naval News","sz":"T2","t":"Blacksword Barracuda: An Attack Submarine to Deliver Operational Superiority","th":"Blacksword Barracuda: Egy támadó tengeralattjáró az operatív fölényért","u":"https://www.navalnews.com/features/2026/11/naval-group-blacksword-barracuda-submarine-greece/","d":"2026-11-24","x":"A Naval Group bemutatta legújabb támadó tengeralattjáró-tervét, a Blacksword Barracuda-t, amelyet a 2026-os Euronavalon mutattak be. A tengeralattjáró a holland Orka-osztályú program keretében került kiválasztásra, és most Görögországnak is ajánlják. A Blacksword Barracuda a hagyományos meghajtású tengeralattjárók közé tartozik, és több küldetésre is alkalmas, beleértve a tengeralattjáró-elhárítást, hajóelhárítást, mélycsapást és hírszerzést. A tengeralattjáró 82 méter hosszú, 35 fős legénységgel üzemel, és akár 30 nehézfegyvert is képes szállítani. A Naval Group a tengeralattjáróhoz lítium-ion akkumulátorokat kínál, amelyek előnyösek a hagyományos ólom-sav akkumulátorokkal szemben. A Blacksword Barracuda a görög haditengerészet új tengeralattjáró-programjának keretében válhat a régió tengeri ellenőrzésének támogatására alkalmas fejlett, több küldetésre is képes tengeralattjáróvá.","dom":"MAR","br":"Tengeralattjárók","sp":["Hajóépítés és haditengerészet","Lőszer és védelmi ipari kapacitás"],"oc":["Greece","France","Netherlands"],"p":8,"cm":1,"cid":14754,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új tengeralattjáró bemutatása, de még nem rendszeresítve."},{"id":14762,"s":"Defense One","sz":"T2","t":"Program looks to build shipbuilding, defense manufacturing capability in Hawaii","th":"Program a hajóépítési és védelmi gyártási képességek fejlesztésére Hawaiin","u":"https://www.defenseone.com/business/2026/11/program-looks-build-shipbuilding-defense-manufacturing-capability-hawaii/417440/","d":"2026-11-24","x":"A Pentagon által finanszírozott munkaerő-fejlesztési program a Honolulu Community College-ban célja a hawaii gyártási ipar következő generációs vezetőinek képzése és a csendes-óceáni védelmi ipari bázis növelése. A program keretében a hallgatók különböző gyártási folyamatokat tanulnak meg, beleértve a modellek, például az 'USS Aloha' tengeralattjáró alkatrészeinek elkészítését is. A program 7 millió dolláros befektetéssel indult, és a helyi igényekhez igazított tantervet alkalmaz. A cél, hogy a helyi munkaerő képzése révén támogassák a Pearl Harbor-i haditengerészeti bázis növekvő munkaerőigényét.","dom":"MAR","br":"Hajóépítés és haditengerészet","sp":["Hajóépítés és haditengerészet","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":8,"cm":1,"cid":14762,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Oktatási program, nem közvetlen haditechnikai hír."},{"id":14796,"s":"DefenseScoop","sz":"T2","t":"Space Systems Command eyes mid-2028 for GPS sustainment upgrade contract","th":"A Space Systems Command 2028 közepére tervezi a GPS fenntartási frissítési szerződést","u":"https://defensescoop.com/2026/11/24/space-systems-command-gps-sustainment-upgrade-contract/","d":"2026-11-24","x":"A Space Force 2028 közepét jelölte meg a következő generációs GPS fenntartási szolgáltatások tervezett odaítélési időpontjaként egy ötéves szerződés keretében. A szolgáltatás célja, hogy olyan beszállítókat találjon, akik képesek fenntartani a hagyományos GPS földi rendszereket, miközben folyamatosan frissítéseket is végeznek a modernizált űrhajók üzembe állításával. A SPIDER díj a GPS Control Segment Sustainment II (GCS II) szerződés utódja lesz, amelyet először 2019-ben adtak át a Lockheed Martin-nak. A fenntartási rendszernek együtt kell működnie a következő generációs műholdakkal, mint például a GPS III follow-on (GPS IIIF).","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Világűr- és műholdképességek","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":8,"cm":1,"cid":14796,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. GPS frissítési szerződés tervezése, de még nem végleges."},{"id":14820,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"First All-Guardian Squadron Graduates Officer Training School, Enters Space Force","th":"Első All-Guardian Század Diplomázott az Tiszti Kiképző Iskolán, Belép a Űrerőbe","u":"https://www.airandspaceforces.com/space-forces-first-all-guardian-class-graduates-officer-training-school/","d":"2026-11-24","x":"2026. november 20-án diplomázott az első tiszti kiképző iskolai század, amely kizárólag az Egyesült Államok Űrerőjének új tisztjelöltjeiből állt. A 'Wolfpack Század' 36 új Űrőrt nevelt ki, ezzel tovább bővítve az Űrerő saját képzési kereteit. Az Űrerő évente körülbelül 100 tisztet képez ki, és a létszám várhatóan 25,000 főre nő. A Wolfpack diplomások számára a következő lépés az Űrerő Tiszti Kiképző Tanfolyama lesz, amely 12 hónapos program keretében készíti fel őket az intelligencia, űr és kiberműveletek területén. A Space Force folyamatosan bővíti képzési kapacitásait, hogy megfeleljen a növekvő igényeknek.","dom":"SPA","br":"Világűr- és műholdképességek","sp":["Haderő-modernizáció és erőszerkezet","MI és autonómia"],"oc":["United States"],"p":8,"cm":1,"cid":14820,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új Űrerő tisztek diplomázása, de nem technológiai hír."},{"id":14823,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"Air Force Signs $48.7M Deal for Weather Data from ‘Balloons with Brains’","th":"Légierő 48,7 millió dolláros megállapodást kötött az időjárási adatokért \"agyú ballonokkal\"","u":"https://www.airandspaceforces.com/air-force-deal-weather-data-autonomous-balloons/","d":"2026-11-24","x":"A Légierő nemrégiben közel 50 millió dolláros szerződést írt alá a Windborne Systems Inc.-el, amely lehetővé teszi az autonóm, hosszú távú időjárási ballonok gyors és olcsó indítását. A megállapodás célja a globális és célzott légköri adatok folyamatos gyűjtése, amely javítja az időjárási modellezést és a helyzetértékelést. A Windborne ballonok akár 21 napig is a levegőben maradhatnak, és képesek az atmoszféra különböző rétegeiben mozogni, így gazdagabb adatokat szolgáltatnak. A Légierő várakozásai szerint a ballonok használata csökkenti az észlelési hiányosságokat és javítja az időjárási körülmények megértését, különösen vitatott környezetekben.","dom":"AIR","br":"Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)","sp":["Vezetés-irányítás és ISR (C2/ISR)","Lőszer és védelmi ipari kapacitás"],"oc":["United States"],"p":8,"cm":1,"cid":14823,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új időjárási ballon szerződés, de nem áttörés."},{"id":14828,"s":"Defense News","sz":"T2","t":"Ford in talks with the Pentagon to supply military vehicles","th":"Ford tárgyalásokat folytat a Pentagon számára katonai járművek szállításáról","u":"https://www.defensenews.com/pentagon/2026/11/24/ford-in-talks-with-the-pentagon-to-supply-military-vehicles/","d":"2026-11-24","x":"A Ford bejelentette, hogy tárgyalásokat folytat a Pentagon számára katonai járművek és egyéb védelmi termékek szállításáról. A beszélgetések középpontjában a nagy teljesítményű katonai járművek biztosítása áll, valamint együttműködés egy űrtechnológiai vállalattal, a Revolution Space-szel, fejlett műholdak építése érdekében. A Pentagon aktívan partnerséget alakít ki hazai gyártókkal és technológiai cégekkel a következő generációs pilóta nélküli és autonóm rendszerek gyártásának felgyorsítása érdekében. A Ford és más autógyártók a második világháború óta alkalmazzák tömeggyártási képességeiket katonai igények kielégítésére. A Pentagon célja egy ellenálló, nagy kapacitású ipari bázis kiépítése.","dom":"LAND","br":"Lövész és gépesített lövész csapatok","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":2,"cid":14828,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Tárgyalások új járművek szállításáról, de még nem végleges."},{"id":14854,"s":"Military Times","sz":"T2","t":"Ford in talks with the Pentagon to supply military vehicles","th":"Ford tárgyalásokat folytat a Pentagon számára katonai járművek szállításáról","u":"https://www.militarytimes.com/news/2026/11/24/ford-in-talks-with-the-pentagon-to-supply-military-vehicles/","d":"2026-11-24","x":"A Ford bejelentette, hogy tárgyalásokat folytat a Pentagon számára katonai járművek és egyéb védelmi termékek szállításáról. A megbeszélések középpontjában a nagy teljesítményű katonai járművek biztosítása áll, valamint együttműködés a Revolution Space céggel fejlett műholdak építésében. A Pentagon aktívan partnerséget alakít ki hazai gyártókkal és technológiai cégekkel a következő generációs pilóta nélküli és autonóm rendszerek gyártásának felgyorsítása érdekében. A Detroit-i autógyártók hosszú múltra tekintenek vissza a tömeggyártási képességek katonai igényekre való átkonvertálásában. A Ford mellett a General Motors is érdeklődik katonai projektek iránt.","dom":"LAND","br":"Lövész és gépesített lövész csapatok","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":7,"cm":2,"cid":14828},{"id":14830,"s":"Defense News","sz":"T2","t":"‘A new competition space’: US Coast Guard takes icebreaker on maiden voyage to the Arctic","th":"Új versenytér: Az Egyesült Államok parti őrsége jégszakítóval az Északi-sarkra indult","u":"https://www.defensenews.com/naval/2026/11/24/a-new-competition-space-us-coast-guard-takes-icebreaker-on-maiden-voyage-to-the-arctic/","d":"2026-11-24","x":"Az Egyesült Államok parti őrsége első új jégszakítója, a Storis, 133 napos küldetés után visszatért az Északi-sarkról. A hajó különböző katonai műveleteket hajtott végre, beleértve a jogérvényesítést és élő tűzgyakorlatokat, amelyek évtizedek óta nem történtek a térségben. A Storis fedélzetén drónokat is teszteltek, amelyek segíthetnek a jég navigálásában. A hajó logisztikai képességei lehetővé teszik a haditengerészeti hajók üzemanyaggal való ellátását, ami jelentős időmegtakarítást jelenthet a hadműveletek során. A küldetés során a Storis részt vett a halászati jogérvényesítési műveletekben is, ami az első ilyen akció volt több mint két évtizede.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Drónok és drónelhárítás","Logisztikai és ellátó csapatok"],"oc":["United States"],"p":8,"cm":2,"cid":14830,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Új jégszakító küldetés, de nem jelentős technológiai áttörés."},{"id":14831,"s":"Defense News","sz":"T2","t":"From horsepower to firepower, Japan draws auto suppliers into major arms buildup","th":"A lóerőből tűzerő: Japán autóipari beszállítók bevonása a jelentős fegyverkezési programba","u":"https://www.defensenews.com/global/asia-pacific/2026/11/24/from-horsepower-to-firepower-japan-draws-auto-suppliers-into-major-arms-buildup/","d":"2026-11-24","x":"Japán autóipari beszállítók, mint például az Aster, a védelem technológiájába való belépés révén új lehetőségeket találnak, miközben a kormány a legnagyobb katonai fejlesztését végzi a második világháború óta. A beszállítók, akik korábban autóalkatrészeket gyártottak, most drónokhoz szükséges elektromos motorokat fejlesztenek. A japán kormány célja, hogy a meglévő ipari ellátási láncokat kihasználva felgyorsítsa a biztonsági átalakulást, miközben növeli a védelmi kiadásokat. A közelmúltban bevezetett programok célja, hogy támogassák a beszállítókat a védelem iparába való belépésben. A közeljövőben várható nemzeti biztonsági stratégia drónflották fejlesztését is előirányozza. A hossz_megjegyzes: Az absztrakt a szövegben szereplő tényekre épül, és 7 mondatot tartalmaz.","dom":"MDO","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Japan","United States","China","North Korea"],"p":8,"cm":1,"cid":14831,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Japán autóipar belépése a védelembe, de nem új."},{"id":14832,"s":"Defense News","sz":"T2","t":"Russia may launch nuke-laden satellite by year’s end, German report warns","th":"Oroszország nukleáris fegyverrel felszerelt műholdat indíthat az év végéig, figyelmeztet egy német jelentés","u":"https://www.defensenews.com/global/europe/2026/11/24/russia-may-launch-nuke-laden-satellite-by-years-end-german-report-warns/","d":"2026-11-24","x":"Egy német közszolgálati média jelentése szerint Oroszország nukleáris fegyverrel felszerelt műholdat indíthat az év végéig. A Sputnik-S néven ismert műhold évek óta a moszkvai térségben van tárolva. A jelentés szerint a műhold indítása 60 napon belül megtörténhet. A NATO főtitkára, Mark Rutte megerősítette, hogy az alliancia folyamatosan értékeli elrettentési és védelmi helyzetét. A műhold indítása 1967-es Űrkutatási Szerződésbe ütközik, amely megtiltja nukleáris fegyverek pályára állítását. A jelentések szerint a műhold célja a nukleáris fegyverek űrbeli hatásainak tesztelése lehet. A hossz_megjegyzes: Az absztrakt 5 mondatnál rövidebb, de a megadott információk alapján készült.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Világűr- és műholdképességek"],"oc":["Russia","Germany","United States"],"p":8,"cm":1,"cid":14832,"sp2":65,"ind":"Jelentőség 4/5, újdonság 4/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Nukleáris műhold indításának lehetősége, jelentős fejlemény."},{"id":14843,"s":"Army Technology","sz":"T2","t":"Lockheed Martin completes third test of JR3 training rocket","th":"A Lockheed Martin befejezte a JR3 kiképző rakéta harmadik tesztjét","u":"https://www.army-technology.com/news/lockheed-martin-jr3-training-rockets/","d":"2026-11-24","x":"A Lockheed Martin sikeresen befejezte a Joint Reduced Range Rocket (JR3) harmadik repülési tesztjét, amely során 24 kiképző lövedéket lőttek ki a Yuma Proving Ground területén, Arizonában. A teszt célja a rakéta teljesítményének és megbízhatóságának ellenőrzése volt. A JR3 rakéta a szárazföldi erők tüzérségi képességeit hivatott erősíteni, és a modern hadviselés követelményeinek megfelelően lett kifejlesztve. A teszt sikeres lebonyolítása fontos lépés a haderő modernizációjában és a védelmi ipar fejlődésében. A Lockheed Martin folytatja a rakéta további fejlesztését és tesztelését.","dom":"LAND","br":"Tüzér és tűztámogatás","sp":["Lőszer és védelmi ipari kapacitás","Haderő-modernizáció és erőszerkezet"],"oc":["USA"],"p":7,"cm":1,"cid":14843},{"id":14858,"s":"Military Times","sz":"T2","t":"Army to detonate degraded ammunition despite community concern","th":"A hadsereg detonálja a degradált lőszert a közösségi aggodalmak ellenére","u":"https://www.militarytimes.com/news/your-military/2026/11/24/army-to-detonate-degraded-ammunition-despite-community-concern/","d":"2026-11-24","x":"Az Egyesült Államok hadserege folytatja a tárolt, instabil lőszerek detonálását egy iowai létesítményben, miután egy szövetségi fellebbviteli bíróság jóváhagyta az eljárást. Az akció támogatását élvezi a helyi hatóságok és a szövetségi ügynökségek részéről is. A hadsereg vezetője hangsúlyozta, hogy a kontrollált robbantás elkerülhetetlen a közbiztonság érdekében, mivel a degradált vegyület spontán detonációra hajlamos. A detonálás után a hatóságok mintavételt terveznek a lehetséges szennyeződés területein. A hadsereg figyelmeztetett, hogy a detonációt követően megnövekedett ólomrészecskék várhatóak a levegőben.","dom":"LAND","br":"Tüzér és tűztámogatás","sp":["Lőszer és védelmi ipari kapacitás"],"oc":["United States"],"p":7,"cm":1,"cid":14858},{"id":14821,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"Wilsbach’s Message to Airmen After One Year as CSAF: ‘Readiness Is Fundamental’","th":"Wilsbach üzenete a légierő tagjainak CSAF-ként eltöltött első éve után: 'A felkészültség alapvető'","u":"https://www.airandspaceforces.com/wilsbach-message-to-airmen-one-year-csaf-readiness/","d":"2026-11-24","x":"Kenneth Wilsbach, az Egyesült Államok Légierő főparancsnoka, levelet írt a légierő tagjainak, amelyben hangsúlyozta a felkészültség javítását, a repülőgépek és más rendszerek modernizálását. Az elmúlt év során a légierő nagy léptékű harci műveletekben vett részt Venezuelában és Iránban, ami megkövetelte a gyors alkalmazkodást és a harci erő előállítását. Wilsbach kiemelte a modernizációs mérföldköveket, beleértve az F-22 Raptor és az új Collaborative Combat Aircraft drón együttműködését, valamint a Sentinel interkontinentális ballisztikus rakéta infrastruktúrájának építését. A légierőnek alkalmazkodnia kell a változó fenyegetésekhez, beleértve a drónokkal szembeni védelmet is. Wilsbach hangsúlyozta a harci kultúra fenntartásának fontosságát, amely magában foglalja a fizikai felkészültséget és a felelősségvállalást is.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":8,"cm":1,"cid":14821,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Vezetői üzenet, nem technikai hír."},{"id":14845,"s":"Army Technology","sz":"T2","t":"MARSS wins $16m contract for counter-drone systems in Middle East","th":"MARSS 16 millió dolláros szerződést nyert drónelhárító rendszerekre a Közel-Keleten","u":"https://www.army-technology.com/news/marss-counter-drone-middle-east/","d":"2026-11-24","x":"A MARSS 16 millió dolláros szerződést nyert a drónelhárító rendszerek szállítására, amelyek több, nemzeti stratégiai szempontból fontos helyszínen kerülnek telepítésre a Közel-Keleten. A projekt keretében a MARSS integrálja a NiDAR parancsnoki és irányítási rendszert, amely a működési gerincet képezi a dedikált irányító központokban. A rendszer célja a drónfenyegetések gyors és hatékony észlelése és semlegesítése, a legmodernebb érzékelők és ellenintézkedések alkalmazásával. A projekt azonnal megkezdődik, a teljes rendszer telepítése 2027-re várható.","dom":"CYB","br":"Védelmi kiberműveletek","sp":["Drónok és drónelhárítás","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Jordan","Kuwait"],"p":8,"cm":1,"cid":14845,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új drónelhárító szerződés, de nem technológiai újdonság."},{"id":14499,"s":"ICDS","sz":"T1","t":"Europeanising NATO: Artificial Intelligence","th":"A NATO európai integrációja: Mesterséges intelligencia","u":"https://icds.ee/en/europeanising-nato-artificial-intelligence/","d":"2026-11-24","x":"A mesterséges intelligencia (MI) a geopolitikai verseny egyik fő területévé vált az Egyesült Államok és Kína között. Az MI katonai alkalmazása növekvő tendenciát mutat, különösen Oroszország ukrajnai agressziója kapcsán, de az európai NATO-tagállamok között egyenlőtlen a technológia elfogadása. A NATO az MI-t kilenc kritikus technológia egyikeként azonosította, és politikai keretet dolgozott ki a katonai alkalmazások fejlesztéséhez. Az Egyesült Államok dominanciája a katonai MI terén fontos következményekkel jár az európai NATO számára, mivel a tagállamoknak képesnek kell lenniük az MI védelmi célú alkalmazására az Egyesült Államok nélkül is. Az amerikai és európai megközelítések közötti kulturális különbségek, valamint a technológiai függőség kérdései tovább bonyolítják a helyzetet. A NATO által választott amerikai technológiai cégek, mint például a Palantir, a katonai műveletek gerincét képezik, ami tovább növeli az európai NATO technológiai sebezhetőségét.","dom":"MDO","br":"Lövész és gépesített lövész csapatok","sp":["MI és autonómia","Haderő-modernizáció és erőszerkezet"],"oc":["United States","Germany","France","Ukraine"],"p":8,"cm":1,"cid":14499,"sp2":53,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. MI katonai alkalmazása ismert téma, de NATO keret új."},{"id":14727,"s":"The War Zone","sz":"T2","t":"Lynx KF41 Fighting Vehicles, Newly Arrived In Ukraine, Will Take On Counter-Drone Mission","th":"Lynx KF41 Harcjárművek, Újonnan Érkeztek Ukrajnába, Ellenséges Drónok Ellen Fognak Harcolni","u":"https://www.twz.com/land/lynx-kf41-fighting-vehicles-newly-arrived-in-ukraine-will-take-on-counter-drone-mission","d":"2026-11-24","x":"Ukrajna megkapta első Lynx KF41 gyalogsági harcjárműveit Németországból, amelyek fő feladata az orosz drónok lelövése lesz. A Lynx járművek 30 mm-es automata ágyúval és 12,7 mm-es géppuskával vannak felszerelve, amelyek képesek a drónok és más alacsony repülésű célpontok hatékony megsemmisítésére. A járművek a Rheinmetall által gyártott AHEAD programozható lőszereket használják, amelyek csökkentik a földi kár kockázatát. A 21. Különálló Gépesített Brigád a Lynxet nemcsak drónok ellen, hanem orosz gyalogság és könnyű páncélozott járművek ellen is beveti. A Lynx magas szintű védelmet, mobilitást és tűzerőt kínál, amely lehetővé teszi a különböző földi és légi célpontok hatékony megsemmisítését a csatatéren.","dom":"LAND","br":"Lövész és gépesített lövész csapatok","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás"],"oc":["Ukraine","Germany","Hungary","Italy"],"p":8,"cm":1,"cid":14727,"sp2":65,"ind":"Jelentőség 4/5, újdonság 4/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új harcjárművek Ukrajnában, jelentős fejlemény.","hu":["közvetett","A hír releváns lehet a magyar haderőfejlesztési program szempontjából, mivel Magyarország is jelentős mennyiségű Lynx KF41 gyalogsági harcjárművet szerzett be a Rheinmetalltól, és ezek a járművek hasonló képességekkel rendelkeznek, mint az Ukrajnába szállítottak [HU-01]. A magyar Lynx járművek is 30 mm-es gépágyúval és páncéltörő rakétákkal vannak felszerelve, ami lehetővé teszi a különböző célpontok elleni hatékony fellépést [HU-03]. A magyarországi gyártás és fejlesztés a zalaegerszegi üzemben történik, ami a hazai védelmi ipar erősítését szolgálja [HU-02].","ok"]},{"id":14731,"s":"The War Zone","sz":"T2","t":"Turkish Kizilelma Fighter Drone Declared Operational","th":"A török Kizilelma harci drón üzemképessé nyilvánítva","u":"https://www.twz.com/air/turkish-kizilelma-fighter-drone-declared-operational","d":"2026-11-24","x":"A Baykar török dróngyártó bejelentette, hogy a Bayraktar Kizilelma harci drón első három példánya belépett a török biztonsági erők állományába. Ez a fejlesztés a világ első üzemképessé nyilvánított pilóta nélküli harci repülőgépe. A Kizilelma drón a harci típusú küldetésekre, beleértve a légi harcot is, lett tervezve, és várhatóan kiegészíti Törökország következő generációs TF Kaan pilóta nélküli harci repülőgépét. A drón jellemzői közel állnak egy könnyű vadászgéphez, és a program jelentős mérföldköveket ért el, beleértve a fegyverintegrációt és az autonóm formációs repülést is.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Turkey"],"p":8,"cm":1,"cid":14731,"sp2":73,"ind":"Jelentőség 5/5, újdonság 4/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új török harci drón üzemképessé nyilvánítva."},{"id":14563,"s":"Lowy Interpreter","sz":"T1","t":"Australia’s conflict prevention choice: build the system, not just the parts","th":"Ausztrália konfliktusmegelőzési választása: építsük a rendszert, ne csak a részeket","u":"https://www.lowyinstitute.org/the-interpreter/australia-s-conflict-prevention-choice-build-the-system-not-just-the-parts","d":"2026-11-25","x":"Ausztrália konfliktusmegelőzési stratégiája a rendszerek integrálására összpontosít, nem csupán az egyes elemek fejlesztésére. A parlamenti jelentés hangsúlyozza a konfliktusok megelőzésének fontosságát, és javaslatokat tesz a fejlesztési programok hatékonyságának növelésére. A jelentés szerint a konfliktusmegelőzéshez szükséges eszközök együttműködése és a korai figyelmeztető rendszerek kiépítése elengedhetetlen. Az Ausztrál Kormány válasza kulcsfontosságú, hogy a javaslatokat egy átfogó rendszerként kezelje, amely figyelemmel kíséri a társadalmi ellenállást és a konfliktusok kockázatát. A jelentés kiemeli a klímaváltozás szerepét is, mint a konfliktusok kockázatát növelő tényezőt.","dom":"MAR","br":"Tengeri pilóta nélküli rendszerek","sp":["Vezetés-irányítás és ISR (C2/ISR)","Drónok és drónelhárítás"],"oc":["Australia","Solomon Islands"],"p":7,"cm":1,"cid":14563},{"id":14718,"s":"Breaking Defense","sz":"T2","t":"Trump’s carrier desire might not take flight, and a new twist for Navy shipbuilding","th":"Trump hajógyártási tervei nem biztos, hogy megvalósulnak","u":"https://breakingdefense.com/2026/11/trumps-carrier-desire-might-not-take-flight-and-a-new-twist-for-navy-shipbuilding/","d":"2026-11-24","x":"Donald Trump elnök szeretné, ha a haditengerészet visszatérne a gőzüzemű repülőgép-indító rendszerekhez, de a törvényhozók nem támogatják ezt az elképzelést. A haditengerészet titkárának jelöltje, Hung Cao meghallgatásán a republikánusok és demokraták is kifejezték ellenállásukat. A haditengerészet államtitkárának jelöltje, William Toti egy új tervet javasolt az amerikai hadihajók építésére. A cikk a haditengerészeti hajógyártás jövőjét és a jelöltek körüli politikai vitákat elemzi.","dom":"MAR","br":"Felszíni harci hajók","sp":["Haderő-modernizáció és erőszerkezet","Hajóépítés és haditengerészet"],"oc":["United States"],"p":6,"cm":1,"cid":14718},{"id":14728,"s":"The War Zone","sz":"T2","t":"Seoul Scrambles F-15Ks As Russian Warplanes Come Within Seconds Of Crossing Into South Korean Airspace","th":"Dél-Korea F-15K vadászgépeket vetett be, miután orosz harci repülők közel kerültek a dél-koreai légtérhez","u":"https://www.twz.com/air/seoul-scrambles-f-15ks-as-russian-warplanes-come-within-seconds-of-crossing-into-south-korean-airspace","d":"2026-11-24","x":"2026. november 24-én orosz katonai repülőgépek rendkívül közel kerültek Dél-Korea szuverén légtéréhez, ami sürgősségi választ váltott ki Szöulból. A dél-koreai hadsereg F-15K Slam Eagle vadászgépeket indított, hogy figyelemmel kísérjék az orosz repülőgépeket, amelyek a Korea Légvédelmi Azonosító Zónájába (KADIZ) léptek be. A közelmúlt eseményei diplomáciai feszültséget is okoztak, mivel Dél-Korea hivatalos tiltakozást nyújtott be Oroszországnak. A helyzet hangsúlyozza a régióban zajló orosz katonai tevékenységek növekedését, amely folyamatosan figyelmet vonz a helyi légierők részéről. A Dél-Korea által kiadott figyelmeztetés szerint az orosz repülőgépek nem lépték át a dél-koreai területi légtér határait.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Vezetés-irányítás és ISR (C2/ISR)"],"oc":["South Korea","Russia"],"p":7,"cm":1,"cid":14728},{"id":14795,"s":"DefenseScoop","sz":"T2","t":"Questions about DOD’s frontier AI organization linger after Trump-ordered rebrand and website redesign","th":"Kérdések merülnek fel a DOD határ menti MI szervezetével kapcsolatban a Trump által elrendelt új arculat és weboldal átalakítása után","u":"https://defensescoop.com/2026/11/24/trump-ai-rebrand-pentagon-super-intelligence-office-sio/","d":"2026-11-24","x":"A Pentagon MI-vel foglalkozó irodájának átalakítása után kérdések merültek fel a vezetésről és a prioritásokról. A Trump-adminisztráció által elrendelt új arculat és weboldal átalakítása eltüntette a csapat aktuális prioritásait. A Maven Smart System, amely a Pentagon zászlóshajó MI-alapú szoftverplatformja, továbbra is kulcsszerepet játszik a katonai műveletekben. A szakértők hangsúlyozzák a transzparencia fontosságát, mivel a MI szerepe egyre növekszik a katonai tervezésben és végrehajtásban. A DOD-nak világosabb tájékoztatást kellene adnia a szervezet prioritásairól és vezetéséről.","dom":"CYB","br":"Híradó és informatikai csapatok","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":7,"cm":1,"cid":14795},{"id":14805,"s":"SpaceNews","sz":"T2","t":"Simera Sense, Spacemanic, Zaitra and World from Space Join Forces on an End-to-End Dual-Use Mission Solution","th":"Simera Sense, Spacemanic, Zaitra és World from Space együttműködik egy végigkísérő kettős felhasználású küldetés megoldásán","u":"https://spacenews.com/simera-sense-spacemanic-zaitra-and-world-from-space-join-forces-on-an-end-to-end-dual-use-mission-solution/","d":"2026-11-24","x":"A Simera Sense, Spacemanic, Zaitra és World from Space együttműködést kötött egy kettős felhasználású kamerára épülő teljes küldetésmegoldás kidolgozására. A megállapodás célja, hogy a partnerek egy olyan megoldást kínáljanak, amely lefedi az egész folyamatot: a Simera Sense biztosítja az xScape200 Dual-Use kamerát, míg a Spacemanic a műholdplatformot. A Zaitra az SKAIDOCK fedélzeti számítógépet és a képelemző szoftvert biztosítja, míg a World from Space a képekből nyerhető információkat alakítja át ügyfelek számára hasznosítható betekintésekké. A partnerség célja, hogy a kettős felhasználású képek könnyebben elérhetővé váljanak az ügyfelek számára.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Világűr- és műholdképességek"],"oc":["Belgium","Czech Republic","South Africa","United Kingdom"],"p":7,"cm":1,"cid":14805},{"id":14857,"s":"Military Times","sz":"T2","t":"‘A new competition space’: US Coast Guard takes icebreaker on maiden voyage to the Arctic","th":"Új versenytér: Az Egyesült Államok Parti Őrsége jégtörője első útjára indult az Északi-sarkra","u":"https://www.militarytimes.com/news/your-military/2026/11/24/a-new-competition-space-us-coast-guard-takes-icebreaker-on-maiden-voyage-to-the-arctic/","d":"2026-11-24","x":"Az Egyesült Államok Parti Őrsége első új jégtörője, a Storis, 133 napos küldetés után tért vissza az Északi-sarkról, ahol különböző katonai műveleteket hajtott végre. A hajó drónokkal végzett kísérleteket is, amelyek segíthetnek a jégtörés hatékonyságának növelésében. A Storis emellett képes lehet az amerikai haditengerészeti hajók üzemanyaggal való ellátására is, ami jelentős időmegtakarítást jelenthet a műveletek során. A küldetés során a hajó jogi ellenőrzéseket is végzett, ami több mint két évtized után az első ilyen akció volt egy jégtörő által. A Storis új képességei és tapasztalatai új lehetőségeket nyitnak meg a jövőbeli műveletek számára az Északi-sarkon.","dom":"MAR","br":"Felszíni harci hajók","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás","Logisztikai és ellátó csapatok"],"oc":["United States"],"p":8,"cm":2,"cid":14830},{"id":14541,"s":"ASPI The Strategist","sz":"T1","t":"Australia must turn its quantum edge into a powerful deterrent","th":"Ausztráliának a kvantumelőnyét erőteljes elrettentővé kell alakítania","u":"https://www.aspistrategist.org.au/australia-must-turn-its-quantum-edge-into-a-powerful-deterrent/","d":"2026-11-24","x":"Ausztráliának ki kell alakítania egy beszerzési és exportprogramot a kvantumórák és érzékelők számára, amely összekapcsolja a sikeres próbákat a katonai minősítéssel. A kvantumtechnológiák fontos szerepet játszanak a katonai erők koordinálásában és navigálásában, amikor a GPS jelek nem állnak rendelkezésre. Az új kvantumórák segíthetnek a katonai kommunikációk és radarhálózatok szinkronizálásában, míg a kvantumérzékelők lehetővé teszik a járművek helymeghatározását GPS nélkül. Az Ausztrál Védelmi Erőknek folyamatosan szüksége van a sikeres próbákra és a finanszírozott beszerzési döntésekre, hogy a prototípusok fenntartható termelésbe kerüljenek. Az AUKUS partnerek is foglalkoznak ezzel a problémával, és Ausztráliának saját programot kellene létrehoznia a meglévő védelmi keretek között.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","MI és autonómia"],"oc":["Australia","United States","United Kingdom","India"],"p":8,"cm":1,"cid":14541,"sp2":58,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Kvantumtechnológia katonai alkalmazása új, de nem áttörés."},{"id":14730,"s":"The War Zone","sz":"T2","t":"Sweden’s Gripens Are Doing Big Things With A Tiny Footprint In Poland","th":"Svéd Gripenek jelentős szerepe Lengyelországban","u":"https://www.twz.com/air/swedens-tiny-gripen-fighter-detachment-takes-on-a-big-nato-role","d":"2026-11-24","x":"A svéd Gripenek a lengyelországi Mińsk Mazowiecki légibázison végzett műveleteik során demonstrálták a kis előretolt jelenlét operatív értékét. A svéd pilóták a NATO légvédelmi feladatokban vettek részt, és a kis létszámú támogatói csapat lehetővé tette a gyors reagálást és a rugalmasságot. A svéd légierő 60 éve építi a harci repülőgépek szórt üzemeltetésének képességét, amely most a NATO műveletekhez is alkalmazható. A Missed Refueling Base (MRB) koncepciója lehetővé teszi a Gripenek számára, hogy rugalmasan és hatékonyan működjenek a szövetséges területeken, anélkül hogy nagy támogatói infrastruktúrát kellene kiépíteni. A svéd megközelítés célja a műveletek rugalmasságának növelése és a különböző helyszínek közötti támogatás egyszerűsítése.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Sweden","Poland"],"p":8,"cm":1,"cid":14730,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Gripenek NATO műveletekben, de nem új információ.","hu":["közvetett","A svéd Gripenek lengyelországi műveletei közvetett módon relevánsak lehetnek Magyarország számára, mivel a Magyar Légierő is üzemeltet JAS 39 Gripen vadászgépeket [HU-15]. A svéd tapasztalatok a Gripenek szórt üzemeltetésében és a NATO műveletekhez való alkalmazkodásban hasznosak lehetnek a magyar légierő számára is, különösen a rugalmasság és a gyors reagálás terén.","ok"]},{"id":13813,"s":"ASPI The Strategist","sz":"T1","t":"Sign of the times: CCAs dominate a major fighter conference","th":"A korszak jelei: A CCÁ-k dominálnak egy jelentős vadászrepülő konferencián","u":"https://www.aspistrategist.org.au/flashbacks-in-munich-as-ccas-hit-a-tipping-point/","d":"2026-11-23","x":"A müncheni nemzetközi vadászrepülő konferencia idén a kollaboratív harci repülőgépekről (CCA) szólt, ahol a résztvevők a pilóta nélküli és pilótás járművek jövőbeli erőstruktúráiról beszéltek. A Saab bemutatta a következő generációs autonóm platformját, amely 2025-re várhatóan repülni fog. Az Egyesült Államok légierője is érdeklődik a CCÁ-k iránt, mivel a jövőbeli repülőgépek költséghatékonyságát és tömeges alkalmazását keresik. A konferencia során a résztvevők a CCÁ-k integrálásának lehetőségeit és kihívásait vitatták meg, különös figyelmet fordítva a költségek csökkentésére és a pilóták képzésére. A CCÁ-k szerepe a jövőbeli légiharcokban egyre fontosabbá válik.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet","MI és autonómia"],"oc":["United States","Sweden","Germany","France"],"p":8,"cm":1,"cid":13813,"sp2":58,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. CCA-k dominanciája a konferencián."},{"id":13836,"s":"Lowy Interpreter","sz":"T1","t":"Australia’s next critical mineral step is metallisation","th":"Ausztrália következő kritikus ásványi lépése a metallizáció","u":"https://www.lowyinstitute.org/the-interpreter/australia-s-next-critical-mineral-step-is-metallisation","d":"2026-11-24","x":"Ausztrália a következő lépésként a kritikus ásványok értékláncának fejlesztésére összpontosít, különös figyelmet fordítva a metallizációra, amely a finomított oxidokat fémmé alakítja. A kormány célja, hogy erősítse a védelmi és gazdasági biztonságot, és a Critical Minerals R\u0026D Hub keretében kutatásokat finanszíroz a metallizációs folyamatok terén. A metallizációs projektek finanszírozásának biztosítása érdekében Ausztrália és az Egyesült Államok együttműködik, hogy elősegítse a kritikus ásványi projektekbe történő befektetéseket. A kormány célja, hogy a környezeti jóváhagyási folyamatokat felgyorsítsa a prioritásként kezelt projektek, például a kritikus ásványok esetében. A metallizációs képességek fejlesztése kulcsfontosságú a gazdasági biztonság szempontjából.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["Australia","United States"],"p":7,"cm":1,"cid":13836},{"id":13984,"s":"Breaking Defense","sz":"T2","t":"$16 billion propulsion mega-contract posted in error, Air Force says","th":"$16 milliárdos hajtómű-mega-szerződés téves közzététele, mondja a Légierő","u":"https://breakingdefense.com/2026/11/propulsion-mega-contract-posted-in-error-air-force-says/","d":"2026-11-23","x":"A Légierő visszavonta a tévesen közzétett, akár 16,1 milliárd dolláros hajtóműszerződés bejelentését. A szerződés az Advanced Propulsion Acquisition Contract (APAC) keretein belül valósulna meg, amely 2041-ig tartana. A program célja, hogy rugalmas, vállalati szintű beszerzési eszközként szolgáljon a hajtóművekhez szükséges követelményekhez. A Légierő megerősítette, hogy 58 vállalatot terveznek kiválasztani a szerződés keretében, amely a jövőbeli platformok, például drónok és nagy mobilitású repülőgépek hatékonyabb működtetésére irányul. A jövőbeli megrendelések a kiválasztott beszállítók között versenyeznek majd, ahogy a követelmények érvényesítése és finanszírozása megtörténik.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Lőszer és védelmi ipari kapacitás"],"oc":["United States"],"p":8,"cm":1,"cid":13984,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Téves szerződés közzététel visszavonása."},{"id":13985,"s":"Breaking Defense","sz":"T2","t":"Colombia races for counter-drone tech as militant groups embrace drones as frontline weapons","th":"Kolumbia versenyt fut a drónelhárító technológiáért, miközben a militáns csoportok drónokat használnak első vonalbeli fegyverként","u":"https://breakingdefense.com/2026/11/colombia-races-for-counter-drone-tech-as-militant-groups-embrace-drones-as-frontline-weapons/","d":"2026-11-23","x":"Kolumbia új kormánya, Abelardo de la Espriella vezetésével, erőteljes fellépést ígért a kartellek és más fegyveres csoportok ellen, ami drónokkal végrehajtott támadásokhoz vezetett. Az elmúlt hónapokban több katonai bázist is drónok támadtak meg, amelyek robbanószereket dobtak le, több halálos áldozatot követelve. A helyi kormányoknak sürgősen lépéseket kell tenniük a drónokkal szembeni védelem érdekében, mivel a militáns csoportok egyre inkább alkalmazzák ezeket a technológiákat. A kolumbiai fegyveres erőknek szükségük van a drónfenyegetések elleni védelmi rendszerek fejlesztésére, hogy megvédjék a katonákat és a civileket. A helyzet sürgőssége miatt a drónelhárító rendszerekbe való befektetés elengedhetetlen.","dom":"AIR","br":"Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Colombia","United States"],"p":8,"cm":1,"cid":13985,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Kolumbia drónelhárító technológia fejlesztése."},{"id":13999,"s":"The War Zone","sz":"T2","t":"Did Ukraine Use A Mothership To Launch Its Sea Drone Attack On Russian Ships in Benghazi?","th":"Ukrán hajóanyagról indított tengeri drón támadás orosz hajók ellen Bengáziban","u":"https://www.twz.com/sea/did-ukraine-use-a-mothership-to-launch-its-sea-drone-attack-on-russian-ships-in-benghazi","d":"2026-11-23","x":"Az Ukrán Fegyveres Erők által végrehajtott támadás során uncrewed surface vessel (USV) rendszerek orosz hadihajókra indultak egy hajóanyagról. Az ukrán Biztonsági Szolgálat (SBU) megerősítette, hogy a támadások célpontjai között szerepelt a Merkury nevű orosz korvett és az Angara nevű teherszállító hajó. A támadás során a Merkury korvett elsüllyedt, míg az Angara súlyosan megsérült. Az SBU szerint a művelet célja a orosz logisztikai képességek gyengítése volt, amely a Fekete-tengeren túl is érvényesült. A támadás részletei és a hajóanyagról való indítás új dimenziókat nyitnak a tengeri drónhadviselésben. A hossz_megjegyzes: Az absztrakt 5 mondatból áll, amely a szövegben szereplő tényekre épül.","dom":"MAR","br":"Tengeri pilóta nélküli rendszerek","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Ukraine","Russia","Libya"],"p":8,"cm":1,"cid":13999,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Ukrán dróntámadás orosz hajók ellen."},{"id":14000,"s":"The War Zone","sz":"T2","t":"Marines Want Naval Strike Missiles With Double The Range","th":"A tengerészgyalogság kétszeres hatótávolságú tengeri csapásmérő rakétákat szeretne","u":"https://www.twz.com/sea/marines-want-naval-strike-missiles-with-double-the-range","d":"2026-11-23","x":"Az Egyesült Államok Tengerészgyalogsága (USMC) arra törekszik, hogy legalább megduplázza a földről indítható Naval Strike Missile (NSM) rakéták hatótávolságát. Az NSM jelenlegi hatótávolsága 135 tengeri mérföld, de a tervek szerint ez 270 tengeri mérföldre nőhet. Ez jelentős előnyöket nyújtana a jövőbeli szigetek közötti hadműveletek során, amelyek középpontjában a tengerészgyalogság új koncepciói állnak. Az NSM már most is modern tervezésű, rejtett funkciókkal rendelkezik, és a Marines a jövőbeli hadműveletekhez szükséges képességek gyors telepítésére és áthelyezésére összpontosít. A tengerészgyalogság már bemutatta ezeket a koncepciókat több gyakorlat során, beleértve a legutóbbi Keen Sword gyakorlatot is.","dom":"MAR","br":"Tengerészgyalogság és kétéltű erők","sp":["Rakéták és hiperszonikus fegyverek","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":14000,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. NSM rakéták hatótávolságának növelése."},{"id":14001,"s":"The War Zone","sz":"T2","t":"China’s Naval Developments Set For The Spotlight At Zhuhai Airshow","th":"Kína haditengerészeti fejlesztései a Zhuhai Légibemutatón","u":"https://www.twz.com/air/chinas-naval-developments-set-for-the-spotlight-at-zhuhai-airshow","d":"2026-11-23","x":"A Kínai Népi Felszabadító Hadsereg Haditengerészete (PLAN) jelentős jelenlétet tervez a közelgő Zhuhai Légibemutatón, ahol hadihajók, hordozóra telepített repülőgépek és fejlett fegyverrendszerek szerepelnek. Az esemény során különös figyelmet kap a hordozórepülőgép-képességek gyors fejlődése, beleértve a J-15T és J-35A vadászgépeket, valamint a KJ-600 korai figyelmeztető és irányító repülőgépet. A JL-15 hordozóképes kiképző repülőgép bemutatása is várható, amely fontos lépés a következő generációs hordozópilóták képzésében. A Zhuhai Légibemutató Kína legfontosabb védelmi és légiipari eseménye, amely lehetőséget biztosít a legújabb katonai technológiák bemutatására.","dom":"MAR","br":"Haditengerészeti repülés és tengeri járőr","sp":["Hajóépítés és haditengerészet","Drónok és drónelhárítás"],"oc":["China"],"p":8,"cm":1,"cid":14001,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Kínai haditengerészeti fejlesztések bemutatása."},{"id":14057,"s":"C4ISRNET","sz":"T2","t":"A race for lifesaving battlefield drones | Defense News Weekly Full Episode 11.24.26","th":"Verseny az életmentő csatatéri drónokért","u":"https://www.c4isrnet.com/videos/2026/11/23/a-race-for-lifesaving-battlefield-drones-defense-news-weekly-full-episode-11-24-26/","d":"2026-11-23","x":"A cikk a csatatéren alkalmazott életmentő drónok fejlesztéséről szól. Miközben ukrán innovátorok a frontvonalban lévő légi drónos evakuációt fejlesztenek, a DARPA mesterséges intelligenciával segített robotokat fejleszt, amelyek képesek megtalálni és felmérni a sebesült katonákat és civileket. Az életmentésért folytatott verseny már megkezdődött.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás"],"oc":["Ukraine","United States"],"p":8,"cm":3,"cid":14057,"sp2":60,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 3/5 (3 forrás), forrásszint 3/5. Életmentő drónok fejlesztése."},{"id":14058,"s":"C4ISRNET","sz":"T2","t":"Ukraine strikes Russian warship and cargo vessel with naval drones in Libya","th":"Ukrajna tengeri drónokkal csapott le orosz hadihajóra és teherhajóra Líbiában","u":"https://www.c4isrnet.com/videos/2026/11/23/ukraine-strikes-russian-warship-and-cargo-vessel-with-naval-drones-in-libya/","d":"2026-11-23","x":"Ukrajna tengeri drónokkal támadta meg az orosz hadihajót és teherhajót Líbiában. Volodymyr Zelenskyy ukrán elnök elmondta, hogy a támadás során hét tengeri drónt használtak, amelyek elsüllyesztették az orosz Merkury korvettet.","dom":"MAR","br":"Felszíni harci hajók","sp":["Drónok és drónelhárítás"],"oc":["Ukraine","Russia"],"p":8,"cm":3,"cid":14058,"sp2":60,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 3/5 (3 forrás), forrásszint 3/5. Ukrajna dróntámadása orosz hajók ellen."},{"id":14060,"s":"C4ISRNET","sz":"T2","t":"DARPA tests drones to find and assess injured victims at the Triage Challenge","th":"DARPA drónokat tesztel a sérült áldozatok felkutatására és értékelésére a Triage Challenge keretében","u":"https://www.c4isrnet.com/videos/2026/11/23/darpa-tests-drones-to-find-and-assess-injured-victims-at-the-triage-challenge/","d":"2026-11-23","x":"A DARPA drónokat tesztel a Triage Challenge keretében, hogy tömeges balesetek után felkutassák és értékeljék a sérült áldozatokat. A cél az, hogy a drónok segítségével gyorsan koordinálják a sérültek ellátását. A verseny célja a drónok hatékonyságának növelése a sürgősségi helyzetek kezelésében.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás"],"oc":["United States"],"p":7,"cm":2,"cid":14060},{"id":14105,"s":"Defense News","sz":"T2","t":"DARPA tests drones to find and assess injured victims at the Triage Challenge","th":"DARPA drónokat tesztel a sérült áldozatok felkutatására és értékelésére a Triage Challenge keretében","u":"https://www.defensenews.com/video/2026/11/23/darpa-tests-drones-to-find-and-assess-injured-victims-at-the-triage-challenge/","d":"2026-11-23","x":"A DARPA drónokat tesztel a tömeges áldozatokat követő események során a sérültek felkutatására és ellátásuk koordinálására. A cél az, hogy a drónok segítségével gyorsan megtalálják és értékeljék a sérülteket, valamint megkezdjék a szükséges orvosi ellátás megszervezését. A Triage Challenge során a legjobban teljesítő csapatokat is díjazzák.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás"],"oc":["United States"],"p":7,"cm":2,"cid":14060},{"id":14067,"s":"DefenseScoop","sz":"T2","t":"Marine Corps moving new chatbot prototyped at recent hackathon into full production","th":"A Tengerészgyalogság új chatbotot indít el a legutóbbi hackathon prototípusából","u":"https://defensescoop.com/2026/11/23/marine-corps-chatbot-hackathon-full-production/","d":"2026-11-23","x":"A Tengerészgyalogság egy hackathon keretében kifejlesztett chatbotot tervez teljes körű gyártásba állítani. A hackathon során a résztvevők mesterséges intelligencia alapú eszközöket hoztak létre, amelyek célja a Tengerészgyalogság közösségi szolgáltatásainak támogatása. A chatbot a MCCS Connect mobilalkalmazáson keresztül nyújt segítséget a tengerészeknek és családjaiknak. A projekt során kiemelt figyelmet fordítottak a biztonsági intézkedésekre, különösen a szenzitív kérdések kezelésére. A Tengerészgyalogság célja, hogy a technológia segítségével javítsa a katonák életminőségét és közösségi élményeit.","dom":"CYB","br":"Híradó és informatikai csapatok","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":7,"cm":1,"cid":14067},{"id":14068,"s":"DefenseScoop","sz":"T2","t":"DISA boss highlights need for training, standardization to prepare for new era of ZT and AI-enabled cyber warfare","th":"A DISA vezetője hangsúlyozza a képzés és a standardizálás szükségességét az új ZT és AI-alapú kibertámadások korában","u":"https://defensescoop.com/2026/11/23/ai-cyber-warfare-zero-trust-lt-gen-stanton/","d":"2026-11-23","x":"A DISA vezetője, Paul Stanton tábornok hangsúlyozta, hogy az Egyesült Államok hadseregének megfelelő képzést és architektúrákat kell kialakítania a nulla bizalom (ZT) és az AI-alapú kiberműveletek hatékony működéséhez. A Pentagon célja, hogy 2027 végére elérje a 'cél szintű' ZT érettséget. Stanton kiemelte, hogy a jól képzett személyzet elengedhetetlen a komplex ZT környezet működtetéséhez, és figyelmeztetett, hogy a hadseregnek automatizálnia kell a konfigurációs változásokat, hogy lépést tudjon tartani az AI-t használó ellenfelekkel. A kibertámadásokkal szembeni védelem érdekében a DOD-nak standardizálnia kell architektúráját, hogy gyorsan reagálhasson a változó operatív környezetre.","dom":"CYB","br":"Védelmi kiberműveletek","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":8,"cm":1,"cid":14068,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. ZT és AI-alapú kibervédelem fejlesztése."},{"id":14093,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"F-35 Demo Team Returns to Luke Ahead of 2027 Season","th":"F-35 Demócsapat visszatér Lukába a 2027-es szezon előtt","u":"https://www.airandspaceforces.com/f-35-demo-team-returns-to-luke-2027-season/","d":"2026-11-23","x":"Az Egyesült Államok Légierő F-35A Lightning II Demócsapata hét év után visszatér a Lukai Légibázisra, ahol a 2027-es légibemutató szezonra készül. A csapat a Hill Légibázisról került áthelyezésre, ahol 2019 óta működött. A demócsapat célja, hogy bemutassa az F-35A fejlett képességeit, és hangsúlyozza a légierő szerepét. A csapat tagjai között pilóták, karbantartók és közönségkapcsolati szakemberek találhatók. A Lukai Légibázis az F-35 pilóták képzésének központja, beleértve a szövetséges országok, például a Hollandia és Dánia pilótáit is.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)","Légi szállítás és utántöltés"],"oc":["United States"],"p":7,"cm":1,"cid":14093},{"id":14103,"s":"Defense News","sz":"T2","t":"China’s fourth aircraft carrier, bigger than others and nuclear-powered, nears completion","th":"Kína negyedik repülőgép-hordozója, amely nagyobb és nukleáris meghajtású, közel a befejezéshez","u":"https://www.defensenews.com/global/asia-pacific/2026/11/23/chinas-fourth-aircraft-carrier-bigger-than-others-and-nuclear-powered-nears-completion/","d":"2026-11-23","x":"Kína negyedik repülőgép-hordozója, a Type 004, hamarosan elkészül, és nagyobb lesz elődeinél, valamint nukleáris meghajtással rendelkezik. A hajó 75-90 repülőgépet képes befogadni, és várhatóan 2027-ben áll szolgálatba. A nukleáris energia lehetővé teszi a gyorsabb felszállásokat, és a hajó globális telepítést is lehetővé tesz. A Type 004 mérete és kapacitása versenyképessé teszi a kínai flottát az Egyesült Államok haditengerészetével szemben. Kína a következő évtizedben további repülőgép-hordozókat tervez építeni, hogy kék vízi képességeit fejlessze.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet"],"oc":["China","United States","Japan"],"p":9,"cm":1,"cid":14103,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Nagyobb, nukleáris hajó közel a befejezéshez."},{"id":14129,"s":"Military Times","sz":"T2","t":"Under Hegseth, the OSS rides again — kind of","th":"Hegseth alatt újraéled az OSS - legalábbis névleg","u":"https://www.militarytimes.com/news/your-military/2026/11/23/under-hegseth-the-oss-rides-again-kind-of/","d":"2026-11-23","x":"Pete Hegseth védelmi miniszter újraélesztette az OSS-t, az Egyesült Államok második világháborús hírszerző és kommandós szervét. A november 2-án kiadott emlékirat célja, hogy a különleges műveletekért felelős államtitkárt az OSS államtitkárává nevezze ki. Az emlékirat emellett a különleges műveleti erők személyzetének és finanszírozásának bővítését is célul tűzi ki, mivel a Pentagon egyre inkább támaszkodik ezekre az erőkre. A különleges műveletek finanszírozása azonban nem tart lépést a növekvő igényekkel, így Hegseth emlékirata 45 millió dolláros forrásnövelést javasol. Az OSS története során a szervezet kulcsszerepet játszott a hírszerzés és a katonai műveletek összekapcsolásában.","dom":"MDO","br":"Különleges műveleti erők","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":8,"cm":1,"cid":14129,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. OSS névleges újraélesztése."},{"id":14117,"s":"Army Technology","sz":"T2","t":"Auterion and SkyFall plan German drone factory for Ukraine","th":"Auterion és SkyFall német dróngyárat tervez Ukrajnának","u":"https://www.army-technology.com/news/auterion-skyfall-drone-factory-ukraine/","d":"2026-11-23","x":"Az Auterion és a SkyFall közös vállalkozást tervez létrehozni, amely drónokat gyárt Ukrajnának egy új német gyárban. A gyár a 'Build with Ukraine' védelmi együttműködési keretén belül jön létre, és a német és ukrán kormányok támogatását élvezi. Az elsődleges termelés a SkyFall Shrike FPV platformjára összpontosít, amelyet nehéz üzemeltetési körülmények között terveztek. A gyár célja, hogy támogassa az ukrán drónellátást, miközben munkahelyeket teremt Németországban. A két cég eddig több mint 50,000 drónt szállított az ukrán erőknek.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Germany","Ukraine"],"p":8,"cm":2,"cid":13282},{"id":14127,"s":"Military Times","sz":"T2","t":"USS Theodore Roosevelt replaces USS George Washington in the Middle East","th":"USS Theodore Roosevelt váltja az USS George Washington-t a Közel-Keleten","u":"https://www.militarytimes.com/news/your-military/2026/11/23/uss-theodore-roosevelt-replaces-uss-george-washington-in-the-middle-east/","d":"2026-11-23","x":"A USS Theodore Roosevelt, a Nimitz-osztályú repülőgép-hordozó hivatalosan megkezdte működését a Közel-Keleten, hogy támogassa a tengeri biztonságot és stabilitást. A hajó érkezése egybeesik az Iránnal folytatott háborúval, amely hamarosan a kilencedik hónapjába lép. A Roosevelt szeptember 27-én indult San Diegóból, és várhatóan legalább hét hónapos bevetésre számíthat. A hajó az USS George Washington-t váltotta, amely három hónapot töltött a térségben. Az USS George Washington augusztus 19-én érkezett a Közel-Keletre, hogy helyettesítse az USS Abraham Lincoln-t, amely történelmi 10 hónapos bevetés után távozott.","dom":"MAR","br":"Felszíni harci hajók","sp":[],"oc":["United States","Iran"],"p":7,"cm":2,"cid":13293},{"id":13986,"s":"Breaking Defense","sz":"T2","t":"Army publishes guidebook for defending critical infrastructure at local installations","th":"A hadsereg útmutatót publikál a kritikus infrastruktúra védelmére helyi létesítményeknél","u":"https://breakingdefense.com/2026/11/army-publishes-guidebook-for-defending-critical-infrastructure-at-local-installations/","d":"2026-11-23","x":"A hadsereg közzétette az első olyan 'játékkönyvét', amely segít a létesítményeknek a kritikus infrastruktúra védelmi terveinek kidolgozásában és az érintett felekkel való koordinációban. A 'Defense Critical Infrastructure Community Coordination Guide' célja, hogy a katonai egységek szabadon elérhessék a kikötőket, vasutakat és repülőtereket válsághelyzetekben. A dokumentum öt fő részből áll, beleértve a gyorsindító útmutatót és a koordináció fontosságát tárgyaló fejezeteket. A cél, hogy a hadsereg felkészültebb legyen a jövőbeli incidensekre, és a közösségi koordinációs útmutató széles körben alkalmazható legyen az Egyesült Államok területén.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Vezetés-irányítás és ISR (C2/ISR)","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":7,"cm":1,"cid":13986},{"id":14101,"s":"Defense News","sz":"T2","t":"A race for lifesaving battlefield drones | Defense News Weekly Full Episode 11.24.26","th":"Verseny a életmentő csatatéri drónokért","u":"https://www.defensenews.com/video/2026/11/23/a-race-for-lifesaving-battlefield-drones-defense-news-weekly-full-episode-11-24-26/","d":"2026-11-23","x":"A cikk a csatatéri drónok életmentő szerepéről szól, különös figyelmet fordítva az ukrán innovátorokra, akik a frontvonalban dolgoznak a drónos evakuálás fejlesztésén. Ezen kívül a DARPA is AI-t támogató robotokat fejleszt, amelyek képesek megtalálni és felmérni a sérült katonákat és civileket. A verseny az életmentésért folyik.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás"],"oc":["Ukraine","United States"],"p":8,"cm":3,"cid":14057},{"id":14130,"s":"Military Times","sz":"T2","t":"A race for lifesaving battlefield drones | Defense News Weekly Full Episode 11.24.26","th":"Verseny az életmentő csatatéri drónokért","u":"https://www.militarytimes.com/video/2026/11/23/a-race-for-lifesaving-battlefield-drones-defense-news-weekly-full-episode-11-24-26/","d":"2026-11-23","x":"A cikk a csatatéren alkalmazott életmentő drónok fejlesztéséről szól. Miközben ukrán innovátorok a frontvonalban drónos evakuációs megoldásokat dolgoznak ki, a DARPA mesterséges intelligenciával támogatott robotokat fejleszt a sebesült katonák és civilek felkutatására és értékelésére. Az életmentésért folytatott verseny már megkezdődött.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","MI és autonómia"],"oc":["Ukraine","USA"],"p":8,"cm":3,"cid":14057},{"id":14102,"s":"Defense News","sz":"T2","t":"Ukraine strikes Russian warship and cargo vessel with naval drones in Libya","th":"Ukrajna tengeri drónokkal támadta meg az orosz hadihajót és teherhajót Líbiában","u":"https://www.defensenews.com/video/2026/11/23/ukraine-strikes-russian-warship-and-cargo-vessel-with-naval-drones-in-libya/","d":"2026-11-23","x":"Ukrajna tengeri drónokkal támadta meg az orosz hadihajót és teherhajót Líbiában. Volodimir Zelenszkij ukrán elnök elmondta, hogy hét tengeri drónt használtak a támadás során, amelynek következtében elsüllyedt az orosz Merkury korvett. A támadás jelentős esemény a tengeri hadviselés terén, és újabb példája az ukrán haditengerészet képességeinek.","dom":"MAR","br":"Felszíni harci hajók","sp":[],"oc":["Ukraine","Russia"],"p":7,"cm":3,"cid":14058},{"id":14133,"s":"Military Times","sz":"T2","t":"USS Doris Miller to keep its name, Navy says","th":"USS Doris Miller megtartja nevét, mondja a Haditengerészet","u":"https://www.militarytimes.com/news/your-military/2026/11/23/uss-doris-miller-to-keep-its-name-navy-says/","d":"2026-11-23","x":"A jövőbeli Ford-osztályú repülőgép-hordozó, a CVN-81, megtartja az USS Doris Miller nevet, amit a Haditengerészet megerősített. A hajó, amely az első fekete amerikai tisztre emlékezik, 2034 februárjára várhatóan elkészül. Doris Miller a Pearl Harbor-i támadás során hősies tetteivel vált ismertté, és az ő nevét viselő hajó építése a haditengerészet történetének fontos mérföldköve. A hajó építése a Newport News Shipbuildingnél zajlik, és a ceremoniális hajógerinc-állításra december 5-én kerül sor. Az USS Doris Miller név megtartása a Miller család számára is fontos, mivel a névadás a fekete amerikaiak elismerését is jelenti.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet"],"oc":["United States"],"p":7,"cm":1,"cid":14133},{"id":14134,"s":"Military Times","sz":"T2","t":"Army to detonate lead ammunition day before Thanksgiving","th":"Hadsereg: Ólomlőszerek robbantása Hálaadás előtt","u":"https://www.militarytimes.com/news/your-military/2026/11/23/army-to-detonate-lead-ammunition-day-before-thanksgiving/","d":"2026-11-23","x":"Az Egyesült Államok Hadserege másodszor halasztotta el egy instabil lőszerraktár robbantását egy iowai üzemben. Az új időpontot a kedvező időjárási viszonyok és a biztonsági intézkedések figyelembevételével tűzték ki. A hadsereg több mint 9,000 font degradált ólom-azidot tervez robbantani, amely egy érzékeny vegyület, és a közösség aggályait figyelembe véve a döntés ellen tiltakozások indultak. A robbantás után a levegőben megnövekedett ólomrészecskék várhatóak, és a hadsereg térképeket fog frissíteni az érintett területekről. Az Iowa állam kormányzója hangsúlyozta, hogy a lakosság egészségének védelme a legfontosabb prioritás.","dom":"LAND","br":"Tüzér és tűztámogatás","sp":["Lőszer és védelmi ipari kapacitás","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":7,"cm":1,"cid":14134},{"id":14025,"s":"Naval News","sz":"T2","t":"ASELSAN’s GÖKDENIZ Destroys High-Speed Jet Drone in Live-Fire Sea Trial","th":"ASELSAN GÖKDENIZ rendszere megsemmisítette a nagy sebességű jet drónt élő tűzpróbán","u":"https://www.navalnews.com/naval-news/2026/11/aselsans-gokdeniz-destroys-high-speed-jet-drone-in-live-fire-sea-trial/","d":"2026-11-23","x":"Az ASELSAN GÖKDENIZ haditengerészeti védelmi rendszere sikeresen megsemmisített egy jet UAV-t élő tűzpróbán. A rendszer automatikus célprioritizálással és egygombos indítással működik, lehetővé téve a gyors reagálást a felmerülő fenyegetésekre. A bemutató során a GÖKDENIZ képes volt észlelni, követni, támadni és megsemmisíteni a mozgó légi célt, amely a modern aszimmetrikus légi fenyegetések jellemzőit szimulálta. A rendszer félautonóm üzemmódban működött, csökkentve a reakcióidőt, és lehetővé téve a gyors válaszokat a haditengerészeti védelem időkritikus helyzeteiben. A GÖKDENIZ megoldásai nemcsak katonai hajók, hanem kereskedelmi hajók védelmét is szolgálják, bővítve a tengeri eszközök védelmét a felmerülő légi fenyegetések ellen.","dom":"MAR","br":"Haditengerészeti repülés és tengeri járőr","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Turkey"],"p":8,"cm":1,"cid":14025},{"id":14063,"s":"C4ISRNET","sz":"T2","t":"Ukraine confirms it sank Russian corvette in Libyan port","th":"Ukrajna megerősítette, hogy elsüllyesztette az orosz korvettet líbiai kikötőben","u":"https://www.c4isrnet.com/unmanned/2026/11/23/ukraine-confirms-it-sank-russian-corvette-in-libyan-port/","d":"2026-11-23","x":"Ukrajna megerősítette, hogy a Merkury nevű orosz korvettet elsüllyesztette a líbiai Benghazi kikötőjében. Az ukrán elnök, Volodymyr Zelenskyy elmondta, hogy az akció során hét ukrán gyártmányú tengeri drónt használtak. A támadás következtében a korvett nagyrészt elsüllyedt, és egy Ka-27 helikopter is megsemmisült. A támadás a háború földrajzi kiterjedésének egyik legszembetűnőbb példája, amelyben Ukrajna és Oroszország közötti konfliktusok egyre inkább megjelennek Afrikában is. A helyzet tovább bonyolítja a líbiai politikai megosztottság, amely az orosz támogatású keleti kormány és a nemzetközileg elismert nyugati kormány között húzódik.","dom":"MAR","br":"Felszíni harci hajók","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Ukraine","Russia","Libya"],"p":8,"cm":2,"cid":14063},{"id":14108,"s":"Defense News","sz":"T2","t":"Ukraine confirms it sank Russian corvette in Libyan port","th":"Ukrajna megerősítette, hogy elsüllyesztette az orosz korvettet líbiai kikötőben","u":"https://www.defensenews.com/global/mideast-africa/2026/11/23/ukraine-confirms-it-sank-russian-corvette-in-libyan-port/","d":"2026-11-23","x":"Ukrajna megerősítette, hogy a Merkury nevű orosz korvettet elsüllyesztette a líbiai Bengáziban. Az akció során hét ukrán gyártmányú tengeri drónt használtak, amelyek a hajó oldalának csapódtak. Az ukrán hadsereg közleménye szerint a műveletet a Biztonsági Szolgálat közösen hajtotta végre a védelmi erőkkel. A támadás következtében a hajó nagy része víz alá került, és a helyszínen több sérült is volt. Az esemény a háború földrajzi kiterjedésének egyik legszembetűnőbb példája, mivel Líbiában a politikai megosztottság miatt Ukrajna és Oroszország közötti konfliktusok várhatóak.","dom":"MAR","br":"Felszíni harci hajók","sp":["Drónok és drónelhárítás"],"oc":["Ukraine","Russia","Libya"],"p":8,"cm":2,"cid":14063},{"id":13896,"s":"Modern War Institute","sz":"T1","t":"“We Fight Differently” Is Not a Plan: The Risk of Dismissing Ukraine’s Drone Warfare Lessons","th":"A 'Másképp Harcolunk' Nem Terv: A Kockázat, Hogy Figyelmen Kívül Hagyjuk Ukrajna Drón Háborús Tanulságait","u":"https://mwi.westpoint.edu/we-fight-differently-is-not-a-plan-the-risk-of-dismissing-ukraines-drone-warfare-lessons/","d":"2026-11-23","x":"A cikk bemutatja, hogy az Egyesült Államok hadserege nem tanul eleget Ukrajna drónhadviseléséből, ami komoly hiányosságokat eredményezhet. A szerző, James L. Andreasen, hangsúlyozza, hogy a 'másképp harcolunk' érvelés nem indokolt, és a hadseregnek sürgősen alkalmaznia kell a drónokkal kapcsolatos tapasztalatokat. Az amerikai és ukrán erők közötti gyakorlat során a ukrán dróncsapatok jelentős előnyre tettek szert, ami rávilágít a jelenlegi hadsereg doktrínájának hiányosságaira. A cikk arra figyelmeztet, hogy a hadseregnek fel kell készülnie a drónokkal szembeni harcra, és meg kell védenie azokat az alapokat, amelyek lehetővé teszik a manőverezést. A drónok integrálása és a megfelelő felkészülés elengedhetetlen a jövőbeli harci helyzetekhez.","dom":"AIR","br":"Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["United States","Ukraine"],"p":8,"cm":1,"cid":13896},{"id":14024,"s":"Naval News","sz":"T2","t":"Royal Thai Navy Forced to Retender Frigate Programme","th":"A Thaiföldi Királyi Haditengerészet kénytelen újra kiírni a fregatt programot","u":"https://www.navalnews.com/naval-news/2026/11/royal-thai-navy-forced-to-retender-frigate-programme/","d":"2026-11-23","x":"A Thaiföldi Királyi Haditengerészet (RTN) kénytelen volt lemondani és újra kiírni fregatt programját, miután eljárási hibák miatt megsemmisítették a Hanwha Ocean által benyújtott ajánlatot. A tender folyamata során több nemzetközi hajógyártó is részt vett, de a Hanwha Ocean volt az egyetlen, amely megfelelt a minősítési követelményeknek. A tender törlését követően a RTN új bizottságokat kell felállítson, és a friss pályázati folyamat körülbelül hat hónapot vesz igénybe. A haditengerészet hangsúlyozta, hogy a közérdek védelme érdekében tiszta és átlátható eljárást kíván biztosítani. A helyi hajógyártók is részt vesznek a programban, amely a technológia átadását és a hazai tartalom minimum 20%-os arányát is előírja.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Beszerzés és védelmi költségvetés"],"oc":["Thailand","South Korea","Spain"],"p":7,"cm":1,"cid":14024},{"id":13871,"s":"War on the Rocks","sz":"T1","t":"While Shenzhen Talked, Berlin Pulled Up a Chair: Europe’s Generational Bet on Itself and Ukraine","th":"Míg Shenzhen beszélt, Berlin leült: Európa generációs fogadása önmagára és Ukrajnára","u":"https://warontherocks.com/while-shenzhen-talked-berlin-pulled-up-a-chair-europes-generational-bet-on-itself-and-ukraine/","d":"2026-11-23","x":"A 37. Ramstein találkozón a szövetségesek új légvédelmi támogatást ígértek Ukrajnának, mivel az orosz dróntámadások folyamatos áramszüneteket okoznak. Németország és Norvégia egyenként 300 millió dollárt fordít a Patriot rakétákra, de a mennyiségek és időkeretek még nem nyilvánosak. Az Egyesült Királyság 240 millió fontos csomagja több mint 1000 rövid hatótávolságú rakétát és radart tartalmaz, amelyek várhatóan december közepén érkeznek. Zelenszkij elnök javasolta, hogy a partnerek kölcsönözzék a Patriot és IRIS-T rakétákat saját készleteikből, amelyeket később pótolnának. A szállítási sebesség döntő fontosságú lesz Ukrajna téli védelme szempontjából.","dom":"AIR","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Lőszer és védelmi ipari kapacitás","Haderő-modernizáció és erőszerkezet"],"oc":["Germany","Norway","United Kingdom","Ukraine"],"p":8,"cm":1,"cid":13871,"sp2":58,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Új légvédelmi támogatás Ukrajnának."},{"id":13990,"s":"Breaking Defense","sz":"T2","t":"Yes, no, maybe? The countries that can (or can’t) deliver Ukraine’s 40 requested F-16s","th":"Igen, nem, talán? Az országok, amelyek képesek (vagy nem képesek) szállítani Ukrajnának a kért 40 F-16-ost","u":"https://breakingdefense.com/2026/11/yes-no-maybe-the-countries-that-can-or-cant-deliver-ukraines-40-requested-f-16s/","d":"2026-11-23","x":"Volodimir Zelenszkij ukrán elnök a közelmúltban 40 F-16-os vadászgép szállítását kérte a nyugati szövetségesektől, hogy megerősítse Ukrajna légvédelmét. A kérdés, hogy mely országok tudják ezt a mennyiséget biztosítani, különösen nehéz, mivel a legtöbb európai ország nem tudja feláldozni saját légierőjét. Belgium már bejelentette, hogy 10 F-16-ost küld Ukrajnának, de más országok, mint például Görögország, elutasították a gépek átadását. A szállítások bonyolultságát tovább növeli a politikai helyzet és a közelgő választások is, amelyek befolyásolhatják a döntéseket.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["Ukraine","Belgium","Norway","Greece"],"p":8,"cm":1,"cid":13990,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. F-16-os vadászgépek szállítása Ukrajnának."},{"id":13988,"s":"Breaking Defense","sz":"T2","t":"Umbra, ICEYE tout higher-resolution radar imaging with new satellites","th":"Umbra és ICEYE új, nagyobb felbontású radaros képek a műholdakkal","u":"https://breakingdefense.com/2026/11/umbra-iceye-tout-higher-resolution-radar-imaging-with-new-satellites/","d":"2026-11-23","x":"Umbra és ICEYE, a világ két vezető szintetikus apertúrás radar (SAR) képkészítő cége, új műholdakat indít, amelyek öt centiméteres felbontású képeket kínálnak. Az Umbra Freetail 5 műholdja 2028-ban fog repülni, míg az ICEYE Gen5 műholdjai 11 centiméteres felbontású képeket tudnak biztosítani. A műholdak reprogramozható szoftverrel és fedélzeti feldolgozási képességekkel rendelkeznek, amelyek növelik a képfeldolgozás gyakoriságát. A SAR képkészítés különösen hasznos az európai ügyfelek számára, mivel a régió gyakori felhőborítottsága korlátozhatja a hagyományos optikai műholdak hatékonyságát.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Világűr- és műholdképességek"],"oc":["United States","Finland"],"p":8,"cm":1,"cid":13988,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új SAR műholdak indítása."},{"id":14135,"s":"Military Times","sz":"T2","t":"Ukraine strikes Russian warship and cargo vessel with naval drones in Libya","th":"Ukrajna tengeri drónokkal támadta meg az orosz hadihajót és teherhajót Líbiában","u":"https://www.militarytimes.com/video/2026/11/23/ukraine-strikes-russian-warship-and-cargo-vessel-with-naval-drones-in-libya/","d":"2026-11-23","x":"Ukrajna tengeri drónokkal támadta meg az orosz hadihajót és teherhajót Líbiában. Volodymyr Zelenskyy ukrán elnök elmondta, hogy a támadás során hét tengeri drónt használtak, amelyek elsüllyesztették az orosz Merkury korvettet.","dom":"MAR","br":"Felszíni harci hajók","sp":[],"oc":["Ukraine","Russia"],"p":7,"cm":3,"cid":14058},{"id":13590,"s":"Atlantic Council","sz":"T1","t":"Dispatch from 2032: After Chinese salvos fail to defeat Taiwan, Beijing is trapped in a war of attrition","th":"Közlemény 2032-ből: Miután a kínai támadások nem tudták legyőzni Taiwant, Peking egy elhúzódó háborúba került","u":"https://www.atlanticcouncil.org/dispatches/dispatch-from-2032-after-chinese-salvos-fail-to-defeat-taiwan-beijing-is-trapped-in-a-war-of-attrition/","d":"2026-11-23","x":"A cikk a 2032-es eseményeket elemzi, amikor Kína első rakétái és drónjai megpróbálták megtámadni Taiwant, de a T-Dome, Taiwan többrétegű légvédelmi rendszere, váratlanul hatékonyan működött. A támadások során a T-Dome 90%-os hatékonysággal semlegesítette a kínai munitiók többségét, lehetővé téve Taiwan számára, hogy ellentámadást indítson. A cikk hangsúlyozza, hogy Taiwan nem volt tehetetlen, és a kínai inváziós terveket sikerült megakadályozni. A konfliktus során Taiwan folyamatosan kapott támogatást az Egyesült Államoktól és Japántól, ami tovább növelte a védekezési képességeit. A háború elhúzódása és a Taiwan által elért eredmények a politikai és pszichológiai hatások szempontjából is jelentősek voltak.","dom":"MDO","br":"Lövész és gépesített lövész csapatok","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["China","Taiwan","United States","Japan"],"p":9,"cm":1,"cid":13590,"sp2":32,"ind":"Jelentőség 1/5, újdonság 1/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Jövőbeli elemzés, nem aktuális fejlemény."},{"id":14132,"s":"Military Times","sz":"T2","t":"B-2 bomber wings awarded Presidential Unit Citation for Midnight Hammer","th":"B-2 bombázó szárnyak elnyerték az Elnöki Egységkitüntetést a Midnight Hammer műveletért","u":"https://www.militarytimes.com/news/2026/11/23/b-2-bomber-wings-awarded-presidential-unit-citation-for-midnight-hammer/","d":"2026-11-23","x":"Két bombázó szárny, a 509. és a 131. Bomb Wing, Elnöki Egységkitüntetést kapott a Midnight Hammer műveletben végzett munkájukért. A művelet során a legnagyobb B-2 Spirit csomagot indították, amely iráni nukleáris létesítmények ellen irányult. A B-2 bombázók összesen 420,000 font robbanóanyagot szállítottak, beleértve a bunker-buster bombákat is. A művelet 125 repülőgépet vonultatott fel, és a siker érdekében több mint 4,000 légierő katona működött együtt. Ez az első alkalom, hogy bombázó egység kapott Elnöki Egységkitüntetést a vietnami háború óta.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Iran"],"p":9,"cm":2,"cid":13378,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Kitüntetés hír, nem új képesség vagy rendszer."},{"id":14116,"s":"Army Technology","sz":"T2","t":"Renk, BAE Systems, Forterra team up on autonomous US Army AMPV","th":"Renk, BAE Systems és Forterra együttműködik az amerikai hadsereg AMPV autonóm fejlesztésén","u":"https://www.army-technology.com/news/renk-bae-systems-forterra-ampv/","d":"2026-11-23","x":"A Renk America, a BAE Systems és a Forterra együttműködik az amerikai hadsereg Armoured Multi-Purpose Vehicle (AMPV) autonóm vezetési képességének fejlesztésén, amelynek első bemutatója 2027 februárjára van tervezve. Az autonóm AMPV-t a hadsereg éves konferenciáján mutatták be. A fejlesztés része a BAE Systems gyors képességfejlesztési kezdeményezésének, amely célja az új technológiák integrálásának felgyorsítása a hadsereg járműflottájába. A Renk America HMPT hajtóműve már jelenleg is használatban van az amerikai hadsereg közepes lánctalpas járműflottájában. Az AMPV az M113 járműcsalád helyettesítésére készül, öt változatban, beleértve a General Purpose, Mortar Carrier, Mission Command, Medical Treatment és Medical Evacuation verziókat.","dom":"LAND","br":"Harckocsizó (páncélos) csapatok","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás"],"oc":["United States"],"p":8,"cm":1,"cid":14116,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. AMPV autonóm fejlesztése."},{"id":13592,"s":"Atlantic Council","sz":"T1","t":"What NATO allies can learn from World War II partnerships about defense industrial production","th":"Mit tanulhatnak a NATO szövetségesek a második világháborús partnerségekből a védelmi ipari termelésről?","u":"https://www.atlanticcouncil.org/dispatches/what-nato-allies-can-learn-from-world-war-ii-partnerships-about-defense-industrial-production/","d":"2026-11-23","x":"A NATO szövetségesek számára világossá vált, hogy sürgősen növelniük kell a védelmi ipari termelést, különösen Oroszország ukrajnai háborúja és hibrid hadviselése miatt. A második világháború ipari tapasztalatai hasznos tanulságokat kínálnak a mai védelmi ipari problémák megoldásához. A szövetségeseknek együtt kell működniük a kritikus ellátási láncok megerősítése érdekében, és a közös fejlesztés, gyártás és fenntartás elősegíti az innovációt és a kapacitás növelését. Az ipari kapacitás bővítése és a kutatás-fejlesztési költségvetések prioritása elengedhetetlen a védelmi innovációhoz. A szövetségesek célja, hogy a következő évben végrehajtsák a szükséges lépéseket a védelmi termelés és ipari kapacitás bővítése érdekében.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet","Lőszer és védelmi ipari kapacitás"],"oc":["United States","Netherlands"],"p":8,"cm":1,"cid":13592,"sp2":32,"ind":"Jelentőség 1/5, újdonság 1/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Történelmi elemzés, nem új fejlemény."},{"id":14095,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"3 Launches in 2 Weeks: Space Data Network ‘Backbone’ Takes Shape","th":"3 Indítás 2 Hét Alatt: A Űr Adathálózat 'Gerince' Formálódik","u":"https://www.airandspaceforces.com/space-force-data-network-backbone-takes-shape/","d":"2026-11-23","x":"Az Egyesült Államok Űrerőinek új Űr Adathálózatának gerince formálódik, mivel számos új kommunikációs műhold indítása várható. A Space Force megerősítette, hogy három sikeres indítást hajtottak végre két héten belül, amelyek az első SDN-Gerinc műholdakat állították pályára. A program célja, hogy biztonságos és gyors adatmozgást biztosítson a globális katonai műveletekhez. A műholdak kormányzati tulajdonban és irányítás alatt állnak, és a tervek szerint regionális képességeket nyújtanak az év végéig, globális támogatással pedig a következő évben.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Világűr- és műholdképességek","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":14095,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új űr adathálózat műholdak indítása."},{"id":14026,"s":"Naval News","sz":"T2","t":"Japan Confirms Ten-Shot Railgun Test Using Battery-Based Power Supply","th":"Japán megerősítette a tíz lövéses railgun tesztet akkumulátoros energiaellátással","u":"https://www.navalnews.com/naval-news/2026/11/japan-confirms-ten-shot-railgun-test-using-battery-based-power-supply/","d":"2026-11-23","x":"Japán Védelmi Technológiai és Logisztikai Ügynöksége (ATLA) megerősítette, hogy egy kísérleti elektromágneses railgun sikeresen lőtt ki tíz lövedéket egymás után 2026 május-júniusában. A teszt során a lövedékek átlagos csősebessége 245 m/s volt. Az ATLA célja a kompakt energiaellátó rendszerek fejlesztése, amelyek lehetővé teszik a railgunok ismételt lövéseit. A rendszer lítium-titanát akkumulátorokat és nagyfeszültségű kondenzátorokat használ, hogy biztosítsa a szükséges áramimpulzusokat a lövésekhez. A kutatás része a jövőbeli közepes kaliberű haditengerészeti railgunok fejlesztésének is.","dom":"MAR","br":"Felszíni harci hajók","sp":["Haderő-modernizáció és erőszerkezet","Lőszer és védelmi ipari kapacitás"],"oc":["Japan"],"p":8,"cm":1,"cid":14026},{"id":13872,"s":"War on the Rocks","sz":"T1","t":"China’s Growing Ambitions in Very Low Earth Orbit","th":"Kína növekvő ambíciói a nagyon alacsony Föld körüli pályán","u":"https://warontherocks.com/cogs-of-war/chinas-growing-ambitions-in-very-low-earth-orbit-2/","d":"2026-11-23","x":"A cikk Kína ambícióit tárgyalja a nagyon alacsony Föld körüli pályán, ahol a tervek szerint több mint 2200 műholdat kívánnak telepíteni 2030-ig. Ezek a műholdak lehetővé teszik a Kínai Népi Felszabadító Hadsereg számára, hogy részletesebb felderítést végezzen az Egyesült Államok erőiről, és javítsák a kínai katonai túlélőképességet konfliktus esetén. A cikk hangsúlyozza, hogy az Egyesült Államoknak reagálnia kell Kína űrképességeinek fejlődésére, és bővítenie kell saját űrképességeit. Kína már sikeresen végrehajtott több demonstrációs küldetést ezen a pályán, és a következő öt év kritikus időszaknak számít a számukra.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Világűr- és műholdképességek"],"oc":["China","United States"],"p":8,"cm":1,"cid":13872},{"id":13277,"s":"Breaking Defense","sz":"T2","t":"Despite Hegseth memo, Canada hasn’t seen changes to defense relationship with US, says DefMin","th":"Kanada nem tapasztalt változásokat az Egyesült Államokkal való védelmi kapcsolatában, mondja a védelmi miniszter","u":"https://breakingdefense.com/2026/11/canada-hasnt-seen-changes-to-defense-relationship-with-us-says-mcguinty/","d":"2026-11-21","x":"David McGuinty, Kanada védelmi minisztere a Halifax Nemzetközi Biztonsági Fórumon nyilatkozott arról, hogy Kanada meglepődött az Egyesült Államok védelmi kapcsolataival kapcsolatos változások hírére, de eddig nem tapasztaltak változást a katonai együttműködésben. A hírek szerint Pete Hegseth új korlátozásokat vezetett be az Egyesült Államok és Kanada védelmi kapcsolataiban, de a védelmi miniszter hangsúlyozta, hogy a két ország közötti együttműködés továbbra is folytatódik. Kanada célja, hogy kevesebb fegyvert vásároljon az Egyesült Államoktól, és több saját gyártású haditechnikai eszközt állítson elő. McGuinty bejelentette, hogy Kanada csatlakozik a NATO innovációs alaphoz, amely új lehetőségeket teremt a kanadai startupok számára.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["Canada","United States"],"p":7,"cm":1,"cid":13277,"sp2":26,"ind":"Jelentőség 1/5, újdonság 1/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Politikai nyilatkozat, ismert védelmi kapcsolatok."},{"id":13278,"s":"Breaking Defense","sz":"T2","t":"Senate gearing up to investigate Ukraine’s access to Starshield","th":"Szenátus vizsgálatot indít Ukrajna Starshield-höz való hozzáféréséről","u":"https://breakingdefense.com/2026/11/senate-gearing-up-to-investigate-ukraines-access-to-starshield/","d":"2026-11-21","x":"A szenátus vizsgálatot indít Ukrajna SpaceX Starshield-höz való hozzáférésének megértésére. Chris Coons szenátor szerint a Starshield működésének megszakítása civilek halálát okozza, és aláássa az Egyesült Államok megbízhatóságát mint biztonsági eszközök szállítóját. Ukrajna a Starshieldet használja drónműveleteihez, és a közelmúltban a szolgáltatás lelassulásáról számoltak be, amelyet a Pentagon vagy a SpaceX nem magyarázott meg. Coons ígéretet tett arra, hogy választ keres a helyzet okaira és következményeire. A vizsgálat része a Trump-adminisztráció esetleges korrupciós ügyeinek feltárására irányuló szélesebb körű törekvéseknek.","dom":"SPA","br":"Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)","sp":["Világűr- és műholdképességek","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Ukraine"],"p":7,"cm":1,"cid":13278,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Vizsgálat a Starshield hozzáférésről, új fejlemény."},{"id":13279,"s":"Breaking Defense","sz":"T2","t":"Air Force issues massive $16B contract for engine work to dozens of companies","th":"Légierő 16 milliárd dolláros szerződést kötött motorfejlesztésre számos céggel","u":"https://breakingdefense.com/2026/11/air-force-issues-massive-16b-contract-for-engine-work-to-dozens-of-companies/","d":"2026-11-20","x":"Az Egyesült Államok Légierője 16,1 milliárd dolláros szerződést hirdetett meg motorfejlesztési munkákra, amely a következő 15 évben valósulhat meg. A szerződést 58 vállalat kapta, akik kezdetben mindössze 1,000 dollárt kaptak. A szerződés célja a hajtóműtechnológia folyamatos fejlesztése, beleértve a technológiai érés, koncepciófejlesztés és integráció területeit. A Légierő új és hatékonyabb hajtóművek kifejlesztésére törekszik, amelyek a jövőbeli platformok, például az F-47 lopakodó vadászgép működtetésére is alkalmasak. A szerződés keretein belül a digitális környezet maximális kihasználására is törekednek. A hossz_megjegyzes:","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Lőszer és védelmi ipari kapacitás"],"oc":["United States"],"p":8,"cm":1,"cid":13279,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Nagy értékű szerződés, de nem új program."},{"id":13280,"s":"Breaking Defense","sz":"T2","t":"This counter-UAS system senses deep inside neighboring borders to detect and defeat drones","th":"Ez a drónelhárító rendszer mélyen a szomszédos határok mögé érzékel","u":"https://breakingdefense.com/2026/11/this-counter-uas-system-senses-deep-inside-neighboring-borders-to-detect-and-defeat-drones/","d":"2026-11-20","x":"A CACI SkyValor drónvédelmi rendszere hosszú távú érzékelést és rétegzett érzékelési architektúrát alkalmaz, hogy bővítse a drónok azonosításának és célba vételének távolságát. A rendszer célja, hogy a határok, katonai létesítmények és kritikus infrastruktúrák védelmét hatékonyabbá tegye, lehetővé téve a döntéshozók számára, hogy megfelelő választ válasszanak a drónfenyegetésekre. A SkyValor képes 75 kilométeres távolságból észlelni a drónokat, ami jelentős taktikai előnyt biztosít az operátorok számára. A rendszer nemcsak a drónok észlelésére, hanem azok semlegesítésére is képes, alacsony vagy nulla kísérő kár mellett, így a drónokkal szembeni védekezés hatékonyabbá válik. A SkyValor a legújabb technológiákat alkalmazza a drónokkal szembeni védekezés terén, és képes alkalmazkodni a folyamatosan változó fenyegetésekhez.","dom":"CYB","br":"Híradó és informatikai csapatok (CIS)","sp":["Drónok és drónelhárítás","Vezetés-irányítás és ISR (C2/ISR)","MI és autonómia"],"oc":["United States"],"p":8,"cm":1,"cid":13280,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új drónelhárító rendszer, de nem rendszerbe állítás."},{"id":13282,"s":"Breaking Defense","sz":"T2","t":"Autonomy firm Auterion to launch joint venture with Ukrainian drone maker Skyfall","th":"Autonóm cég, az Auterion közös vállalkozást indít az ukrán Skyfall dróngyártóval","u":"https://breakingdefense.com/2026/11/autonomy-firm-auterion-to-launch-joint-venture-with-ukrainian-drone-maker-skyfall/","d":"2026-11-20","x":"Az Auterion, egy amerikai autonóm szoftvercég, közös vállalkozást indít az ukrán Skyfall dróngyártóval, hogy drónokat gyártsanak Ukrajna számára egy új német gyárban. A Skyfall X Auterion néven létrejövő vállalkozás kezdetben a Shrike FPV platformra összpontosít, később pedig a Skyfall interceptorokra és közepes- illetve mélycsapású rendszerekre is kiterjed. A német gyár lehetővé teszi a gyártási kapacitás növelését, miközben a Skyfall mérnökei közvetlen visszajelzéseket kapnak a frontról. A német kormány finanszírozást biztosít az új gyárhoz és a drónrendelésekhez, amelyek elsődlegesen Ukrajnának, majd a német fegyveres erőknek szólnak. A közös vállalkozás célja, hogy a német erők is hozzáférjenek a már Ukrajnában használt drónokhoz.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["United States","Ukraine","Germany"],"p":8,"cm":2,"cid":13282,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új közös vállalkozás, de nem rendszerbe állítás."},{"id":13283,"s":"Breaking Defense","sz":"T2","t":"Sweden’s Nordic Air Defence launches K200 drone interceptor, pushes toward Ukraine tests","th":"Svédország északi légvédelme bemutatja a K200 drónelhárítót, tesztelés Ukrajnában","u":"https://breakingdefense.com/2026/11/swedens-nordic-air-defence-launches-k200-drone-interceptor-pushes-toward-ukraine-tests/","d":"2026-11-20","x":"A svéd Nordic Air Defence bemutatta K200 nevű autonóm drónelhárítóját, amelyet Ukrajnában fognak tesztelni. A K200 a Kreuger 100XR utódja, és célja, hogy hatékonyan lépjen fel a jet-meghajtású támadó drónok ellen, beleértve az orosz Geran-3a-t is. A rendszer képes a hagyományos légvédelmi rakéták költségeinek töredékéért védeni a hadseregeket, miközben gyorsabb és nehezebb robbanófejet hordoz. A K200 integrálva van autonóm irányítással, és képes a meglévő légvédelmi rendszerekkel való együttműködésre is. A tesztelés célja a rendszer további fejlesztése és piacra vitele több országban.","dom":"AIR","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Sweden","Ukraine","Russia"],"p":8,"cm":1,"cid":13283,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új drónelhárító tesztelése, de nem rendszerbe állítás."},{"id":13285,"s":"Breaking Defense","sz":"T2","t":"One data foundation and many application layers drive the Army’s NGC2 transformation","th":"Az adatalap és a sok alkalmazási réteg vezeti a Hadsereg NGC2 átalakulását","u":"https://breakingdefense.com/2026/11/one-data-foundation-and-many-application-layers-drive-the-armys-ngc2-transformation/","d":"2026-11-20","x":"Az Egyesült Államok Hadseregének NGC2 (Next Generation Command and Control) programja egy közös adatalapra épül, amely lehetővé teszi a különböző hadműveleti funkciók közötti interoperabilitást. A cél egy olyan kompozit architektúra kialakítása, amely lehetővé teszi új szoftverek, fegyverek és érzékelők integrálását. A program során a 25. Gyalogos Dandár Hawaii-ban demonstrálta az adatok megosztását, amely javította a valós idejű helyzetképet és a célzási időt. Az NGC2 megközelítése lehetővé teszi a katonák számára, hogy közvetlen visszajelzést adjanak a rendszerek használata során, így a fejlesztések gyorsan megvalósulhatnak. Az AI alkalmazása is része a rendszernek, amely segíti a katonai döntéshozatalt.","dom":"LAND","br":"Tüzér és tűztámogatás","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Philippines"],"p":8,"cm":1,"cid":13285,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új program, de nem rendszerbe állítás."},{"id":13292,"s":"The War Zone","sz":"T2","t":"Ukraine’s Campaign Against Russian Naval Assets Far Beyond The Black Sea Enters A New Phase","th":"Ukrajna hadjárata az orosz tengeri eszközök ellen új szakaszba lépett","u":"https://www.twz.com/sea/ukraines-campaign-against-russian-naval-assets-far-beyond-the-black-sea-enters-a-new-phase","d":"2026-11-22","x":"Ukrajna hadjárata az orosz tengeri eszközök ellen új szakaszba lépett, miután ukrán drónok támadást indítottak orosz hadihajók ellen a Fekete-tengeren túli területeken. Az ukrán tengeri drónok sikeresen eltalálták a Merkury nevű orosz korvettet, amely a líbiai Bengháziban dokkolt. A támadás során a hajó súlyosan megsérült és elsüllyedt. A Merkury egy modern orosz hadihajó, amely 2023-ban állt szolgálatba, és a Fekete-tengeri Flottához tartozik. A támadások részeként egy orosz teherszállító hajó is célponttá vált, amely fegyvereket és drónokat szállított. Az események újabb jelei annak, hogy Ukrajna fokozza a nyomást az orosz tengeri képességekre a Földközi-tengeren.","dom":"MAR","br":"Felszíni harci hajók","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Ukraine","Russia","Libya"],"p":8,"cm":1,"cid":13292,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új támadás, jelentős hadműveleti fejlemény."},{"id":13293,"s":"The War Zone","sz":"T2","t":"USS Theodore Roosevelt Arrives In The Middle East, Relieving USS George Washington","th":"USS Theodore Roosevelt megérkezett a Közel-Keletre, leváltva az USS George Washington-t","u":"https://www.twz.com/sea/theodore-roosevelt-strike-group-arrives-in-the-middle-east-relieving-uss-george-washington","d":"2026-11-21","x":"Az USS Theodore Roosevelt megérkezett a Közel-Keletre, ahol az USS George Washington-t váltotta. Jelenleg három amerikai repülőgép-hordozó tartózkodik a térségben, de a George Washington CSG már elhagyta a régiót. A haditengerészet vezetői jelezték, hogy a flotta a következő öt évben kilenc hordozóval fog működni, ami két hajóval kevesebb, mint a törvény által előírt tizenegy. A blokád Irán partjainál továbbra is érvényben van, és az amerikai erők válaszul csapásokat mértek Qeshm szigetére. A haditengerészet folyamatosan dolgozik az önálló felszíni járművek fejlesztésén is.","dom":"MAR","br":"Haditengerészeti repülés és tengeri járőr","sp":["Hajóépítés és haditengerészet"],"oc":["United States"],"p":8,"cm":2,"cid":13293,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Rutin hajócsere, nem jelentős újdonság."},{"id":13298,"s":"The War Zone","sz":"T2","t":"Mysterious MQ-25 Stingray-Like Chinese Drone Emerges At Little-Known Flight Test Center","th":"Rejtélyes, MQ-25 Stingray-ra hasonlító kínai drón bukkant fel egy kevésbé ismert repülési tesztközpontban","u":"https://www.twz.com/air/mysterious-mq-25-stingray-like-chinese-drone-emerges-at-little-known-flight-test-center","d":"2026-11-20","x":"A Puchengben, Kínában készült műholdfelvételek egy szokatlan pilóta nélküli repülőgépet mutatnak, amely erős hasonlóságokat mutat a Boeing MQ-25 Stingray-jével. A drón funkciója még ismeretlen, de a létesítmény egyre fontosabb központtá válik Kína növekvő pilóta nélküli repülőgép iparában. A drón méretei alapján a kínai UAV körülbelül 20%-kal kisebb, mint az MQ-25, ami kevesebb üzemanyagot jelent. A fejlesztések összhangban állnak Kína ambiciózus törekvéseivel, hogy integrálja a pilóta nélküli repülőgépeket a jövőbeli haditengerészeti légierőbe.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["China"],"p":7,"cm":1,"cid":13298,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új kínai drón megjelenése, ismeretlen funkció."},{"id":13317,"s":"Defense One","sz":"T2","t":"Canada joins NATO innovation fund, promises ‘business as usual’ with US","th":"Kanada csatlakozik a NATO innovációs alaphoz, ígéri, hogy 'minden a megszokott módon' folytatódik az Egyesült Államokkal","u":"https://www.defenseone.com/policy/2026/11/canada-joins-nato-innovation-fund-promises-business-usual-us/417391/","d":"2026-11-21","x":"Kanada bejelentette, hogy 100 millió kanadai dollárt fektet a NATO védelmi innovációs alapjába, válaszul az Egyesült Államok védelmi együttműködésének csökkenésére. A NATO innovációs alap célja, hogy összekapcsolja a startupokat a befektetőkkel és a katonai felhasználókkal, segítve a sikeres megoldások skálázását. Kanada döntése a kollektív cselekvés melletti fogadást jelenti, mivel a pénzek közvetlenül kanadai cégekhez is eljuthattak volna. A bejelentés a Trump-adminisztráció által a kanadai termékekre kivetett vámokkal egy időben történt, ami tovább bonyolítja a két ország közötti védelmi együttműködést.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["Canada","United States"],"p":7,"cm":1,"cid":13317,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Politikai nyilatkozat, ismert NATO együttműködés."},{"id":13318,"s":"Defense One","sz":"T2","t":"The military lacks an ‘overarching plan’ to improve munition stockpiles—partly because it’s no one’s job","th":"A hadseregnek nincs 'átfogó terve' a lőszerraktárak javítására - részben mert senkinek sem ez a feladata","u":"https://www.defenseone.com/threats/2026/11/military-lacks-munitions-plan/417390/","d":"2026-11-21","x":"A Pentagon nem rendelkezik átfogó tervvel a lőszerraktárak javítására, ami a katonai készletek hiányosságait eredményezi. A Kormányzati Számvevőszék (GAO) tanulmánya szerint a hadsereg túl reakciós a globális eseményekre, és nem képes előre jelezni saját szükségleteit. A jelentés hangsúlyozza, hogy a DOD-nak szüksége van egy hosszú távú tervre a lőszerek termelésének javítására, hogy megfeleljen a követelményeknek. A Pentagon tisztviselői egyetértenek a GAO ajánlásaival, de a hiányosságok kezeléséhez szükséges központosított hatalom hiányzik. A tanulmány arra figyelmeztet, hogy a lőszerek készletezése és nyomon követése nem megfelelő, ami a jövőbeni hadműveletek szempontjából is aggasztó.","dom":"MDO","br":"Tüzér és tűztámogatás","sp":["Lőszer és védelmi ipari kapacitás","Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":13318,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Általános probléma, nem új fejlemény."},{"id":13319,"s":"Defense One","sz":"T2","t":"Europeans, with Ukraine’s help, brace for more Russian attacks","th":"Az európaiak, Ukrajna segítségével, felkészülnek a további orosz támadásokra","u":"https://www.defenseone.com/threats/2026/11/europeans-ukraines-help-brace-more-russian-attacks/417389/","d":"2026-11-21","x":"Az európai NATO-tagok és Ukrajna közösen dolgoznak azon, hogy megakadályozzák Oroszország ukrajnai inváziójának befejezését Moszkva feltételei szerint. A német, francia és brit vezetők megerősítették, hogy 70 milliárd euró értékű katonai felszerelést, támogatást és képzést nyújtanak Ukrajnának. Az EU is 60 milliárd eurót ígért a védelemre és 30 milliárdot költségvetési támogatásra. A NATO és ukrán tisztviselők a technológiai konferencián mélyítették el kapcsolataikat, és a hibrid támadásokra válaszul a tagállamok növelik a hírszerzési és felderítési kiadásaikat.","dom":"MDO","br":"Lövész és gépesített lövész csapatok","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)","Drónok és drónelhárítás"],"oc":["Ukraine","Russia","Germany","France"],"p":8,"cm":1,"cid":13319,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Ismert támogatás, nem új információ."},{"id":13320,"s":"Defense One","sz":"T2","t":"New guide lays out how Army installations can coordinate with local agencies before disaster strikes","th":"Új útmutató az amerikai hadsereg telephelyeinek helyi ügynökségekkel való együttműködéséről katasztrófa előtt","u":"https://www.defenseone.com/threats/2026/11/new-guide-lays-out-how-army-installations-can-coordinate-local-agencies-disaster-strikes/417377/","d":"2026-11-20","x":"Az amerikai hadsereg új útmutatót adott ki, amelyben a telephelyeik és a helyi ügynökségek közötti együttműködés fontosságát hangsúlyozza katasztrófák esetén. A kézikönyv a második Védelmi Kritikus Infrastruktúra csúcsértekezlet után jelent meg, és célja, hogy elősegítse a kommunikációt a helyi kormányokkal és szolgáltatókkal. A hadsereg hangsúlyozza, hogy a telephelyek működése szorosan összefonódik a helyi közösségekkel, és a katasztrófákra való felkészülés érdekében már most el kell kezdeni az együttműködést. Az útmutató javaslatokat tartalmaz arra, hogyan lehet fenntartani a kapcsolatokat a válsághelyzetekben. A drónokkal kapcsolatos fenyegetések kiemelt figyelmet kapnak a védelmi intézkedések között.","dom":"LAND","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Vezetés-irányítás és ISR (C2/ISR)","Drónok és drónelhárítás"],"oc":["United States"],"p":7,"cm":1,"cid":13320,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Útmutató kiadása, nem új haditechnikai fejlemény."},{"id":13340,"s":"C4ISRNET","sz":"T2","t":"German attack drones pass live-fire tests, with first deliveries planned this year","th":"Német támadó drónok élő tűzpróbán, az első szállítmányok idén várhatóak","u":"https://www.c4isrnet.com/unmanned/2026/11/20/german-attack-drones-pass-live-fire-tests-with-first-deliveries-planned-this-year/","d":"2026-11-20","x":"Két német egyirányú támadó drónváltozat sikeresen teljesítette az élő tűzpróbákat, ami elősegíti az első szállítmányok és a katonai kiképzés megkezdését az év végéig. A Bundeswehr a teszteket a meppeni fegyver- és lőszertesztelő központban végezte, ahol a drónok célzott találatok elérésére és a robbanófejek működésére összpontosítottak. A német hadsereg tervezi, hogy 2027-ben felszereli páncélozott brigádját Litvániában a rendszerekkel. A német törvényhozók korábban szkeptikusak voltak a fegyveres drónok jóváhagyásával kapcsolatban, de a közelmúltbeli események, köztük Oroszország ukrajnai inváziója, a katonai hozzáállás átgondolásához vezettek. Az első szállítmányok várhatóan még idén megérkeznek.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Germany"],"p":8,"cm":2,"cid":13340},{"id":13377,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"Army 3-Star to Lead NORAD; Air Force Picks New Head at Nuclear Weapons Center","th":"Hármas tábornok vezeti a NORAD-ot; Új vezetőt választottak a Nukleáris Fegyverek Központjába","u":"https://www.airandspaceforces.com/army-3-star-norad-air-force-nuclear-weapons-center-boss/","d":"2026-11-21","x":"Patrick D. Frank tábornokot jelölték az Egyesült Államok Északi Parancsnokságának és az Észak-Amerikai Légi Védelem Parancsnokságának vezetésére, ami szokatlan lépés, mivel a pozíciót hagyományosan légierő tisztek töltötték be. Frank a közelmúltban tapasztalatokat szerzett a közel-keleti katonai bázisok védelmében, ahol drónok és rakéták ellen kellett védekeznie. A légierő új vezetője, Mark B. Pye, a nukleáris fegyverek központjának irányítását is átveszi, így a nukleáris erőfeszítések szinkronizálására is lehetősége nyílik. A NORAD és NORTHCOM vezetése a modern fenyegetések, például drónok és hiperszonikus rakéták elleni védekezés szempontjából is kulcsfontosságú lehet.","dom":"MDO","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás","Nukleáris elrettentés"],"oc":["United States"],"p":8,"cm":1,"cid":13377,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Személyi változás, nem új képesség."},{"id":13378,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"B-2 Wings Receive US Military’s Highest Unit-Level Award for Midnight Hammer","th":"B-2 Szárnyak Megkapják az Egyesült Államok Katonai Legmagasabb Egységi Díját a Midnight Hammerért","u":"https://www.airandspaceforces.com/b-2-presidential-unit-citation-operation-midnight-hammer/","d":"2026-11-21","x":"A B-2 bombaszárnyak, amelyek megtervezték és végrehajtották a Midnight Hammer műveletet, megkapták az Egyesült Államok katonai legmagasabb egységi díját, a Presidential Unit Citation-t. A 509. Bombaszárny és a 131. Nemzeti Gárda Bombaszárny a 'fegyveres ellenséggel szembeni rendkívüli hősiességért' részesült az elismerésben. A Midnight Hammer volt a legnagyobb B-2-es csapásmérés a történelemben, amely során 14 pilóta hajtott végre titkos küldetést Irán nukleáris létesítményei ellen. Az elismerés a művelet során végzett összes tevékenységet elismeri, beleértve a karbantartást, a logisztikát és a kommunikációt is. Az elismerés a csapatmunka és a felkészülés fontosságát hangsúlyozza, amely lehetővé tette a sikeres végrehajtást.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Iran"],"p":9,"cm":2,"cid":13378,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Díjazás, nem új képesség vagy rendszer."},{"id":13379,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"GAO: Oversight, Better Tracking Needed to Fix Munitions Shortage","th":"GAO: Felügyelet és jobb nyomon követés szükséges a lőszerek hiányának orvoslásához","u":"https://www.airandspaceforces.com/gao-oversight-better-tracking-needed-to-fix-munitions-shortage/","d":"2026-11-20","x":"A GAO jelentése szerint az Egyesült Államok hadserege lőszerek hiányával küzd, amelyet a háborúk támogatása és a külföldi partnerekkel kötött megállapodások okoznak. A jelentés hangsúlyozza, hogy szükség van egy átfogó tervre, amely összekapcsolja a célokat, stratégiákat és a lőszerek nyomon követését. A Pentagon elismerte, hogy szükséges egy központi hivatal létrehozása a lőszerek kezelésére, amely felelősséggel bír a lőszerek termelésének és beszerzésének irányításáért. A jelentés arra figyelmeztet, hogy a lőszerek nyomon követésének javítása érdekében rendszeres adatellenőrzésekre van szükség, mivel a jelenlegi adatok pontossága nem megfelelő. A Pentagon vezetői javasolták a lőszerek nyomon követésének standardizálását is.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Lőszer és védelmi ipari kapacitás","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":8,"cm":1,"cid":13379,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Általános probléma, nem új fejlemény.","hu":["közvetett","A hír az Egyesült Államok hadseregének lőszerhiányáról szól, amely közvetett módon releváns lehet Magyarország számára, mivel a magyar védelmi ipar is érintett a lőszergyártásban. A Rheinmetall Hungary Munitions Zrt. Várpalotán lőszert szállít a Magyar Honvédségnek, és a szállítások 2023-ban kezdődtek meg [HU-04]. A magyar védelmi ipar fejlesztése és a lőszergyártás kapacitásának növelése hozzájárulhat a hazai és nemzetközi lőszerigények kielégítéséhez.","ok"]},{"id":13415,"s":"Military Times","sz":"T2","t":"Trump, Xi agreed that military AI decisions should involve humans, Bessent says","th":"Trump és Xi megállapodtak, hogy a katonai mesterséges intelligencia döntésekben embereknek kell részt venniük","u":"https://www.militarytimes.com/news/pentagon-congress/2026/11/20/trump-xi-agreed-that-military-ai-decisions-should-involve-humans-bessent-says/","d":"2026-11-20","x":"Donald Trump amerikai elnök és Xi Jinping kínai elnök megállapodtak abban, hogy a katonai mesterséges intelligencia által hozott döntésekben mindig embereknek kell részt venniük. A megállapodás a Trump ázsiai látogatásának egyik fontos eredménye volt. A két ország versenye a mesterséges intelligencia terén nem befolyásolja ezt a megállapodást, amely emberi részvételt és egyéb védelmi intézkedéseket követel meg. A megállapodás célja, hogy megakadályozza a nagyobb katonai műveletek autonóm végrehajtását. A kereskedelmi minisztérium lépéseket tett Kína hozzáférésének további korlátozására a fejlett AI chipekhez.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","China"],"p":7,"cm":2,"cid":13385,"sp2":26,"ind":"Jelentőség 1/5, újdonság 1/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Politikai nyilatkozat, ismert AI etikai kérdés."},{"id":13418,"s":"Military Times","sz":"T2","t":"Marines roll out new water survival qualifications","th":"Új vízi túlélési képesítések bevezetése a tengerészgyalogságnál","u":"https://www.militarytimes.com/news/your-military/2026/11/20/marines-roll-out-new-water-survival-qualifications/","d":"2026-11-20","x":"A tengerészgyalogság új, fokozatos képesítési szinteket és standardokat vezetett be a Víz Túlélési Program keretében. Az új képesítési szintek közé tartozik a Víz Túlélési Alap (WSB), a Víz Túlélési Novice (WSN), a Víz Túlélési Competent (WSC), a Víz Túlélési Proficient (WSP) és a Víz Túlélési Advanced (WSA). A program célja a folyamatos képzés és a képesítési lehetőségek biztosítása a tengerészgyalogság tagjai számára. Az új standardok hangsúlyozzák a vízi túlélési készségek fejlesztését és a folyamatos képzést a tengerészgyalogság karrierje során.","dom":"MAR","br":"Tengerészgyalogság és kétéltű erők","sp":["Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":6,"cm":1,"cid":13418,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új képzési standardok, nem új haditechnikai fejlemény."},{"id":13281,"s":"Breaking Defense","sz":"T2","t":"Navy’s shipbuilding plan would require massive hike in annual appropriations: CBO","th":"A haditengerészet hajóépítési terve hatalmas éves költségnövekedést igényel: CBO","u":"https://breakingdefense.com/2026/11/navys-shipbuilding-plan-would-require-massive-hike-in-annual-appropriations-cbo/","d":"2026-11-20","x":"A haditengerészet 2027-es hajóépítési terve jelentős, 41%-os költségnövekedést igényel az elmúlt évek átlagos hajóépítési költségeihez képest, ami évente körülbelül 53,8 milliárd dollárt jelent. A Congressional Budget Office (CBO) jelentése szerint a hajóépítési költségek között szerepelnek a nukleáris meghajtású hajók újratöltésének költségei és egyéb nem harci hajók beszerzése. A CBO becslése szerint a hajóépítési terv 30 év alatt 1,47 trillió dollárra rúghat, ami a haditengerészet 1,23 trillió dolláros becslésénél is magasabb. A haditengerészet 2027-es költségvetési kérésében 65,8 milliárd dollárt kér hajóépítésre, hogy támogassa a flotta bővítését 450 hajóra 2031-ig.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":8,"cm":2,"cid":13281,"sp2":55,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 3/5 (3 forrás), forrásszint 3/5. Költségnövekedés, de nem új program."},{"id":13413,"s":"Military Times","sz":"T2","t":"Navy’s 2027 shipbuilding plan would cost $54B a year, federal agency says","th":"A Haditengerészet 2027-es hajóépítési terve évi 54 milliárd dollárba kerülne, állami ügynökség szerint","u":"https://www.militarytimes.com/news/your-military/2026/11/20/navys-2027-shipbuilding-plan-would-cost-54b-a-year-federal-agency-says/","d":"2026-11-20","x":"A Kongresszusi Költségvetési Hivatal (CBO) jelentése szerint az Egyesült Államok Haditengerészetének 2027-es hajóépítési terve évi 54 milliárd dollárba kerülne. A terv keretében a flotta hajóinak számát 286-ról 398-ra növelnék 2056-ra, új harci hajók és logisztikai támogatási hajók beszerzésével. A CBO becslése szerint a hajók építési költségei 21%-kal magasabbak a 2025-ös hajóépítési tervhez képest. A jelentés arra figyelmeztet, hogy a Haditengerészet nem biztos, hogy képes finanszírozni ezt az ambiciózus hajóépítési tervet, hacsak nem kap jelentős éves támogatást. A 2027-es hajóépítési terv a legnagyobb Haditengerészeti flottát hozhatja létre 2001 óta.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":8,"cm":2,"cid":13281},{"id":13297,"s":"The War Zone","sz":"T2","t":"Navy CCA Plans Will Not Wait For F/A-XX Next Generation Fighter","th":"A Haditengerészet CCA tervei nem várnak az F/A-XX következő generációs vadászra","u":"https://www.twz.com/air/navy-cca-plans-will-not-wait-for-f-a-xx-next-generation-fighter","d":"2026-11-20","x":"A cikkben a Haditengerészet következő generációs F/A-XX hordozóról indított vadászrepülőgépe és a Collaborative Combat Aircraft (CCA) drónok integrációja kerül szóba. William Toti, a Haditengerészet aláíró titkára elmondta, hogy a Haditengerészet nem várhat az F/A-XX-re a CCA drónok bevezetésével. A Haditengerészet már elkezdte a CCA drónok fejlesztését, és az F-35C Joint Strike Fighterrel való párosítást tervezik. A cikk említi, hogy a Haditengerészet a jövőbeli CCA flottáját többféle tervezéssel kívánja bővíteni, és a CCA drónok integrációja kulcsfontosságú a jövőbeli légifölény fenntartásához.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":13297,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új fejlesztési terv, de nem rendszerbe állítás."},{"id":13385,"s":"Defense News","sz":"T2","t":"Trump, Xi agreed that military AI decisions should involve humans, Bessent says","th":"Trump és Xi megállapodtak, hogy a katonai AI döntésekben embereknek kell részt venniük","u":"https://www.defensenews.com/global/asia-pacific/2026/11/20/trump-xi-agreed-that-military-ai-decisions-should-involve-humans-bessent-says/","d":"2026-11-20","x":"Donald Trump és Xi Jinping megállapodtak abban, hogy az embereknek mindig részt kell venniük a katonai döntésekben, amelyek mesterséges intelligencia technológiákat használnak. A megállapodás a Trump ázsiai látogatásának egyik fő eredménye volt. A megállapodás értelmében a katonai műveletek nem indulhatnak el emberi beavatkozás nélkül. A két ország közötti verseny az AI fölényért nem befolyásolja ezt a megállapodást. A kereskedelmi minisztérium lépéseket tett a Kína számára hozzáférhető fejlett AI chipek korlátozására is.","dom":"CYB","br":"Híradó és informatikai csapatok (CIS)","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","China"],"p":7,"cm":2,"cid":13385},{"id":13350,"s":"DefenseScoop","sz":"T2","t":"Army plans to work with OpenAI on Project Gatekeeper","th":"A Hadsereg együttműködik az OpenAI-jal a Gatekeeper projekten","u":"https://defensescoop.com/2026/11/20/army-project-gatekeeper-openai-gabe-chiulli/","d":"2026-11-20","x":"A Hadsereg tervezi, hogy együttműködik az OpenAI-jal a Gatekeeper projekt keretében, amely célja a kereskedelmi szolgáltatók szoftvereinek katonai használatra való akkreditálási folyamatának felgyorsítása. A projekt automatizálni kívánja az ATO (Authority to Operate) folyamatot, amely általában hónapokig tart. A kereskedelmi szolgáltatók kódot nyújthatnak be az Army DevSecOps platformra gyors érvényesítés céljából. Az első fázisban az OpenAI eszközeit használják a szoftverek ellenőrzésére, mielőtt más nyílt forráskódú és kereskedelmi modellek is bekerülnének a rendszerbe.","dom":"MDO","br":"Híradó és informatikai csapatok (CIS)","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":7,"cm":1,"cid":13350,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új projekt az OpenAI-jal, új fejlesztési célok."},{"id":13351,"s":"DefenseScoop","sz":"T2","t":"GAO calls for broad munitions plan, better data management from Pentagon","th":"A GAO széleskörű lőszerrendszert és jobb adatkezelést sürget a Pentagontól","u":"https://defensescoop.com/2026/11/20/gao-pentagon-munitions-plan-data-management/","d":"2026-11-20","x":"A GAO jelentése szerint a Pentagon hosszú távú lőszerrendszerrel kapcsolatos előrejelzései és az adatok nyomon követésének hiányosságai gátolják a kulcsfontosságú lőszerszükségletek helyreállítását. A jelentés javasolja, hogy a védelmi miniszter dolgozzon ki egy tervet a lőszerek készleteinek feltöltésére és az adatok pontos kezelésére. A Pentagon részben egyetértett a GAO ajánlásaival, de vitatta, hogy a digitális és mesterséges intelligencia irodának kellene felügyelnie az adatkezelési tervet. A jelentés hangsúlyozza, hogy a központosított terv nélkül a Pentagon reakciós helyzetben van, ami kockázatot jelent a globális eseményekre való reagálás során.","dom":"MDO","br":"Tüzér és tűztámogatás","sp":["Lőszer és védelmi ipari kapacitás","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":8,"cm":1,"cid":13351,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Általános probléma, nem új fejlemény.","hu":["közvetett","A GAO jelentése, amely a Pentagon lőszerrendszerének és adatkezelésének javítását sürgeti, közvetett módon releváns lehet Magyarország számára, mivel a magyar védelmi ipar is érintett a lőszergyártásban. A Rheinmetall Hungary Munitions Zrt. Várpalotán lőszert szállít a Magyar Honvédség számára, és a szállítások 2023-ban kezdődtek meg [HU-04]. A magyar védelmi ipar fejlesztése és a lőszergyártás kapacitásának növelése összhangban állhat a globális lőszerigények növekedésével és a hatékony adatkezelés fontosságával.","ok"]},{"id":13352,"s":"DefenseScoop","sz":"T2","t":"Trump taps Pentagon CIO Davies to be national cyber director","th":"Trump a Pentagon CIO-ját, Kirsten Davies-t nevezi ki nemzeti kibervédelmi igazgatónak","u":"https://cyberscoop.com/sean-cairncross-out-national-cyber-director/","d":"2026-11-20","x":"Sean Cairncross távozik a nemzeti kibervédelmi igazgatói posztról, mivel nem rendelkezett megfelelő technikai háttérrel. Kirsten Davies, a Pentagon informatikai igazgatója ideiglenes szerepet vállal a Fehér Házban. Az új igazgató hangsúlyozta, hogy az Egyesült Államoknak modernizálnia kell a kibervédelmi alapjait, hogy dominálhasson a kibertérben. A kormány célja, hogy az AI-t a kritikus infrastruktúra védelmére használja, miközben a törvényhozók erősebb kormányzati szabályozást követelnek. A vezetőváltás a kormányzati kibervédelmi pozíciók betöltésének nehézségei közepette történik.","dom":"CYB","br":"Védelmi kiberműveletek","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":7,"cm":2,"cid":13286},{"id":13386,"s":"Defense News","sz":"T2","t":"German attack drones pass live-fire tests, with first deliveries planned this year","th":"Német támadó drónok élő tűzpróbán, az első szállítmányok idén várhatóak","u":"https://www.defensenews.com/global/europe/2026/11/20/german-attack-drones-pass-live-fire-tests-with-first-deliveries-planned-this-year/","d":"2026-11-20","x":"Két német egyirányú támadó drónváltozat sikeresen teljesítette az élő tűzpróbákat, ami elősegíti a kezdeti szállítmányokat és a katonai kiképzést az év végéig. A Bundeswehr tervei szerint a rendszerek 2027-től az észtországi páncélozott brigádot fogják felszerelni. A tesztek során a drónok célzott találatok elérésére és a robbanófejek működésére összpontosítottak. A német törvényhozók korábban szkeptikusak voltak a fegyveres drónok jóváhagyásával kapcsolatban, de a közelmúltban a katonai kiadások átgondolása részeként változások történtek. Az első szállítmányok várhatóan még idén megérkeznek, hogy a katonák elkezdhessék a kiképzést.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Germany"],"p":8,"cm":2,"cid":13340,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Új drónok tesztelése, de nem rendszerbe állítás."},{"id":13400,"s":"Army Technology","sz":"T2","t":"UK opens fully automated artillery melt-cast factory","th":"Az Egyesült Királyság megnyitotta az első teljesen automatizált tüzérségi lőszergyártó üzemét","u":"https://www.army-technology.com/news/uk-opens-fully-automated-artillery-melt-cast-factory/","d":"2026-11-20","x":"A BAE Systems megnyitotta az Egyesült Királyság első teljesen automatizált nagy kaliberű lőszergyártó üzemét Glascoedben, Dél-Walesben. A 180 millió fontos beruházás lehetővé teszi a 155 mm-es lövedékek gyártási kapacitásának tizenhatszoros növelését. Ez a fejlesztés támogatja az Egyesült Királyság lőszerszállítását, annak ellenére, hogy az ország jelenlegi 155 mm-es tüzérségi flottája korlátozott. Az új robbanóanyag-töltő létesítmény a gyártási kapacitás bővítését célozza meg, amely hozzájárul a hadsereg modernizációjához és a védelmi ipar fejlődéséhez.","dom":"LAND","br":"Lőszer és védelmi ipari kapacitás","sp":["Lőszer és védelmi ipari kapacitás","Haderő-modernizáció és erőszerkezet"],"oc":["UK"],"p":8,"cm":1,"cid":13400,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új gyártóüzem, jelentős fejlesztés."},{"id":13104,"s":"ASPI The Strategist","sz":"T1","t":"America cannot destroy Iran’s missiles. China’s will be a far greater challenge","th":"Amerika nem tudja megsemmisíteni Irán rakétáit. Kína kihívása sokkal nagyobb lesz.","u":"https://www.aspistrategist.org.au/america-cannot-destroy-irans-missiles-chinas-will-be-a-far-greater-challenge/","d":"2026-11-23","x":"Az Egyesült Államok hírszerzési értékelése szerint Irán 1500-2500 ballisztikus rakétát tart fenn, annak ellenére, hogy az Egyesült Államok és Izrael intenzív katonai műveleteket folytatott a rakéták megsemmisítésére. A helyzet különösen aggasztó a csendes-óceáni térségben, ahol Kína jelentős és fejlett rakétaképességekkel rendelkezik. A konfliktusok során kiderült, hogy a modern rakétavédelmi rendszerek, mint a Patriot és Thaad, hatékonyak, de a költségek és a készletek gyors kimerülése komoly problémát jelent. Az Egyesült Államoknak sürgősen növelnie kell a rakétavédelmi rendszerek gyártását és integrálnia kell a szövetségesek védelmi iparát, hogy felkészüljön a jövőbeli kihívásokra. A Kínával való potenciális konfliktus során a rakéták és drónok koordinált támadásai jelentős kihívást jelentenek a védelem számára.","dom":"MDO","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Rakéták és hiperszonikus fegyverek","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Iran","China","Ukraine"],"p":9,"cm":1,"cid":13104,"sp2":53,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Ismert helyzetértékelés, nem új információ."},{"id":13286,"s":"Breaking Defense","sz":"T2","t":"Pentagon CIO Davies tapped as acting National Cyber Director","th":"Pentagon CIO Davies kinevezve ideiglenes Nemzeti Kibervédelmi Igazgatónak","u":"https://breakingdefense.com/2026/11/pentagon-cio-davies-tapped-as-acting-national-cyber-director/","d":"2026-11-20","x":"Kirsten Davies, a Pentagon Chief Information Officer (CIO) szerepét betöltő szakember, átvette a Nemzeti Kibervédelmi Igazgató pozícióját, miután Sean Cairncross távozott. Davies hangsúlyozta a kibervédelmi képességek modernizálásának és a jövő kibertalentumának kiépítésének fontosságát. Az új igazgató négy kulcsfontosságú pillérre összpontosít, beleértve a digitális képességek fejlesztését és a kiberbiztonság átalakítását. Az ő vezetése alatt a Pentagon több nagy szerződést is aláírt, amelyek célja a technológiai rendszerek integrálása és a kibervédelmi programok fejlesztése. A hossz_megjegyzes: Az absztrakt a megadott szöveg alapján készült.","dom":"CYB","br":"Védelmi kiberműveletek","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":7,"cm":2,"cid":13286,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Személyi kinevezés, nem új haditechnikai fejlemény."},{"id":13295,"s":"The War Zone","sz":"T2","t":"There Is More To Air Force One’s Long Flight From China Than Just Breaking Records","th":"Több mint rekorddöntés: Az Air Force One hosszú repülése Kínából","u":"https://www.twz.com/air/there-is-more-to-air-force-ones-long-flight-from-china-than-just-breaking-records","d":"2026-11-20","x":"Donald Trump elnök a legújabb Air Force One, a VC-25B Bridge repülőgéppel tért haza Kínából, amely rekordidő alatt, 14,5 óra alatt tette meg az utat. A repülőgép képes volt elkerülni a tankolást, ami jelentős előrelépés az előző modellekhez képest. A repülés során a gép a legnagyobb felszállási súlyt is elérte, ami új rekordot jelentett. Az új VC-25B modellek azonban nem rendelkeznek tankolási lehetőséggel, ami nemzetbiztonsági aggályokat vet fel. A repülőgép hatótávolsága is csökkent, ami további kérdéseket vet fel a jövőbeli elnöki szállítások kapcsán.","dom":"AIR","br":"Légi szállítás és utántöltés","sp":["Haderő-modernizáció és erőszerkezet","Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)"],"oc":["United States","China","Russia"],"p":7,"cm":1,"cid":13295,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Repülési rekord, nem új haditechnikai fejlemény."},{"id":13296,"s":"The War Zone","sz":"T2","t":"Oddball CFL-120 Karpat Medium Tank With A Big Gun Faces A Battlefield Increasingly Hostile To Armor","th":"Oddball CFL-120 Karpat közepes harckocsi nagyágyúval a páncélosok számára egyre ellenségesebb csatatéren","u":"https://www.twz.com/land/oddball-cfl-120-karpat-medium-tank-with-a-big-120mm-gun-faces-a-battlefield-increasingly-hostile-to-armor","d":"2026-11-20","x":"A CFL-120 Karpat egy új szlovák-török közepes harckocsi, amely a nehezebb fő harckocsik (MBT) beszerzésére képtelen vagy könnyebb, mozgékonyabb járművet kereső hadseregek számára készült. A harckocsi 120 mm-es ágyúval van felszerelve, és a legújabb teszteléseken bemutatta mozgékonyságát és tűzerejét. A Karpat súlya körülbelül 35 tonna, ami jelentősen kevesebb, mint a modern MBT-ké, de a páncélos járművek túlélhetősége egyre inkább megkérdőjeleződik a drónok és fejlett páncéltörő fegyverek elterjedése miatt. A Karpat jövője attól függ, hogy képes lesz-e meggyőző operatív igényt felmutatni a hagyományos MBT-k és a könnyebb gyalogsági harcjárművek közötti rés betöltésére.","dom":"LAND","br":"Harckocsizó (páncélos) csapatok","sp":["Haderő-modernizáció és erőszerkezet","Lőszer és védelmi ipari kapacitás"],"oc":["Slovakia","Turkey","Italy"],"p":7,"cm":1,"cid":13296,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új közepes harckocsi bemutatása, új tesztelési eredmények."},{"id":13414,"s":"Military Times","sz":"T2","t":"Army delays detonation of unstable ammunition stockpile until Monday","th":"A hadsereg elhalasztja a stabilizálatlan lőszerraktár felrobbantását hétfőre","u":"https://www.militarytimes.com/news/your-military/2026/11/20/army-delays-detonation-of-unstable-ammunition-stockpile-until-monday/","d":"2026-11-20","x":"A hadsereg elhalasztotta a stabilizálatlan lőszerraktár felrobbantását, amelyet egy iowai lőszergyárban tároltak, a közbiztonság és a kommunikáció miatt. Az eredetileg péntekre tervezett robbantást hétfőre halasztották, mivel a hideg időjárás miatt a lőszerek instabilitása fokozódhat. A hadsereg több mint 4000 kg degradált ólom-azidot kíván megsemmisíteni, amelyet gyakran használnak a robbanófejekben. A robbantás körüli aggodalmak miatt a helyi közösségek és politikai képviselők is tiltakoztak, és alternatív megoldások keresését sürgették. A hadsereg modernizálja a gyárat, hogy növelje a lövedékgyártást 2027 végére.","dom":"LAND","br":"Tüzér és tűztámogatás","sp":["Lőszer és védelmi ipari kapacitás","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":7,"cm":1,"cid":13414,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Általános biztonsági intézkedés, nem új haditechnikai fejlemény."},{"id":12599,"s":"Defense One","sz":"T2","t":"The Army wants its units to use more data, but many aren’t built to do so","th":"A hadsereg több adat használatát szeretné, de sok egység nem erre van felkészülve","u":"https://www.defenseone.com/technology/2026/11/army-wants-its-units-use-more-data-many-arent-built-do-so/417355/","d":"2026-11-19","x":"A hadsereg vezetői a jövőbeli adatvezérelt működéshez szükséges információk gyors és hatékony áramlásának hiányosságait tapasztalják. A Project Flytrap gyakorlat során kiderült, hogy a harci egységek és a parancsnokság közötti információmegosztás nem tart lépést a modern hadviselés követelményeivel. A mesterséges intelligencia potenciálisan segíthet az információk gyorsabb átvitelében, lehetővé téve a parancsnokok számára, hogy releváns döntéseket hozzanak a harctéren. A hadsereg jelenleg az adatkezelési problémák megoldásán dolgozik, hogy a taktikai egységek hatékonyabban reagálhassanak a kihívásokra. A jövőbeni megoldások ígéretesek, és a hadsereg adatkezelési központja folyamatosan keresi a megoldásokat.","dom":"COG","br":"Híradó és informatikai csapatok (CIS)","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":7,"cm":1,"cid":12599},{"id":12621,"s":"C4ISRNET","sz":"T2","t":"New tools for troops to gun down drones | Defense News Weekly Full Episode 11.17.26","th":"Új eszközök a csapatok számára drónok lelövésére","u":"https://www.c4isrnet.com/videos/2026/11/19/new-tools-for-troops-to-gun-down-drones-defense-news-weekly-full-episode-11-17-26/","d":"2026-11-19","x":"A megfizethető drónok, amelyek precíziós, irányított személyi elleni lőszereket szállítanak, folyamatosan új védelmi rendszerek kifejlesztését ösztönzik. Az új eszközök célja, hogy segítsenek a csapatoknak a drónok hatékony semlegesítésében. A cikk említi, hogy a drónok jelentette fenyegetés komoly kihívásokat támaszt a modern hadviselésben.","dom":"AIR","br":"Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)","sp":["Drónok és drónelhárítás"],"oc":[],"p":7,"cm":3,"cid":12621},{"id":11989,"s":"CBO","sz":"T1","t":"An Analysis of the Navy's Fiscal Year 2027 Shipbuilding Plan","th":"A Haditengerészet 2027-es Évközi Hajóépítési Terve","u":"https://www.cbo.gov/publication/62884","d":"2026-11-19","x":"A Haditengerészet 2027-es hajóépítési terve a 2027-től 2056-ig terjedő időszakot öleli fel. A Congressional Budget Office (CBO) becslése szerint a terv végrehajtásának átlagos éves költsége 53,8 milliárd dollár lenne (2026-es árakon), amelyből 48,9 milliárd dollár új hajók építésére fordítandó. Ez a költségvetési terv jelentős hatással lehet a haditengerészet modernizációjára és fejlesztésére. A hajóépítési program célja a flotta fenntartása és fejlesztése a jövőbeli kihívásokkal szemben.","dom":"MAR","br":"Hajóépítés és haditengerészet","sp":["Hajóépítés és haditengerészet"],"oc":["United States"],"p":7,"cm":3,"cid":11989},{"id":12668,"s":"Defense News","sz":"T2","t":"New tools for troops to gun down drones | Defense News Weekly Full Episode 11.17.26","th":"Új eszközök a csapatok számára a drónok lelövésére","u":"https://www.defensenews.com/video/2026/11/19/new-tools-for-troops-to-gun-down-drones-defense-news-weekly-full-episode-11-17-26/","d":"2026-11-19","x":"A kedvező árú drónok, amelyek precíziós, irányított személyi elleni lőszereket szállítanak, folyamatosan új védelmi rendszerek kifejlesztését ösztönzik. Az új eszközök célja, hogy a csapatok hatékonyan tudják megsemmisíteni ezeket a fenyegetéseket. A cikk említi, hogy a drónok elleni védekezés egyre fontosabbá válik a modern hadviselésben. A védelmi ipar folyamatosan reagál a technológiai kihívásokra, hogy biztosítsa a katonák védelmét.","dom":"AIR","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Drónok és drónelhárítás"],"oc":[],"p":7,"cm":3,"cid":12621},{"id":12695,"s":"Military Times","sz":"T2","t":"New tools for troops to gun down drones | Defense News Weekly Full Episode 11.17.26","th":"Új eszközök a csapatok számára a drónok lelövésére","u":"https://www.militarytimes.com/video/2026/11/19/new-tools-for-troops-to-gun-down-drones-defense-news-weekly-full-episode-11-17-26/","d":"2026-11-19","x":"A megfizethető drónok, amelyek precíziós, irányított személyi elleni lőszereket szállítanak, folyamatosan új védelmi rendszerek kifejlesztését ösztönzik. A cikk bemutatja az új védelmi megoldásokat, amelyek célja a drónok hatékony semlegesítése. Emellett egy Medal of Honor kitüntetett interjúja is szerepel a műsorban.","dom":"AIR","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Drónok és drónelhárítás"],"oc":[],"p":7,"cm":3,"cid":12621},{"id":12159,"s":"Atlantic Council","sz":"T1","t":"Kyiv’s partners should prioritize Ukraine’s domestic drone production","th":"Kijev partnereinek prioritásként kell kezelniük Ukrajna hazai dróntermelését","u":"https://www.atlanticcouncil.org/blogs/ukrainealert/kyivs-partners-should-prioritize-ukraines-domestic-drone-production/","d":"2026-11-19","x":"A cikk szerint Kijev partnereinek támogatniuk kell Ukrajna hazai dróntermelését, mivel az ukrán hosszú távú dróncsapások jelentős hatással voltak Oroszország olajfinomító kapacitására. Ukrajna védelmi ipara gyors ütemben fejlődött, és jelentős kapacitással rendelkezik, azonban a pénzügyi források hiánya korlátozza a termelést. A donor országok közvetlenül támogathatják az ukrán gyártókat, ami gazdaságilag és katonailag is előnyös. A cikk hangsúlyozza, hogy a megfelelő nemzetközi támogatással Ukrajna képes lenne még több drón előállítására, ami költséghatékony módja lenne az orosz fenyegetés elleni védekezésnek.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Ukraine","Russia"],"p":8,"cm":1,"cid":12159,"sp2":53,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Általános vélemény Ukrajna dróntermeléséről."},{"id":12548,"s":"Breaking Defense","sz":"T2","t":"Toti pushes new foreign-built shipyard in the US to focus on frigates, large surface combatants","th":"Toti új, külföldi építésű hajógyárat sürget az Egyesült Államokban, hogy a fregattokra és nagy felszíni harci hajókra összpontosítson","u":"https://breakingdefense.com/2026/11/toti-pushes-new-foreign-built-shipyard-in-the-us-to-focus-on-frigates-large-surface-combatants/","d":"2026-11-19","x":"William Toti, aki a haditengerészet államtitkárának jelöltje, egy új, külföldi építésű hajógyár létrehozását javasolja az Egyesült Államokban, amely a fregattok és más hajók építésére összpontosítana. Toti szerint a leggyorsabb módja a fregattok beszerzésének az, ha egy külföldi hajógyár befektet az Egyesült Államokban. Az amerikai haditengerészet költségvetése 1,85 milliárd dollárt kér a külföldi hajógyárak által épített hadihajók tanulmányozására. A javasolt hajógyár célja a haditengerészeti ipar kapacitásának növelése és a munkaerő megerősítése. A Kongresszusban folyamatban lévő viták a külföldi hajógyárak szerepéről továbbra is aktívak.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Beszerzés és védelmi költségvetés"],"oc":["United States","Japan","South Korea"],"p":7,"cm":1,"cid":12548},{"id":12550,"s":"Breaking Defense","sz":"T2","t":"Army extends Data Operations Center pilot to Oct. 2027","th":"A Hadsereg meghosszabbítja az Adatműveleti Központ pilot programját 2027 októberéig","u":"https://breakingdefense.com/2026/11/army-extends-data-operations-center-pilot-to-oct-2027/","d":"2026-11-19","x":"A Hadsereg egy évvel meghosszabbítja az Adatműveleti Központ (ADOC) pilot programját, hogy meghatározza, milyen lenne egy állandó szervezet. Az ADOC célja, hogy információt és adatokat mozgasson világszerte, különösen a taktikai szinten. A központ segít a hadseregi egységeknek az információkhoz való hozzáférésben, és folyamatosan tanulják és finomítják a folyamatokat. A Hadsereg vezetése a pilot program végén dönt a központ állandóvá tételéről. A központ működése során a problémák megoldási ideje jelentősen csökkent, ami a technológiai fejlődésnek is köszönhető.","dom":"COG","br":"Híradó és informatikai csapatok (CIS)","sp":["Vezetés-irányítás és ISR (C2/ISR)","MI és autonómia"],"oc":["United States"],"p":7,"cm":2,"cid":12550},{"id":12631,"s":"DefenseScoop","sz":"T2","t":"Army extends ADOC pilot by a year as officials work to make the data ops center a more permanent fixture","th":"A Hadsereg egy évvel meghosszabbítja az ADOC pilot programot, miközben a hivatalnokok azon dolgoznak, hogy a data ops központot tartósabbá tegyék","u":"https://defensescoop.com/2026/11/19/army-extends-data-operations-center-pilot/","d":"2026-11-19","x":"A Hadsereg Data Operations Center (ADOC) pilot programját 12 hónappal meghosszabbították, hogy a vezetők több időt kapjanak a szervezet hosszú távú formalizálására. Az ADOC célja a hadsereg adatkezelési kihívásainak kezelése, beleértve az adatokhoz való hozzáférés problémáit. Az ADOC egy jegykezelő rendszert hozott létre, amely lehetővé teszi a világ különböző pontjain lévő egységek számára, hogy segítséget kérjenek. Az automatizálás és a mesterséges intelligencia kulcsszerepet játszik a feladatok végrehajtásában. A program kiterjesztése lehetővé teszi a tapasztalatok gyűjtését és a folyamatok javítását a jövőbeli formalizálás érdekében.","dom":"COG","br":"Híradó és informatikai csapatok (CIS)","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":7,"cm":2,"cid":12550},{"id":12551,"s":"Breaking Defense","sz":"T2","t":"Raytheon taps Ursa Major, Avio USA as second source for Tomahawk solid rocket motors","th":"Raytheon második forrást keres a Tomahawk szilárd rakétamotorjaihoz","u":"https://breakingdefense.com/2026/11/raytheon-taps-ursa-major-avio-usa-as-second-source-for-tomahawk-solid-rocket-motors/","d":"2026-11-19","x":"A Raytheon az Ursa Major és az Avio USA cégeket választotta ki, hogy közösen gyártsák a Tomahawk cirkáló rakéta szilárd rakétamotorját, ezzel második beszállítót biztosítva a haditengerészet számára. A Tomahawk kulcsfontosságú képesség a harcosok számára, és a növekvő kereslet kielégítése érdekében erősebb és ellenállóbb ellátási láncra van szükség. A szilárd rakétamotorok iránti kereslet az ukrajnai háború és a közel-keleti konfliktusok miatt nőtt meg az utóbbi években. A haditengerészet augusztusban 22,9 milliárd dolláros szerződést kötött a Raytheonnal a Tomahawk éves 1000 darabra történő termelésének növelésére.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Lőszer és védelmi ipari kapacitás","Haderő-modernizáció és erőszerkezet"],"oc":["United States","Italy"],"p":8,"cm":1,"cid":12551,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új beszállítók a Tomahawk motorokhoz."},{"id":12552,"s":"Breaking Defense","sz":"T2","t":"The real-world missile defense lessons from Ukraine and Iran — and how they matter for China","th":"Valóságbeli rakétavédelmi tanulságok Ukrajnából és Iránból - és hogy ezek miért fontosak Kínának","u":"https://breakingdefense.com/2026/11/the-real-world-missile-defense-lessons-from-ukraine-and-iran-and-how-they-matter-for-china/","d":"2026-11-19","x":"A világ hadseregei az ukrán és iráni konfliktusokat tanulmányozzák, hogy megértsék a rakétatechnológiák, drónok és légvédelmi rendszerek hatásait. Mivel minden konfliktus más és minden régiónak eltérő igényei vannak, fontos megérteni, hogy mely tanulságok alkalmazhatóak különböző területeken. Becca Wasser és Mark Cancian szakértők a Breaking Defense keretein belül vitatták meg ezeket a kérdéseket. A légvédelem és rakétavédelem területén szerzett tapasztalatok különösen relevánsak lehetnek Kína számára.","dom":"AIR","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Rakéták és hiperszonikus fegyverek","Drónok és drónelhárítás","Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)"],"oc":["Ukraine","Iran","China"],"p":8,"cm":1,"cid":12552,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Általános elemzés rakétavédelemről."},{"id":12632,"s":"DefenseScoop","sz":"T2","t":"Trump nominates Centcom Deputy Lt. Gen. Patrick Frank to lead Northcom, NORAD","th":"Trump Patrick Frank tábornokot jelöli a Northcom és NORAD vezetésére","u":"https://defensescoop.com/2026/11/19/trump-nominates-centcom-deputy-lt-gen-patrick-frank-to-lead-northcom-norad/","d":"2026-11-19","x":"Donald Trump elnök Patrick Frank tábornokot jelölte az Egyesült Államok Északi Parancsnokságának (Northcom) és az Észak-Amerikai Légvédelmi Parancsnokságnak (NORAD) vezetésére. Frank, aki jelenleg a Közép-Ázsiai Parancsnokság helyettes parancsnoka, a megerősített légvédelmi rendszerek és a drónokkal szembeni védelem modernizálásáért felelős. A parancsnokságok célja a fenyegetések elleni védelem, különös figyelmet fordítva a hiperszonikus rakétákra és a drónok incursion-jaira. Frank kinevezése a parancsnokságok számára új lehetőségeket teremt a védelmi technológiák fejlesztésében és a határok mentén végzett műveletek támogatásában. A Northcom a belső drónellenes erőfeszítések vezető szinkronizálója is lett 2024 novemberében.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás","MI és autonómia"],"oc":["United States","Canada"],"p":8,"cm":1,"cid":12632},{"id":12699,"s":"Military Times","sz":"T2","t":"F-35C completes first launch and recovery trials on a Ford-class carrier","th":"F-35C első indítási és visszatérési próbái a Ford-osztályú repülőgép-hordozón","u":"https://www.militarytimes.com/news/your-military/2026/11/19/f-35c-completes-first-launch-and-recovery-trials-on-a-ford-class-carrier/","d":"2026-11-19","x":"Két Navy F-35C Lightning II vadászgép sikeresen teljesítette az első indítási és visszatérési teszteket az USS John F. Kennedy fedélzetén. A tesztelés során 34 repülést hajtottak végre, 122 katapult indítással és 122 landolással. Az F-35C a Ford-osztályú repülőgép-hordozókhoz való integrációját igazolja, amely új elektromágneses indítórendszert és fejlett visszatérési rendszert használ. A tesztelés célja a repülőgép és a hordozó közötti kompatibilitás ellenőrzése volt, és a Navy most már engedélyezte az F-35C használatát az összes repülőgép-hordozóján. A USS John F. Kennedy várhatóan 2027 tavaszán kerül hivatalosan átadásra.","dom":"MAR","br":"Haditengerészeti repülés és tengeri járőr","sp":["Hajóépítés és haditengerészet","Drónok és drónelhárítás"],"oc":["United States"],"p":8,"cm":2,"cid":12671},{"id":12681,"s":"Army Technology","sz":"T2","t":"Ukraine, Denmark agree on defence AI cooperation","th":"Ukrajna és Dánia megállapodott a védelmi mesterséges intelligencia együttműködésről","u":"https://www.army-technology.com/news/ukraine-denmark-ai-avengers-lab/","d":"2026-11-19","x":"Ukrajna és Dánia aláírt egy szándéknyilatkozatot a mesterséges intelligencia (MI) és az adatok védelmi alkalmazásokra vonatkozó együttműködésének bővítéséről. Az egyezményt a Ramstein-formátumú találkozó keretében írták alá. A két ország tervezi, hogy megosztja operatív tapasztalatait, és harctéri adatokat használ az MI eszközök fejlesztésére. Dánia hozzáférést kap az Avengers Labs platformhoz, amelyet az MI modellek védelmi célú képzésére és értékelésére használnak. Az együttműködés célja, hogy mindkét fél erősebbé váljon az MI alkalmazásával a harci műveletek során.","dom":"COG","br":"Híradó és informatikai csapatok (CIS)","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Ukraine","Denmark"],"p":8,"cm":1,"cid":12681},{"id":12589,"s":"Naval News","sz":"T2","t":"U.S. Senate Seeks to Exchange Shipbuilding Funds for More Munitions","th":"Az Egyesült Államok Szenátusa hajóépítési alapok átcsoportosítását tervezi több lőszer beszerzésére","u":"https://www.navalnews.com/naval-news/2026/11/u-s-senate-seeks-to-exchange-shipbuilding-funds-for-more-munitions/","d":"2026-11-19","x":"Az Egyesült Államok Szenátusa közzétette a 2027-es költségvetési javaslatát, amely a haditengerészet lőszerbeszerzési prioritásait tartalmazza. A javasolt költségvetés jelentős növekedést mutat a lőszerkészletek terén, különösen az előrehaladott csapásmérő lőszerek és rakéták esetében. A hajóépítési alapokból átcsoportosított források révén a lőszerbeszerzésre közel 19,7 milliárd dollárt szánnak, amely tartalmazza a Tomahawk rakéták és a Patriot PAC-3 rakéták jelentős finanszírozását is. A hajóépítési programok közül csak néhány kapott növelést, a hangsúly a meglévő rendszerek fejlesztésén van. A költségvetés átcsoportosítása azonban jelentős csökkentéseket is magával hozott a tengeralattjáró programokban.","dom":"MAR","br":"Felszíni harci hajók","sp":["Lőszer és védelmi ipari kapacitás","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":8,"cm":1,"cid":12589},{"id":12563,"s":"The War Zone","sz":"T2","t":"The Jet That Always Shadows Air Force One When The President Travels Abroad","th":"A gép, amely mindig kíséri az Air Force One-t, amikor az elnök külföldre utazik","u":"https://www.twz.com/news-features/why-the-e-4b-doomsday-plane-always-shadows-air-force-one-when-the-president-travels-abroad","d":"2026-11-20","x":"A cikk az E-4B Nightwatch repülőgépről szól, amely az Egyesült Államok elnökének külföldi útjain kíséri az Air Force One-t. Az E-4B, amely egy mobil parancsnoki központ, kulcsszerepet játszik a nukleáris elrettentésben és a kormányzati folytonosság biztosításában. Az E-4B repülőgépek folyamatosan frissülnek, és képesek napokig a levegőben maradni, így bármilyen válsághelyzetben irányítani tudják a katonai műveleteket. Az elnök külföldi útjain a repülőgép a biztonságos kommunikáció és irányítás érdekében elengedhetetlen. Az E-4B flottája a kormányzati vészhelyzeti tervek szerves része, amely biztosítja, hogy a kulcsfontosságú kormányzati elemek működőképesek maradjanak egy támadás után.","dom":"AIR","br":"Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)","sp":["Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":8,"cm":1,"cid":12563,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Ismert E-4B szerep, kevés újdonság."},{"id":12564,"s":"The War Zone","sz":"T2","t":"Regent Squire Wing-In-Ground Effect Drone To Patrol Middle East Waters","th":"Regent Squire Szárny-a-Földön Hatású Drón a Közel-Kelet Vizein","u":"https://www.twz.com/news-features/regent-squire-wing-in-ground-effect-drone-to-patrol-middle-east-waters","d":"2026-11-19","x":"A Regent bejelentette, hogy megállapodást kötött egy amerikai kormányzati ügyféllel, hogy elad egy bizonyos számú autonóm Squire Seaglider drónt. Ezek az elektromos meghajtású drónok a Közel-Keleten fognak működni, és többdomainű érzékelési feladatokat látnak el. A Squire drón különlegessége, hogy hidrofoiling szárny-a-földön hatású jármű, amely képes a víz felett repülni, kihasználva a szárnyak és a víz felszíne közötti levegőpárnát. A drónok feladatai közé tartozik a hírszerzés, megfigyelés és felderítés, valamint a tengeralatti érzékelési missziók. A Regent a Tengerészgyalogsággal is együttműködik egy nagyobb WIG jármű, a Viceroy Seaglider fejlesztésében.","dom":"MAR","br":"Tengeri pilóta nélküli rendszerek","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["United States","Iran"],"p":8,"cm":1,"cid":12564,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új drón megállapodás a Közel-Keleten."},{"id":12565,"s":"The War Zone","sz":"T2","t":"Ukraine Wants More Mirage 2000 Fighters. Where Could They Come From?","th":"Ukrajna további Mirage 2000 vadászgépeket kér","u":"https://www.twz.com/air/ukraine-wants-more-mirage-2000-fighters-where-could-they-come-from","d":"2026-11-19","x":"Ukrajna további francia gyártású Mirage 2000 vadászgépeket kér, amelyeket gyorsabban tudna üzembe helyezni, mint a Rafale típusúakat. Zelensky elnök a legutóbbi Ukrajna Védelmi Kapcsolattartó Csoport ülésén kérte a gépeket, hangsúlyozva, hogy bármilyen egyedi gépet elfogadnának, akár első vonalbeli használatra, akár alkatrészként. Franciaország eddig legalább négy Mirage 2000-5F-t küldött Ukrajnának, de a további gépek sorsa még kérdéses. Görögország is potenciális forrás lehet, mivel 24 Mirage 2000-5 Mk II vadászgépük van, de a politikai megállapodás és a helyettesítő gépek beszerzése még nem biztosított. A Mirage 2000 család különböző konfigurációi miatt a jövőbeli átadások bonyolultak lehetnek.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["Ukraine","France","Greece"],"p":7,"cm":1,"cid":12565},{"id":12566,"s":"The War Zone","sz":"T2","t":"Impacts Of Latest Neptune Missile Strike On Kerch Bridge Seen In Satellite Imagery","th":"A legújabb Neptune rakétatámadás hatásai a Kerch hídról készült műholdképeken","u":"https://www.twz.com/news-features/impacts-of-latest-neptune-missile-strike-on-kerch-bridge-seen-in-satellite-imagery","d":"2026-11-19","x":"A Vantor által készített műholdképek szerint a Kerch híd vasúti szakaszán jelentős károk keletkeztek a legújabb ukrán Neptune rakétatámadás következtében. A támadás következtében a vonatforgalom leállt, és a híd egyes részei súlyosan megsérültek. Az ukrán védelmi erők folyamatosan támadják a híd körüli logisztikai útvonalakat, ami komoly hatással van Oroszország ellátási láncaira. A híd megrongálása miatt Oroszország kénytelen hosszabb és veszélyesebb útvonalakat használni az utánpótlás szállítására. A támadások célja a orosz hadsereg logisztikai képességeinek csökkentése.","dom":"LAND","br":"Tüzér és tűztámogatás","sp":["Rakéták és hiperszonikus fegyverek","Haderő-modernizáció és erőszerkezet"],"oc":["Ukraine","Russia"],"p":8,"cm":1,"cid":12566,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Neptune rakétatámadás hatásai."},{"id":12588,"s":"Naval News","sz":"T2","t":"Argentine Navy interested in acquiring up to three FCX20 corvettes","th":"Argentin Haditengerészet érdeklődése három FCX20 korvett beszerzése iránt","u":"https://www.navalnews.com/naval-news/2026/11/argentine-navy-interested-in-acquiring-up-to-three-fcx20-corvettes/","d":"2026-11-19","x":"Az Argentin Haditengerészet érdeklődést mutatott három FCX20 korvett beszerzése iránt, amelyeket a Fincantieri fejlesztett ki. Az érdeklődést a két ország védelmi minisztere által aláírt szándéknyilatkozat formalizálta. Az FCX20 korvett modern tervezésű, fejlett technológiai rendszerekkel rendelkezik, és képes hatékonyan működni minden harci területen. A hajó a Fincantieri hajógyártási szakértelmét tükrözi, és lehetőséget biztosít a jövőbeni együttműködésre a haditengerészeti szektorban. Az argentin érdeklődés hosszú távú együttműködést ígér az ipar és a hadsereg között.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet"],"oc":["Argentina","Italy"],"p":7,"cm":1,"cid":12588},{"id":12590,"s":"Naval News","sz":"T2","t":"Baltic Workboats Launches EUROGUARD Modular Ship in Estonia","th":"A Baltic Workboats bemutatja az EUROGUARD moduláris hajót Észtországban","u":"https://www.navalnews.com/naval-news/2026/11/estonian-president-christens-first-euroguard-the-largest-warship-ever-built-in-the-country/","d":"2026-11-19","x":"2026. november 19-én az Észtországban, a Baltic Workboats hajógyárában bemutatták az EUROGUARD prototípust, amely a legnagyobb hadihajó, amit az országban építettek. Az 45 méteres hajó tíz európai ország és 27 ipari vállalat közös projektje, amelynek célja az európai tengeri védelem képességeinek megerősítése. Az EUROGUARD moduláris kialakítása lehetővé teszi a tengeri megfigyelés, aknászat, kritikus infrastruktúra védelme és drónok irányítása számára való alkalmazást. A projekt költségvetése körülbelül 95 millió euró, amelyből 65 millió eurót az Európai Védelmi Alap biztosít. A hajó a jövő hadihajóinak fejlesztését is segíti, lehetővé téve a különböző gyártók technológiáinak integrálását.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Drónok és drónelhárítás"],"oc":["Estonia","Germany","France","Spain"],"p":8,"cm":1,"cid":12590},{"id":12633,"s":"DefenseScoop","sz":"T2","t":"CR not slowing Golden Dome progress, deputy director argues","th":"A Golden Dome előrehaladása nem lassul, állítja a helyettes igazgató","u":"https://defensescoop.com/2026/11/19/cr-not-slowing-golden-dome-progress-deputy-director-argues/","d":"2026-11-19","x":"A Golden Dome for America program előrehaladása folytatódik, annak ellenére, hogy a folyamatban lévő költségvetési határozat megkötötte a forrásokat. A program helyettes igazgatója, Marcia Holmes elmondta, hogy a kongresszus jelentős összeget biztosított a program számára, és a Pentagon már elköltötte a rendelkezésre álló forrásokat. A cél az, hogy 2028 nyarára elérjék az első operatív képességet, és a program már több teszten is túljutott. A szenátusi költségvetési bizottság azonban aggodalmát fejezte ki a program finanszírozási megközelítése miatt, és további forrásokat javasolt a költségvetéshez. A Golden Dome költségeit 185 milliárd dollárra becsülik, és a program jövője a kongresszusi megállapodásoktól függ.","dom":"AIR","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":8,"cm":1,"cid":12633},{"id":12641,"s":"SpaceNews","sz":"T2","t":"The sweet spot for constellation size","th":"A konstelláció méretének optimális pontja","u":"https://spacenews.com/the-sweet-spot-for-constellation-size/","d":"2026-11-19","x":"A Space Minds podcast legújabb epizódjában Jan Smolders, a Space Inventor kereskedelmi igazgatója beszél a mini-konstellációk előnyeiről és arról, hogyan tudnak az európai kormányok gyorsabban befektetni az űrtechnológiákba. A beszélgetés során kiemelik, hogy a tipping és cueing technikák milyen értékesek lettek a Balti-tengeren. A Space Inventor dániai műholdakat gyárt, amelyek a megbízhatóság és az innováció tökéletes kombinációját kínálják. Az epizód célja, hogy inspiráló beszélgetéseket folytasson az űrtechnológiák jövőjéről.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Világűr- és műholdképességek"],"oc":["Denmark"],"p":7,"cm":1,"cid":12641},{"id":12661,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"ULA’s Latest Launch Failure Spells Trouble for Space Force","th":"ULA legújabb indítási kudarcai problémát okoznak a Űrerő számára","u":"https://www.airandspaceforces.com/ula-launch-failure-trouble-space-force/","d":"2026-11-19","x":"A United Launch Alliance (ULA) rakétája november 15-én kudarcot vallott, ami nemcsak egy rakéta és 40 Amazon LEO műhold megsemmisítését jelentette, hanem szorosabbá tette a Space Force indítási kapacitását is. A Vulcan Centaur rakéta indítása jól indult, de körülbelül 10 perccel a repülés után nem tudott elérni megfelelő magasságot és sebességet, így nem jutott pályára. A Space Force már eddig is áthelyezett több küldetést a SpaceX Falcon 9 vagy Falcon Heavy rakétákra, mivel az ULA nem tudta biztosítani a szükséges kapacitást. A Pentagon 150 millió dolláros kölcsönöket kínál új rakéták támogatására két kisebb indító szolgáltatónak, a Rocket Labnak és a Stoke Space-nek, amelyek 2027-ben tervezik első repüléseiket.","dom":"SPA","br":"Haditengerészeti repülés és tengeri járőr","sp":["Világűr- és műholdképességek","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":7,"cm":1,"cid":12661},{"id":12666,"s":"Defense News","sz":"T2","t":"US missile shortages create a range problem, report shows","th":"Az Egyesült Államok rakétahiányai tartományi problémákat okoznak","u":"https://www.defensenews.com/air/2026/11/19/us-missile-shortages-create-a-range-problem-report-shows/","d":"2026-11-19","x":"A legfrissebb elemzés szerint az Egyesült Államok kritikus hosszú hatótávolságú rakétakészletei kimerültek, ami arra kényszerítheti a katonai erőket, hogy 300 mérföld alatti hatótávolságú lőszerekre támaszkodjanak. A jelentés szerint a Pentagon megállapodásokat kötött a gyártókkal a termelési sebesség növelésére, de az idő sürgető, mivel a készletek kimerülése sebezhetőségeket teremt. A jelentés hangsúlyozza, hogy a hosszú hatótávolságú lőszerek hiánya operatív kihívásokat jelent, különösen Kínával szemben. A jelentés megállapítja, hogy a rövid hatótávolságú lőszerek használata növeli a légifölény megszerzésének fontosságát, ami bonyodalmakat okozhat, ha az Egyesült Államok erős ellenféllel néz szembe.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Rakéták és hiperszonikus fegyverek","Lőszer és védelmi ipari kapacitás"],"oc":["United States","Iran","China"],"p":8,"cm":2,"cid":12666,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Rakétahiány jelentős probléma, de nem új."},{"id":12693,"s":"Military Times","sz":"T2","t":"US missile shortages create a range problem, report shows","th":"Az Egyesült Államok rakétahiányai tartományi problémát okoznak","u":"https://www.militarytimes.com/news/your-military/2026/11/19/us-missile-shortages-create-a-range-problem-report-shows/","d":"2026-11-19","x":"A legfrissebb elemzés szerint az Egyesült Államok kritikus hosszú hatótávolságú rakétakészletei kimerültek, ami arra kényszerítheti a katonai erőket, hogy 300 mérföld alatti hatótávolságú lőszerekre támaszkodjanak. A jelentés hangsúlyozza, hogy a Pentagon megállapodásokat kötött a gyártókkal a termelési sebesség növelésére, azonban az idő sürgető, mivel a készletek kimerülése sebezhetőségeket teremt. A jelentés szerint a Patriot rakéták és a THAAD rakéták erősen használtak, és a készletek kritikus állapotban vannak. A rövid hatótávolságú lőszerek, mint például a levegő-levegő rakéták, nem szenvednek jelentős korlátozásoktól, de a hosszú hatótávolságú lőszerek hiánya operatív kihívásokat teremt az Egyesült Államok számára. A jelentés figyelmeztet arra, hogy a kereslet meghaladja a kínálatot, így a helyzet javítása időbe telik.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Rakéták és hiperszonikus fegyverek","Lőszer és védelmi ipari kapacitás"],"oc":["United States","Iran","China"],"p":8,"cm":2,"cid":12666},{"id":12669,"s":"Defense News","sz":"T2","t":"Pentagon lacks ‘overarching plan’ for munitions production, watchdog warns","th":"A Pentagon hiányolja az 'átfogó tervet' a lőszerek gyártásához","u":"https://www.defensenews.com/industry/techwatch/2026/11/19/pentagon-lacks-overarching-plan-for-munitions-production-watchdog-warns/","d":"2026-11-19","x":"A Pentagon gyorsan próbálja növelni a lőszerek gyártását a kimerült készletek miatt, de a legújabb jelentés szerint nem rendelnek lőszereket a katonai igények figyelembevételével. A Kormányzati Számvevőszék (GAO) figyelmeztetett, hogy a védelmi minisztérium nem rendelkezik olyan átfogó tervvel, amely összekapcsolná a lőszerek gyártását és finanszírozását a követelményekkel. A jelentés szerint a Pentagon nem tudja pontosan, mennyi lőszer áll rendelkezésre, és a különböző katonai szolgálatok adatai nem mindig egyeznek. A GAO javasolta, hogy a Pentagon dolgozzon ki egy átfogó tervet a lőszerek követelményeinek, gyártásának és finanszírozásának összekapcsolására. A jelentés hangsúlyozza, hogy enélkül a Pentagon nem lesz képes kezelni a folyamatosan alacsony lőszerszámokat.","dom":"MDO","br":"Tüzér és tűztámogatás","sp":["Lőszer és védelmi ipari kapacitás","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":8,"cm":2,"cid":12669,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Lőszerhiány ismert probléma, részletezés.","hu":["közvetett","A Pentagon lőszer gyártási és beszerzési problémái közvetett módon relevánsak lehetnek Magyarország számára, mivel a magyar védelmi ipar is érintett a lőszergyártásban. A Rheinmetall Hungary Munitions Zrt. Várpalotán lőszert szállít a Magyar Honvédség számára, és a szállítások 2023-ban kezdődtek meg [HU-04]. A magyar védelmi ipar ágazati koncepciója célul tűzi ki a hazai gyártás növelését és a technológiatranszferes beszerzést [HU-16].","ok"]},{"id":12697,"s":"Military Times","sz":"T2","t":"Pentagon lacks ‘overarching plan’ for munitions production, watchdog warns","th":"A Pentagon hiányolja az átfogó tervet a lőszerek gyártásához","u":"https://www.militarytimes.com/industry/techwatch/2026/11/19/pentagon-lacks-overarching-plan-for-munitions-production-watchdog-warns/","d":"2026-11-19","x":"A Pentagon gyorsan próbálja növelni a lőszerek gyártását a kimerült készletek miatt, azonban a jelentés szerint a lőszerek megrendelése nem veszi figyelembe a katonai igényeket. A GAO jelentés figyelmeztetett arra, hogy a védelmi minisztérium nem rendelkezik átfogó tervvel, amely összekapcsolná a lőszerek gyártását és finanszírozását a követelményekkel. A hadsereg sürgősen próbálja növelni a 155 mm-es tüzérségi lövedékek gyártását, de a gyártási problémák miatt ez a folyamat nehézkes. A GAO javasolta, hogy a Pentagon hozzon létre egy átfogó tervet a lőszerek követelményeinek, gyártásának és finanszírozásának összekapcsolására.","dom":"MDO","br":"Tüzér és tűztámogatás","sp":["Lőszer és védelmi ipari kapacitás","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":8,"cm":2,"cid":12669,"hu":["közvetett","A Pentagon lőszer gyártási kapacitásának növelésére irányuló törekvései közvetett módon relevánsak lehetnek Magyarország számára, mivel a Rheinmetall Hungary Munitions Zrt. Várpalotán lőszert gyárt a Magyar Honvédség számára, beleértve a tüzérségi rendszerekhez szükséges lőszereket is [HU-04]. A magyar lőszer gyártás 2023-ban kezdődött, és a megrendelések 2031-ig teljesülnek [HU-04]. A Pentagon által javasolt átfogó tervezés a lőszergyártás és a katonai igények összekapcsolására hasznos lehet a magyar védelmi ipar számára is, különösen a hazai gyártás előnyben részesítése miatt [HU-18].","ok"]},{"id":12670,"s":"Defense News","sz":"T2","t":"France and Sweden hold first joint nuclear-deterrence exercise","th":"Franciaország és Svédország közös nukleáris elrettentési gyakorlatot tartott","u":"https://www.defensenews.com/global/europe/2026/11/19/france-and-sweden-hold-first-joint-nuclear-deterrence-exercise/","d":"2026-11-19","x":"Franciaország és Svédország első közös gyakorlatát tartotta a nukleáris elrettentés terén, amelyet a francia elnök, Emmanuel Macron javaslatára indítottak el. A gyakorlat során francia nukleáris képességgel rendelkező Rafale vadászgépek és egy Airbus A330 MRTT tanker repülőgép működött együtt svéd Gripen vadászgépekkel. A gyakorlat célja a két légierő közötti interoperabilitás javítása volt, és nem használtak tényleges nukleáris fegyvereket. A gyakorlat demonstrálta a két ország közötti közös készséget és elkötelezettséget a fenyegetések elrettentése és a szövetséges biztonság erősítése iránt. A Rafale és Gripen gépek együttműködése új műveleti lehetőségeket nyit meg, különösen a nukleáris elrettentés terén.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Nukleáris elrettentés","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["France","Sweden"],"p":8,"cm":1,"cid":12670},{"id":12671,"s":"Defense News","sz":"T2","t":"F-35C completes first launch and recovery trials on a Ford-class carrier","th":"F-35C első indítási és visszatérési tesztje a Ford-osztályú repülőgép-hordozón","u":"https://www.defensenews.com/air/2026/11/19/f-35c-completes-first-launch-and-recovery-trials-on-a-ford-class-carrier/","d":"2026-11-19","x":"Két F-35C Lightning II vadászgép sikeresen teljesítette az első indítási és visszatérési tesztet az USS John F. Kennedy repülőgép-hordozón. A teszt során 34 repülést hajtottak végre, 122 katapult indítással és 122 landolással. Az új Ford-osztályú hordozók az Electromagnetic Aircraft Launch System (EMALS) és az Advanced Arresting Gear (AAG) rendszereket használják, amelyek simább és pontosabb indítást, valamint szélesebb körű visszatérési feltételeket tesznek lehetővé. A tesztelés célja a repülőgép és a hordozó közötti integráció elősegítése volt, amely lehetővé teszi az F-35C teljes flottán való üzemeltetését. A USS John F. Kennedy várhatóan 2027 tavaszán kerül hivatalosan átadásra.","dom":"MAR","br":"Haditengerészeti repülés és tengeri járőr","sp":["Hajóépítés és haditengerészet"],"oc":["United States"],"p":8,"cm":2,"cid":12671,"sp2":65,"ind":"Jelentőség 4/5, újdonság 4/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Új teszt a Ford-osztályú hordozón."},{"id":12672,"s":"Defense News","sz":"T2","t":"Hegseth, in Caracas, announces US-Venezuela military partnership agreement","th":"Hegseth, Caracasban bejelenti az Egyesült Államok és Venezuela katonai partnerségi megállapodását","u":"https://www.defensenews.com/pentagon/2026/11/19/hegseth-in-caracas-announces-us-venezuela-military-partnership-agreement/","d":"2026-11-19","x":"Pete Hegseth, az Egyesült Államok védelmi minisztere bejelentette a Venezuela elleni katonai együttműködési megállapodást, amely közös kiképzést, hírszerzési információk megosztását és más katonai együttműködési aspektusokat foglal magában. A megállapodás célja a közös fenyegetések elleni fellépés és Venezuela fegyveres erőinek képzésének megerősítése. Hegseth hangsúlyozta, hogy a partnerség jelentős növekedést hoz a drogkereskedő csoportok elleni közös akciókban. A megállapodás a venezuelai olajszektorban is növekvő amerikai befolyást tükröz, amely a Maduro elmozdítása óta gyorsan alakítja az ország jövőjét. A megállapodás a katonai modernizáció és a közös védelmi képességek fejlesztésének fontos lépése.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Venezuela"],"p":8,"cm":2,"cid":12672},{"id":12700,"s":"Military Times","sz":"T2","t":"Hegseth, in Caracas, announces US-Venezuela military partnership agreement","th":"Hegseth, Caracasban bejelenti az Egyesült Államok és Venezuela katonai partnerségi megállapodását","u":"https://www.militarytimes.com/news/pentagon-congress/2026/11/19/hegseth-in-caracas-announces-us-venezuela-military-partnership-agreement/","d":"2026-11-19","x":"Pete Hegseth, az Egyesült Államok védelmi minisztere bejelentette a Venezuela elleni katonai együttműködési megállapodást, amely közös kiképzést, hírszerzés megosztását és más katonai együttműködési aspektusokat foglal magában. A megállapodás célja a közös fenyegetések elleni fellépés és a venezuelai fegyveres erők kiképzésének megerősítése. Hegseth hangsúlyozta, hogy a partnerség jelentős növekedést hoz a kábítószer-kereskedő csoportok elleni közös fellépésben. A megállapodás a venezuelai olajszektorral kapcsolatos amerikai befolyás növekedését is tükrözi. Hegseth látogatása a latin-amerikai körútja részeként zajlott, amely során Kolumbiába is ellátogatott, hogy katonai felszerelést adjon át és biztonsági együttműködésről tárgyaljon.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Venezuela"],"p":8,"cm":2,"cid":12672,"sp2":73,"ind":"Jelentőség 4/5, újdonság 4/5, megerősítettség 3/5 (3 forrás), forrásszint 3/5. Új katonai partnerség, jelentős együttműködés."},{"id":12678,"s":"The Record (Recorded Future News)","sz":"T2","t":"CISA nominee LoSapio vows to bolster cyber defenses while denying Jan. 6 Capitol attack","th":"LoSapio, a CISA jelöltje, ígéretet tett a kibervédelem megerősítésére","u":"https://therecord.media/cisa-losapio-nomination-trump","d":"2026-11-19","x":"Michael LoSapio, a Kibervédelmi és Infrastruktúra Biztonsági Ügynökség (CISA) jelöltje, ígéretet tett arra, hogy feltárja a szervezetben lévő hiányosságokat, amelyeket a személyi állomány és a költségvetés drasztikus csökkentése okozott. LoSapio hangsúlyozta, hogy a CISA a kibervédelem szempontjából olyan, mint a 911-es segélyhívó rendszer. Ha megerősítik, együtt kíván működni a közösséggel és a nemzeti laboratóriumokkal, hogy támogassa a védekezőket a hálózataik védelmében. A költségvetés növelésének szükségességéről azonban nem foglalt állást, hangsúlyozva, hogy a megfelelő megoldásokra való költés csökkenti a kockázatot. A bizottság várhatóan a következő héten szavaz a jelöléséről.","dom":"CYB","br":"Védelmi kiberműveletek","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":7,"cm":1,"cid":12678},{"id":11425,"s":"Atlantic Council","sz":"T1","t":"Dispatch from Kyiv: Let Ukraine strike Russia’s missile launchers at the source","th":"Ukrajna támadja Oroszország rakétakilövőit","u":"https://www.atlanticcouncil.org/dispatches/dispatch-from-kyiv-let-ukraine-strike-russias-missile-launchers-at-the-source/","d":"2026-11-18","x":"A cikk bemutatja, hogy Ukrajna hogyan küzd Oroszország rakétatámadásaival szemben, és milyen kihívásokkal néznek szembe a légvédelmi rendszerek. A Starshield rendszer sebességkorlátozása és a Patriot rakéták hiánya jelentős problémát jelent az ukrán erők számára. A cikk hangsúlyozza, hogy az Egyesült Államoknak sürgősen lépéseket kellene tennie a Starshield korlátozások feloldására és a Patriot rakéták átadására, hogy Ukrajna hatékonyabban tudja védeni magát a téli hónapokban. Az ukrán légierő F-16-os pilótái is aktívan részt vesznek a drónok elleni harcban, de a korlátozott számú repülőgép és a hosszú repülési órák nehezítik a feladatukat.","dom":"AIR","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Drónok és drónelhárítás","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Ukraine","Russia","United States"],"p":8,"cm":1,"cid":11425,"sp2":53,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Ismert ukrán kihívások, kevés újdonság."},{"id":11671,"s":"Lowy Interpreter","sz":"T1","t":"Washington built the hub-and-spokes – Australia and Japan are rewiring it","th":"Washington kiépítette a középpontot és a küllőket – Ausztrália és Japán újraírja azt","u":"https://www.lowyinstitute.org/the-interpreter/washington-built-the-hub-and-spokes-australia-and-japan-are-rewiring-it","d":"2026-11-19","x":"Az Ausztrália és Japán közötti védelmi együttműködés jelentős fejlődésen ment keresztül az utóbbi években. A két ország közös hadgyakorlatokat tart, és már közösen fejlesztenek fegyvereket, például egy nagy energiájú lézert. Japán Mogami fregattokat épít az Ausztrál Haditengerészet számára, az első 2029-re várható. A két ország közötti együttműködés kiterjed a katonai interoperabilitásra és közös hadműveletekre is, különösen a Fülöp-szigetek védelmi ipara és technológiája terén. Az új architektúra, amely a középpontot és a küllőket helyettesíti, lehetővé teszi a regionális biztonság fenntartását és a stratégiai egyensúly megőrzését. A partnerség folyamatosan bővül, és a jövőbeni közös védelmi megállapodások is várhatóak.","dom":"MDO","br":"Tüzér és tűztámogatás","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás","Lőszer és védelmi ipari kapacitás"],"oc":["Australia","Japan","United States","Philippines"],"p":8,"cm":1,"cid":11671,"sp2":58,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Ausztrál-japán együttműködés fejlődése."},{"id":11820,"s":"Breaking Defense","sz":"T2","t":"Navy taps one-star admiral to advance hypersonic weapons, SLCM-N integration at Crane","th":"A haditengerészet egy csillagos admirális kinevezése a hiperszonikus fegyverek és az SLCM-N integráció előmozdítására","u":"https://breakingdefense.com/2026/11/navy-taps-one-star-admiral-to-advance-hypersonic-weapons-slcm-n-integration-at-crane/","d":"2026-11-18","x":"Az Egyesült Államok Haditengerészete sikeresen tesztelte a második szakaszú szilárd rakétamotorját a hiperszonikus támadási képesség fejlesztésének részeként. A haditengerészet Rear Adm. Patrick Finney-t nevezte ki, hogy előmozdítsa a Nukleáris Tengerészeti Indító Rakéta (SLCM-N) és a hiperszonikus Conventional Prompt Strike (CPS) fegyverrendszerek integrációját. A program célja, hogy a Zumwalt-osztályú rombolók és a Virginia-osztályú tengeralattjárók számára biztosítsa a hiperszonikus rakéták telepítését. A program költségvetése 15-20 milliárd dollárra becsülhető, és az első működési képességet 2034-re tervezik elérni.","dom":"MAR","br":"Tengeralattjárók","sp":["Rakéták és hiperszonikus fegyverek","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":11820,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Hiperszonikus fegyverek fejlesztése."},{"id":11821,"s":"Breaking Defense","sz":"T2","t":"Making Super Intelligence useful when connectivity disappears at the tactical edge","th":"A szuperintelligencia hasznosítása, amikor a kapcsolódás megszűnik a taktikai élen","u":"https://breakingdefense.com/2026/11/making-super-intelligence-useful-when-connectivity-disappears-at-the-tactical-edge/","d":"2026-11-18","x":"A szuperintelligencia (SI) alkalmazása a taktikai élen nem csupán a modellek telepítését jelenti, hanem a környezethez való alkalmazkodást is. A hadviselőknek megbízható információkra van szükségük, még akkor is, ha a kapcsolódás megszakad vagy korlátozott. A drónok fontos szerepet játszanak az adatok gyűjtésében, de a feldolgozás gyakran nem a platformon történik. Az SI segíthet a döntések gyorsításában, különösen a logisztikai és személyzeti menedzsment területén. A kihívás az, hogy a modelleknek képesnek kell lenniük a hatékony működésre korlátozott környezetben is. A szuperintelligencia ígérete a gyorsabb döntéshozatal, amely a hadműveletek széles spektrumában alkalmazható.","dom":"MDO","br":"Lövész és gépesített lövész csapatok","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)","Drónok és drónelhárítás"],"oc":["United States"],"p":8,"cm":1,"cid":11821,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Általános SI alkalmazás, kevés újdonság."},{"id":11822,"s":"Breaking Defense","sz":"T2","t":"Britain has the frigate the US needs, and Americans should build it: UK minister","th":"Britannia rendelkezik azzal a fregattal, amire az Egyesült Államoknak szüksége van, és az amerikaiaknak ezt kellene megépíteniük","u":"https://breakingdefense.com/2026/11/britain-has-the-frigate-the-us-needs-and-americans-should-build-it-uk-minister/","d":"2026-11-18","x":"Luke Pollard, az Egyesült Királyság védelmi készültségért és iparért felelős államtitkára hangsúlyozta, hogy az Egyesült Államok haditengerészetének szüksége van fregattokra, és a brit ipar képes biztosítani a szükséges terveket. A brit Arrowhead 140 fregatt tervezése már bizonyított, és alkalmas a különböző feladatok ellátására, beleértve a légi védelmet és a tengeri biztonságot. Az Egyesült Államoknak lehetősége van arra, hogy saját igényei szerint alakítsa ki a hajót, miközben brit ipari tudást is felhasználhat. A két ország közötti együttműködés nemcsak a védelmi képességeket erősíti, hanem gazdasági előnyöket is hoz az amerikai közösségek számára. Az együttműködés alapja a bizalom, amely lehetővé teszi a közös hadműveletek és ipari kapacitások mobilizálását.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet"],"oc":["United Kingdom","United States"],"p":8,"cm":1,"cid":11822,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Vélemény a brit fregattokról."},{"id":11835,"s":"The War Zone","sz":"T2","t":"Europe Is Exploring Orbital Deep Strike Weapons","th":"Európa az orbitális mélycsapású fegyverek lehetőségeit vizsgálja","u":"https://www.twz.com/space/europe-is-exploring-orbital-deep-strike-weapons","d":"2026-11-18","x":"Európa kezdi felfedezni a hagyományos katonai rakományok orbitális szállításának lehetőségét, a német MBDA és az ATMOS Space Cargo együttműködésével. A javasolt Precision Orbital Deep Strike (PODS) koncepció célja, hogy katonai rakományokat helyezzenek el az űrben, majd azokat a parancsra visszaküldjék a légkörbe. A kezdeti munkák a rendszer architektúrájára, technikai megvalósíthatóságára és a rakomány integrációjára összpontosítanak. A koncepció ambiciózus, mivel a rakományok orbitális pályára juttatása és a célzott csapás precíz végrehajtása különböző kihívásokat jelent. A PODS célja, hogy megerősítse Európa hagyományos elrettentését.","dom":"SPA","br":"Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)","sp":["Hajóépítés és haditengerészet","Világűr- és műholdképességek"],"oc":["Germany","United States","China"],"p":8,"cm":1,"cid":11835,"sp2":65,"ind":"Jelentőség 4/5, újdonság 4/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új koncepció az orbitális fegyverekről."},{"id":11836,"s":"The War Zone","sz":"T2","t":"Flying Stripped-Down F-15 “Silver Eagles” To Their Limits","th":"A F-15 „Silver Eagles” határainak feszegetése","u":"https://www.twz.com/air/flying-stripped-down-f-15-silver-eagles-to-their-limits","d":"2026-11-18","x":"A Robins Légibázison végzett F-15E Strike Eagles karbantartás és tesztelés folyamata során a repülőgépeket teljesen lemeztelenítik, hogy a legújabb fejlesztéseket alkalmazzák rajtuk. Az F-15E-k mélykarbantartása során a repülőgépek alapos ellenőrzésen esnek át, és a szükséges javításokat is elvégzik. Az új F-15EX modellek bevezetése előtt a meglévő F-15E flotta teljesítményének maximalizálása érdekében a repülőgépeket különböző tesztelési eljárásoknak vetik alá. A tesztpilóták tapasztalatai alapján ezek a lecsupaszított F-15-ök a legmagasabb teljesítményű gépek a világon.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":8,"cm":1,"cid":11836,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. F-15E karbantartás, ismert folyamat."},{"id":11837,"s":"The War Zone","sz":"T2","t":"U.S. Air Force’s Containerized Surface-To-Air Missile Program Comes Into Sharper Focus","th":"Az Egyesült Államok Légierőjének Konténeres Felszíni-Légi Rakéta Programja Élesebb Figyelmet Kap","u":"https://www.twz.com/land/u-s-air-forces-containerized-surface-to-air-missile-program-comes-into-sharper-focus","d":"2026-11-18","x":"Az Egyesült Államok Légierője számos szerződést kötött egy új, alacsony költségű légvédelmi rakéta és konténeres indítók kifejlesztésére. A Counter-Air Missile Program (CAMP) célja, hogy a rakéták költsége ne haladja meg az 500 000 dollárt, és évente legalább 1000 darabot tudjanak gyártani. A program célja a földi légvédelmi képességek bővítése, amely eddig a hadseregtől függött. Az első fázisban földindítású prototípusokat fognak előállítani, amelyek megalapozzák a hivatalos programot. A program célja, hogy alacsony költségű, nagy mennyiségben gyártható légvédelmi rakétákat biztosítson az Egyesült Államok számára.","dom":"AIR","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Rakéták és hiperszonikus fegyverek","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":11837,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új légvédelmi rakétaprogram."},{"id":11838,"s":"The War Zone","sz":"T2","t":"This Is What Submarine HMS Vengeance Looks Like After Its Record-Setting Nuclear Deterrence Patrol","th":"Így néz ki a HMS Vengeance tengeralattjáró a rekordhosszúságú nukleáris elrettentési küldetése után","u":"https://www.twz.com/sea/this-is-what-submarine-hms-vengeance-looks-like-after-its-record-setting-nuclear-deterrance-patrol","d":"2026-11-18","x":"A HMS Vengeance tengeralattjáró hét hónapos nukleáris elrettentési küldetés után tért vissza hazai kikötőjébe, ahol a hajó állapota jelentős kopásról tanúskodik. A küldetés része volt az Operation Relentless, amely biztosítja, hogy mindig legyen egy nukleáris fegyverekkel felszerelt tengeralattjáró a tengeren. A Vengeance küldetése rekordot döntött, 217 napot töltött a víz alatt, ami kérdéseket vetett fel a tengerészek terhelhetőségéről és az elöregedő tengeralattjárók megbízhatóságáról. A tengeralattjáró állapota, beleértve a hiányzó anechoic csempéket és a korróziót, a hosszú küldetések utáni tipikus jelenség. Az Egyesült Királyságnak több tengeralattjáróra van szüksége a jövőbeni elrettentés biztosítása érdekében.","dom":"MAR","br":"Tengeralattjárók","sp":["Nukleáris elrettentés","Haderő-modernizáció és erőszerkezet"],"oc":["United Kingdom"],"p":8,"cm":1,"cid":11838,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Ismert tengeralattjáró küldetés."},{"id":11858,"s":"Naval News","sz":"T2","t":"South Korea Launches Fifth FFX Batch-III Frigate, ROKS Pyeongtaek","th":"Dél-Korea bemutatja az ötödik FFX Batch-III fregattot, a ROKS Pyeongtaek-et","u":"https://www.navalnews.com/naval-news/2026/11/south-korea-launches-fifth-ffx-batch-iii-frigate-roks-pyeongtaek/","d":"2026-11-18","x":"Dél-Korea november 18-án bemutatta az ötödik FFX Batch-III fregattját, a ROKS Pyeongtaek-et, amely fejlett elektronikai hadviselési és kiberbiztonsági rendszerekkel rendelkezik. A hajó a haditengerészet elöregedett fregattjait hivatott leváltani. A fregatt 3,600 tonnás, 129 méter hosszú, és számos korszerű fegyverzettel van felszerelve, beleértve a 5 hüvelykes tüzérségi ágyút és a koreai függőleges indító rendszert. A hajó építése 2023 novemberében kezdődött, és várhatóan 2027 decemberében kerül átadásra a haditengerészetnek. A ROKS Pyeongtaek a jövőbeli védelmi exportokban is jelentős szerepet játszhat.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["South Korea"],"p":8,"cm":1,"cid":11858,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új dél-koreai fregatt bemutatása."},{"id":11868,"s":"Defense One","sz":"T2","t":"Need range time? The Army now has an online reservation system","th":"Online foglalási rendszer az amerikai hadsereg számára","u":"https://www.defenseone.com/defense-systems/2026/11/need-range-time-army-now-has-online-reservation-system/417309/","d":"2026-11-18","x":"Az amerikai hadsereg új online foglalási rendszert indított, amely célja a fegyverek tesztelésére szánt idő csökkentése. A rendszer bevezetése óta a várakozási időt több mint egy évről 30 napra csökkentették. A teszteléshez szükséges helyszínek közé tartozik a Dugway Proving Ground és a Yuma Proving Ground is. A rendszer lehetővé teszi a cégek számára, hogy gyorsan és rugalmasan teszteljék rendszereiket, különösen a drónok és a hosszú hatótávolságú fegyverek esetében. A program eddig 156 kérést kapott, és a tesztelési folyamat már folyamatban van.","dom":"LAND","br":"Tüzér és tűztámogatás","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["United States","Morocco"],"p":7,"cm":1,"cid":11868},{"id":11870,"s":"Defense One","sz":"T2","t":"Senate grills acting Navy secretary on Iran war costs, extended deployments","th":"Szenátus kihallgatja az ideiglenes haditengerészeti titkárt az iráni háború költségeiről és a hosszabb küldetésekről","u":"https://www.defenseone.com/defense-systems/2026/11/senate-grills-acting-navy-secretary-iran-war-costs-extended-deployments/417307/","d":"2026-11-18","x":"A szenátus kihallgatásán Hung Cao, az ideiglenes haditengerészeti titkár, válaszolt a szenátorok kérdéseire az iráni háború költségeivel és a haditengerészet készültségi állapotával kapcsolatban. Cao elmondta, hogy az iráni háború erőforrásokra gyakorolt nyomást gyakorol, de nem tudott részletes válaszokat adni a költségekre vonatkozóan. A szenátorok aggodalmukat fejezték ki a háború költségei és a haditengerészeti modernizációs erőfeszítések közötti összefüggés miatt. A kihallgatás során Cao hangsúlyozta a mentális egészség fontosságát a tengerészek körében, de a szenátorok kritikákat fogalmaztak meg a meglévő intézkedések elégtelensége miatt.","dom":"MAR","br":"Haditengerészeti repülés és tengeri járőr","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Iran"],"p":7,"cm":1,"cid":11870},{"id":11900,"s":"DefenseScoop","sz":"T2","t":"Navy to test new software platform for Project Roundtable","th":"A Haditengerészet új szoftverplatformot tesztel a Roundtable projekthez","u":"https://defensescoop.com/2026/11/18/navy-software-platform-project-roundtable/","d":"2026-11-18","x":"A Haditengerészet és a GovSignals együttműködésében új prototípus szoftverplatformot tesztelnek a Roundtable projekt keretében. A kezdeményezés célja, hogy megkönnyítse a hivatalnokok ipari kapcsolattartását és a technológiai fejlesztések nyomon követését. A projekt keretében a GovSignals egy digitális platformot prototípusoz, ahol a beszállítók információt adhatnak be újításaikról. A rendszer automatikusan rögzíti az interakciókat, így a résztvevő szervezetek teljes történetet kapnak a Haditengerészettel való kapcsolatukról. A program célja, hogy gyorsabbá tegye a technológiai megoldások elérhetőségét a tengerészek és tengerészgyalogosok számára.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Vezetés-irányítás és ISR (C2/ISR)","MI és autonómia"],"oc":["United States"],"p":7,"cm":1,"cid":11900},{"id":11911,"s":"SpaceNews","sz":"T2","t":"All Points Logistics Announces Partnership with Expeditors for Space Prep Logistics Center at Kennedy Space Center","th":"Az All Points Logistics partnerséget hirdetett az Expeditors-szal a Kennedy Űrközpont űrlogisztikai központjának előkészítésére","u":"https://spacenews.com/all-points-logistics-announces-partnership-with-expeditors-for-space-prep-logistics-center-at-kennedy-space-center/","d":"2026-11-18","x":"Az All Points Logistics bejelentette, hogy partnerséget alakít ki az Expeditors International-nal a Kennedy Űrközpontban tervezett Űrlogisztikai Központ számára. Az Expeditors a helyszínen biztosít logisztikai szolgáltatásokat kormányzati ügynökségek és kereskedelmi űrüzemeltetők számára. A központ célja, hogy támogassa az űrjárművek és a kapcsolódó anyagok logisztikai igényeit, beleértve a raktározást és a szállítást. A létesítmény 2027 végére készül el, és a Kennedy Űrközpont közelében helyezkedik el. A partnerség célja, hogy javítsa az űripar logisztikai hatékonyságát és támogassa a küldetések sikeres lebonyolítását.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Hajóépítés és haditengerészet","Világűr- és műholdképességek"],"oc":["United States"],"p":7,"cm":1,"cid":11911},{"id":11929,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"Air Force Fires Minuteman III ICBM in Test Launch","th":"Légierő: Minuteman III ICBM tesztindítása","u":"https://www.airandspaceforces.com/air-force-global-strike-test-launch-minuteman-icbm/","d":"2026-11-18","x":"A légierő unarmed Minuteman III interkontinentális ballisztikus rakétát indított a kaliforniai Vandenberg Űrközpontból 2026. november 17-én. Az ICBM tesztindítások célja, hogy biztosítsák az Egyesült Államok ICBM flottájának készenlétét és megbízhatóságát. A teszt során a rakéta 4200 mérföldet repült, hogy célba találjon a Marshall-szigeteken található Kwajalein Atollon. A légierő a Minuteman III rendszer modernizálására és fejlesztésére közel 86,5 milliárd dollárt tervez költeni a 2027-es költségvetésében. A Minuteman III rakéták hatékonyságának fenntartása kulcsfontosságú a nukleáris elrettentés szempontjából.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Rakéták és hiperszonikus fegyverek","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":11929,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Ismert ICBM tesztelési gyakorlat."},{"id":11932,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"Feds: Irish National Vandalized C-130 So Thoroughly It Was ‘Effectively Destroyed’","th":"Ír állampolgár vandalizálta a C-130-as repülőt, így az 'gyakorlatilag megsemmisült'","u":"https://www.airandspaceforces.com/feds-irish-national-vandalized-c-130-so-thoroughly-it-was-effectively-destroyed/","d":"2026-11-18","x":"Egy ír állampolgárt azzal vádolnak, hogy módszeresen vandalizálta az Egyesült Államok Légierő C-130H Hercules repülőgépét a shannoni repülőtéren, annyira, hogy a 60 millió dolláros szállítórepülőgép gyakorlatilag megsemmisült. A vádirat szerint a vádlott hónapokig kutatott a repülőgép felépítése után, és előre megtervezte a támadást. A vandalizmus következtében a repülőgép üzemképtelenné vált, és a hatóságok szerint a cselekedetei súlyos robbanásveszélyt jelentettek a közelben tartózkodó emberekre, beleértve az amerikai katonákat is. Az ügyészség 10 év börtönbüntetést kérhet a vádlott számára. A vandalizmus mértéke messze meghaladta a korábbi hasonló eseteket, amelyek 2025-ben történtek a shannoni repülőtéren.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Ireland","United States"],"p":8,"cm":1,"cid":11932,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Vandalizmus, nem jelentős haditechnikai hír."},{"id":11937,"s":"Defense News","sz":"T2","t":"US surges power projection to westernmost island chain as Russia, China loom","th":"Az Egyesült Államok fokozza a hatalomkivetítést a legnyugatibb szigetláncra, miközben Oroszország és Kína fenyegetései körvonalazódnak","u":"https://www.defensenews.com/global/the-americas/2026/11/18/us-surges-power-projection-to-westernmost-island-chain-as-russia-china-loom/","d":"2026-11-18","x":"Az Egyesült Államok Légierője fokozza a kiképzést a legnyugatibb szigeteken, hogy több helyet fejlesszen ki a hatalomkivetítésre és az ellenfelek megfigyelésére a Csendes-óceánon és az Északi-sarkvidéken. Az Eareckson Légitámaszponton végzett gyakorlatok során F-16-osok és más repülőgépek üzemeltek, demonstrálva a gyors reagálás képességét. A légierő tervei között szerepel a közép-csendes-óceáni szigetek, például Rota és Tinian légiközlekedési műveleteinek fokozása, amelyek célja a kínai fenyegetés elleni védekezés erősítése. A fejlesztések a légierő rugalmasságát és az üzemeltetési helyszínek számának növelését célozzák, csökkentve a Guam-i Andersen Légitámaszpontra való támaszkodást.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Canada","Russia","China"],"p":8,"cm":2,"cid":11937,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Kiképzési fokozás, de nem új fejlemény."},{"id":11938,"s":"Defense News","sz":"T2","t":"US Navy used expired munitions during Iran war, Cao says","th":"Az Egyesült Államok Haditengerészete lejárt lőszereket használt az iráni háború alatt","u":"https://www.defensenews.com/newsletters/daily-news-roundup/2026/11/18/us-navy-used-expired-munitions-during-iran-war-cao-says/","d":"2026-11-18","x":"Hung Cao, az Egyesült Államok Haditengerészetének ügyvezető titkára elmondta, hogy a haditengerészet lejárt lőszereket használt az iráni háború során. A hadműveletek során használt lőszerek egy része korábban használhatatlannak volt minősítve. A hadsereg munitions hiányosságokkal küzdött, miután jelentős mennyiségű Tomahawk rakétát lőtt ki. A védelmi minisztérium kérte a kongresszust, hogy hagyja jóvá a Tomahawk rakétakészlet feltöltésére vonatkozó 3 milliárd dolláros támogatást. A Raytheon 22,9 milliárd dolláros szerződést kapott a Tomahawk rakéták gyártásának növelésére. A haditengerészet dolgozik a lőszerek nagyobb mennyiségű előállításán.","dom":"MAR","br":"Haditengerészeti repülés és tengeri járőr","sp":["Lőszer és védelmi ipari kapacitás","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":7,"cm":2,"cid":11938},{"id":11964,"s":"Military Times","sz":"T2","t":"US Navy used expired munitions during Iran war, Cao says","th":"Az Egyesült Államok Haditengerészete lejárt lőszereket használt az iráni háború alatt","u":"https://www.militarytimes.com/news/your-military/2026/11/18/us-navy-used-expired-munitions-during-iran-war-cao-says/","d":"2026-11-18","x":"Hung Cao, az Egyesült Államok Haditengerészetének ügyvezető titkára elmondta, hogy a haditengerészet lejárt lőszereket használt az iráni háború során. A hadműveletek során a hadsereg képes volt újrakódolni és felhasználni azokat a lőszereket, amelyeket korábban használhatatlannak minősítettek. A hadsereg munitions hiányosságokkal küzdött, és a Tomahawk rakéták készletének feltöltésére 3 milliárd dolláros támogatást kért a Kongresszustól. A Raytheon 22,9 milliárd dolláros szerződést kapott a Tomahawk rakéták gyártásának növelésére. A lejárt lőszerek újrahasználata hasonló a lejárt gyógyszerekhez, amelyek hatékonysága megmaradhat.","dom":"MAR","br":"Haditengerészeti repülés és tengeri járőr","sp":["Lőszer és védelmi ipari kapacitás","Beszerzés és védelmi költségvetés"],"oc":["United States","Iran"],"p":7,"cm":2,"cid":11938},{"id":11949,"s":"The Record (Recorded Future News)","sz":"T2","t":"Lawmakers call on White House to develop defensive AI cyber systems","th":"Törvényhozók felhívják a Fehér Házat, hogy fejlesszenek ki védelmi AI kiberrendszereket","u":"https://therecord.media/ai-cyber-white-house","d":"2026-11-18","x":"Két szenátor felhívta a Fehér Házat, hogy indítson nemzeti erőfeszítést az AI-alapú kibertámadásokkal szembeni védekezés megerősítésére. Figyelmeztettek, hogy az AI gyorsan képes felfedezni és kihasználni a szoftverek gyengeségeit, és az ország védelme nem tart lépést ezzel. A szenátorok sürgették, hogy a Fehér Ház gyorsítsa fel a védelmi AI-eszközök fejlesztését és bevezetését, valamint állítson fel biztonsági szabványokat az autonóm AI ügynökök számára. A javasolt védelmi eszközöknek folyamatosan azonosítaniuk kell a sebezhetőségeket, fejleszteniük és tesztelniük kell a javításokat, valamint blokkolniuk kell a támadásokat, mielőtt azok elterjednének. A Fehér Ház felhívta a figyelmet arra is, hogy szükség van egy nemzeti kibervédelmi nagykihívásra.","dom":"CYB","br":"Védelmi kiberműveletek","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","China","Japan","South Korea"],"p":8,"cm":1,"cid":11949,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Általános felhívás AI fejlesztésre."},{"id":11952,"s":"Army Technology","sz":"T2","t":"Ukraine submits defence list for European funding approval","th":"Ukrajna benyújtotta védelmi listáját az európai finanszírozás jóváhagyására","u":"https://www.army-technology.com/news/ukraine-submits-defence-list-for-european-funding-approval/","d":"2026-11-18","x":"Ukrajna több mint 1000 DOT-Chain védelmi rendszert nyújtott be az EU finanszírozásának jóváhagyására. A benyújtott lista 95%-át képviseli az ukrán hadsereg DOT-Chain védelmi hálózatán leadott megrendeléseknek. Az EU 1,71 milliárd eurót biztosított a katonai beszerzésekhez, amely lehetővé teszi a gyártók számára, hogy kifizetést kapjanak a már leadott megrendelésekért. A DOT-Chain rendszer gyorsabb beszerzési lehetőségeket kínál, lehetővé téve a katonai egységek számára, hogy közvetlenül a gyártóktól vásároljanak drónokat és egyéb rendszereket. Az ukrán védelmi beszerzési ügynökség hangsúlyozta, hogy a nem jóváhagyott rendszerek nem kerültek eltávolításra a DOT-Chain védelmi hálózatból.","dom":"MDO","br":"Lövész és gépesített lövész csapatok","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["Ukraine"],"p":8,"cm":1,"cid":11952,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Ukrajna védelmi beszerzési listája."},{"id":11928,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"‘Holy S—, That’s Tehran!’: B-2 Pilots Tell the Story of Operation Midnight Hammer","th":"‘Atyaég, ez Teherán!’: A B-2 Pilóták mesélik el a Midnight Hammer művelet történetét","u":"https://www.airandspaceforces.com/inside-operation-midnight-hammer-b-2-pilots/","d":"2026-11-18","x":"A B-2 Spirit bombázók részt vettek a Midnight Hammer műveletben, amely során az Egyesült Államok támadást indított Irán Fordow nukleáris létesítménye ellen. A művelet során a pilóták két Massive Ordnance Penetrator bombát dobtak le, amelyek jelentős károkat okoztak Irán nukleáris programjában. A támadást F-22, F-35 és F-16 típusú repülőgépek támogatták, összesen 125 repülőgép vett részt a műveletben. A támadás célja a nukleáris anyagok fegyverkezési szintre való dúsításának megakadályozása volt. A művelet 15 év tervezésének eredménye volt, és a B-2 bombázók új, mélyen behatoló fegyverekkel hajtották végre a támadást. A művelet sikerességét a szakértők jelentősnek értékelték, de a pontos károk mértéke továbbra is rejtély maradt.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Rakéták és hiperszonikus fegyverek"],"oc":["United States","Iran"],"p":9,"cm":1,"cid":11928,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Jelentős művelet részletei, de nem új hír."},{"id":11954,"s":"Army Technology","sz":"T2","t":"BAE Systems unveils SUV-portable passive radar to track aerial threats","th":"BAE Systems bemutatja az SUV-hoz hordozható passzív radart a légi fenyegetések követésére","u":"https://www.army-technology.com/news/bae-systems-passive-radar/","d":"2026-11-18","x":"A BAE Systems új, titkos radarszolgáltatása képes észlelni és követni a légi fenyegetéseket anélkül, hogy saját helyzetét felfedné. Ez a passzív radar rendszer lehetővé teszi a katonai egységek számára, hogy diszkréten figyeljék a légi aktivitást, így növelve a védelmi képességeiket. A fejlesztés célja a modern hadviselés kihívásainak kezelése, különös figyelmet fordítva a drónok és egyéb légi eszközök fenyegetéseire. A rendszer mobilitása lehetővé teszi, hogy különböző terepen is alkalmazható legyen, így a hadsereg rugalmasságát is növeli.","dom":"AIR","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Drónok és drónelhárítás","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["UK","USA"],"p":7,"cm":1,"cid":11954},{"id":11648,"s":"ASPI The Strategist","sz":"T1","t":"Australia and the US should give ANZUS teeth and make it a deterrence network","th":"Ausztráliának és az Egyesült Államoknak erősítenie kell az ANZUS-t és elrettentő hálózattá kell alakítania","u":"https://www.aspistrategist.org.au/australia-and-the-us-should-give-anzus-teeth-and-make-it-a-deterrence-network/","d":"2026-11-18","x":"Az ANZUS szerződés 75. évfordulója alkalmából Ausztráliának és az Egyesült Államoknak át kell alakítania a megállapodást egy elrettentő hálózattá, amely gyorsan telepíthető eszközökre épül. A cikk hangsúlyozza, hogy a növekvő kínai katonai erő és az Egyesült Államok tranzakcionális külpolitikája miatt sürgős lépések szükségesek. Ausztráliának prioritásként kell kezelnie a hazai lőszergyártást, a légibázisok megerősítését és a nukleáris integrációt. A cikk javasolja a regionális együttműködés erősítését is, különösen Új-Zéland és Délkelet-Ázsiai partnerek bevonásával. Az AUKUS partnerségnek gyors, gyakorlati képességeket kell biztosítania, hogy a jövőbeli fenyegetésekre reagálni tudjon.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","Rakéták és hiperszonikus fegyverek","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Australia","United States","New Zealand"],"p":8,"cm":1,"cid":11648,"sp2":45,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Általános vélemény az ANZUS-ról."},{"id":11484,"s":"RUSI","sz":"T1","t":"Can Drones Replace Soldiers? NATO's Uncrewed Strategy","th":"A drónok helyettesíthetik a katonákat? A NATO pilóta nélküli stratégiája","u":"https://www.rusi.org/news-and-comment/video-commentary/can-drones-replace-soldiers-natos-uncrewed-strategy","d":"2026-11-19","x":"A FPV (first-person view) drónok elválaszthatatlanul összekapcsolódtak a katonák tömeges megölésével, valamint a páncélozott járművek és más hadianyag megsemmisítésével Ukrajnában. A NATO pilóta nélküli stratégiája a drónok katonai alkalmazásának növekvő jelentőségét tükrözi, amely új kihívásokat és lehetőségeket teremt a modern hadviselésben. A drónok szerepe a jövőbeli harci környezetben egyre inkább felértékelődik, ami a hagyományos katonai erők átalakulásához vezethet.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás"],"oc":["Ukraine"],"p":7,"cm":1,"cid":11484},{"id":11859,"s":"Naval News","sz":"T2","t":"Congress Rebukes U.S. Navy Battleship in New Budget Proposal","th":"A Kongresszus elutasítja az Egyesült Államok Haditengerészetének csatahajóját az új költségvetési javaslatban","u":"https://www.navalnews.com/naval-news/2026/11/congress-rebukes-u-s-navy-battleship-in-new-budget-proposal/","d":"2026-11-18","x":"A szenátusi költségvetési bizottság bemutatta a Pentagon 1,1 billió dolláros költségvetési javaslatát, amelyben szinte teljes mértékben elutasítják az Egyesült Államok Haditengerészetének 34,000 tonnás irányított rakétás csatahajóját. A javasolt költségvetési csökkentések 1,84 milliárd dollár eltávolítását jelentik a BBG(X) program finanszírozásából, amely a haditengerészet legújabb hajóépítési kezdeményezése. A bizottság aggodalmát fejezte ki a költségvetési kérés hatékonyságával kapcsolatban, és úgy véli, hogy a haditengerészet nem áll készen a program előrehaladására. A BBG(X) csatahajó a legnagyobb amerikai felszíni harci hajó lenne a második világháború óta, ha megépülne.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":7,"cm":1,"cid":11859},{"id":11910,"s":"SpaceNews","sz":"T2","t":"Flexell Space and ALATYR Sign MoU to Explore Solar Power Solutions for Orbital Data Centers","th":"A Flexell Space és az ALATYR együttműködési megállapodást írt alá űrbeli adatközpontok napenergia megoldásainak feltárására","u":"https://spacenews.com/flexell-space-and-alatyr-sign-mou-to-explore-solar-power-solutions-for-orbital-data-centers/","d":"2026-11-18","x":"A Flexell Space és az ALATYR együttműködési megállapodást (MoU) írt alá, hogy napenergia megoldásokat vizsgáljanak az űrbeli számítástechnikai infrastruktúrához. A partnerség célja a következő generációs ultrakönnyű napelemek alkalmazásának felmérése az űrbeli adatközpontokban. A Flexell Space a CIGS és perovszkit technológiákra alapozva fejleszti napelemeit, amelyek célja, hogy megbízható energiaforrást biztosítsanak a műholdak és más űrbeli infrastruktúrák számára. A két cég közötti együttműködés célja a jövőbeli közös fejlesztések és validációk megalapozása. A megállapodás fontos lépés a dél-koreai és francia űrenergia és infrastruktúra közötti együttműködés erősítésében.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Világűr- és műholdképességek"],"oc":["South Korea","France"],"p":7,"cm":1,"cid":11910},{"id":11931,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"Hegseth Makes Surprise Visit to Venezuela to Strengthen Military Ties","th":"Hegseth meglepetéslátogatása Venezuelában a katonai kapcsolatok megerősítése érdekében","u":"https://www.airandspaceforces.com/hegseth-makes-surprise-visit-venezuela-to-strengthen-military-ties/","d":"2026-11-18","x":"Pete Hegseth védelmi miniszter meglepetéslátogatást tett Venezuelában, ahol megállapodást írt alá a két ország közötti katonai kapcsolatok helyreállításáról. Az új megállapodás a katonai együttműködést, beleértve a kiképzést és az hírszerzési információk megosztását is magában foglalja. Hegseth szerint Venezuela a legagresszívebb regionális fenyegetésből a biztonsági partnerévé vált. Az új védelmi megállapodás célja a venezuelai stabilitás elősegítése és a drogkereskedelem elleni harc. Rodriguez, az ideiglenes elnök, reméli, hogy a megállapodás új katonai technológiákhoz és kiképzéshez segíti hozzá az ország fegyveres erőit.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Venezuela"],"p":7,"cm":3,"cid":11931},{"id":11933,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"Senate Backs Bigger Space Force, but Trims Pentagon Plans","th":"A Szenátus támogatja a nagyobb Űrhaderejét, de csökkenti a Pentagon terveit","u":"https://www.airandspaceforces.com/senate-backs-bigger-space-force-but-trims-pentagon-plans/","d":"2026-11-18","x":"A Szenátus Költségvetési Bizottsága 73%-kal növelné az Űrhaderejébe való befektetést 2026-ra, azonban ez a Pentagon kéréséhez képest jelentősen elmarad. Az Űrhadereje 54,7 milliárd dollárt kapna, ami a tavalyi 31,6 milliárd dollárról emelkedik. A bizottság a beszerzést helyezte előtérbe a működés és karbantartás vagy a kutatás-fejlesztés helyett. A Golden Dome rakétavédelmi programra 9,4 milliárd dollárt szánnak, ami a költségvetés egyik legnagyobb programja, de még mindig csak a Fehér Ház által kért összeg felét teszi ki. A szenátorok hangsúlyozták, hogy a programokhoz több beszállítót kell bevonni a verseny fenntartása érdekében.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Világűr- és műholdképességek","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":8,"cm":1,"cid":11933,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Űrhaderejének költségvetési növelése."},{"id":11962,"s":"Military Times","sz":"T2","t":"US surges power projection to westernmost island chain as Russia, China loom","th":"Az Egyesült Államok fokozza a hatalomkivetítést a legnyugatibb szigetláncban, miközben Oroszország és Kína fenyegetései növekednek","u":"https://www.militarytimes.com/news/your-military/2026/11/18/us-surges-power-projection-to-westernmost-island-chain-as-russia-china-loom/","d":"2026-11-18","x":"Az Egyesült Államok Légierője fokozza a kiképzést a legnyugatibb szigeteken, hogy több helyet fejlesszen ki a hatalomkivetítésre és az ellenfelek megfigyelésére a Csendes-óceánon és az Északi-sarkvidéken. Az októberi gyakorlat során F-16-osok és más repülőgépek települtek az Eareckson Légitámaszpontra, ahol a légierő sikeresen tanúsította a repülőgépek megállító rendszerét. A jövőbeni műveletek célja a sziget infrastruktúrájának védelme és a légierő működésének bővítése a Csendes-óceán középső részén található szigeteken, mint Rota, Saipan és Tinian. A fejlesztések célja, hogy növeljék a légierő működési képességeit és csökkentsék a Guam-i Andersen Légitámaszpontra való támaszkodást.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Canada","Russia","China"],"p":8,"cm":2,"cid":11937},{"id":11955,"s":"Army Technology","sz":"T2","t":"Gulf militaries rewrite procurement priorities","th":"A Perzsa-öböl hadseregei átírják a beszerzési prioritásokat","u":"https://www.army-technology.com/analyst-comment/gulf-militaries-rewrite-procurement-priorities/","d":"2026-11-18","x":"A Perzsa-öböl országai a védelmi lehetőségeiket értékelik az Egyesült Államok és Irán közötti háború következtében. A hadseregek új beszerzési prioritásokat állítanak fel, hogy reagáljanak a megváltozott biztonsági környezetre. A modernizációs és beszerzési stratégiák átdolgozása várhatóan jelentős hatással lesz a régió védelmi képességeire. A folyamat során a hadseregek figyelembe veszik a legújabb technológiai fejlesztéseket és a fenntarthatósági trendeket is. Az új prioritások célja a hatékonyabb védelem biztosítása a jövőbeli kihívásokkal szemben.","dom":"MDO","br":"Hadsereg-repülők és helikopterek","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["Saudi Arabia","Kuwait","Bahrain","United Arab Emirates"],"p":7,"cm":1,"cid":11955},{"id":11968,"s":"Military Times","sz":"T2","t":"Too easy to fly? Future T-7 trainer jet creates new instruction opportunities, general says","th":"Túl könnyű repülni? A jövő T-7 kiképző repülőgép új oktatási lehetőségeket teremt","u":"https://www.militarytimes.com/news/your-military/2026/11/18/too-easy-to-fly-future-t-7-trainer-jet-creates-new-instruction-opportunities-general-says/","d":"2026-11-18","x":"A Boeing-Saab T-7 Red Hawk kiképző repülőgép 2027-re várhatóan belép a szolgálatba, és a légierő oktatási programjainak vezetője, Clark Quinn tábornok aggodalmát fejezte ki amiatt, hogy a repülőgép túl könnyű lehet a hallgatók számára. A T-7 előnyei közé tartozik egy fejlettebb szimulátor, amely lehetővé teszi a virtuális repülést, de a tábornok hangsúlyozta, hogy a valós repülési tapasztalatok továbbra is fontosak. A T-7 várhatóan csökkenti a hagyományos harci repülőgépeken végzett alapvető manőverek számát is. A légierő már fontolgatja, hogy a T-6 Texan kiképző repülőgépek terhelését a T-7-re helyezze át a jövőben.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":8,"cm":1,"cid":11968,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új kiképző repülőgép bemutatása."},{"id":11912,"s":"SpaceNews","sz":"T2","t":"Origami and solar arrays","th":"Origami és napenergia-gyűjtők","u":"https://spacenews.com/origami-and-solar-arrays/","d":"2026-11-18","x":"A SpaceMinds podcast legújabb epizódjában Mike Gruss beszélget Thomas Sinn-nel, a Dcubed vezérigazgatójával. A beszélgetés középpontjában a cég új, 30 millió dolláros finanszírozási köre áll, valamint az origamihoz hasonlóan gondolkodás a napenergia-gyűjtőkről. A növekvő energiaigények a világűrben egyre fontosabbá válnak. A Space Inventor műholdakat épít Dániában, amelyek innovációt és megbízhatóságot kínálnak. Az epizód célja, hogy inspiráló vezetőket és technológiákat mutasson be a világűr területén.","dom":"SPA","br":"Világűr- és műholdképességek","sp":["Hajóépítés és haditengerészet"],"oc":["United States","Denmark"],"p":7,"cm":1,"cid":11912},{"id":11953,"s":"Army Technology","sz":"T2","t":"US clears potential $210m HIMARS sale to Albania","th":"Az Egyesült Államok jóváhagyta a 210 millió dolláros HIMARS eladást Albániának","u":"https://www.army-technology.com/news/us-albania-himars-m142/","d":"2026-11-18","x":"Az Egyesült Államok külügyminisztériuma jóváhagyta a 210 millió dolláros M142 High Mobility Artillery Rocket Systems (HIMARS) és kapcsolódó felszerelések eladását Albániának. Az ajánlat két HIMARS indítót, hat M31A2 rakétapodot és hat M30A2 rakétát tartalmaz. A javasolt csomag része nyolc nemzetközi tüzérségi taktikai adatkezelő rendszer és egy sor kommunikációs, navigációs, karbantartási és logisztikai felszerelés is. A vásárlás célja Albánia képességeinek erősítése a jövőbeli fenyegetések kezelésére, valamint a NATO védelmi terveihez való hozzájárulás növelése. Az albán védelmi költségvetés 2027-re körülbelül 0,7 milliárd dollárra nőhet.","dom":"LAND","br":"Tüzér és tűztámogatás","sp":["Haderő-modernizáció és erőszerkezet","Beszerzés és védelmi költségvetés"],"oc":["United States","Albania"],"p":8,"cm":1,"cid":11953,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. HIMARS eladás Albániának."},{"id":11963,"s":"Military Times","sz":"T2","t":"What AI’s rebrand to ‘super intelligence’ means for the Pentagon","th":"Mit jelent az AI 'szuperintelligenciára' való átnevezése a Pentagon számára?","u":"https://www.militarytimes.com/news/pentagon-congress/2026/11/18/what-ais-rebrand-to-super-intelligence-means-for-the-pentagon/","d":"2026-11-18","x":"A Pentagon átalakította a mesterséges intelligenciával foglalkozó hivatalának nevét, amely mostantól Szuperintelligencia Irodaként működik. A névváltoztatás célja, hogy jelezze a katonai technológia fejlődését és a szuperintelligencia teljes erejének kihasználását a katonai fölény biztosítása érdekében. A szakértők azonban figyelmeztetnek, hogy a szuperintelligencia fogalma jelenleg még elméleti, és a mai rendszerek jelentős korlátokkal rendelkeznek. A névváltoztatás mögött politikai üzenetek és a technológiai diskurzus befolyásolásának szándéka állhat. A szakértők hangsúlyozzák, hogy a mesterséges intelligencia kontrollálása kulcsfontosságú a kockázatok minimalizálása érdekében.","dom":"COG","br":"MI és döntéstámogatás","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":7,"cm":1,"cid":11963},{"id":10685,"s":"Atlantic Council","sz":"T1","t":"Ukraine’s Crimean Bridge attack is a very personal humiliation for Putin","th":"Ukrajna krími híd elleni támadása Putyin számára személyes megaláztatás","u":"https://www.atlanticcouncil.org/blogs/ukrainealert/ukraines-crimean-bridge-attack-is-a-very-personal-humiliation-for-putin/","d":"2026-11-17","x":"Ukrajna november 17-én sikeresen támadta meg a krími hidat, amely stratégiai jelentőségű összeköttetést biztosít Oroszország és az elfoglalt Krím között. A támadás során a híd középső szakasza és fő íve megsemmisült, ami jelentős katonai következményekkel jár. Zelenszkij elnök az akciót egyedülálló műveletként jellemezte, amely a híd körüli orosz légvédelmi képességek fokozatos gyengítésére épült. A támadás aláhúzza Ukrajna növekvő katonai erejét, hiszen a korábbiakhoz képest most már képesek magas értékű célpontokat elérni. A híd megsemmisítése nemcsak a logisztikát nehezíti meg az orosz hadsereg számára, hanem Putyin számára is súlyos megaláztatást jelent, mivel a híd a Krím megszerzésének szimbóluma volt.","dom":"LAND","br":"Lövész és gépesített lövész csapatok","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Ukraine","Russia"],"p":9,"cm":1,"cid":10685,"sp2":71,"ind":"Jelentőség 4/5, újdonság 4/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Stratégiai célpont sikeres támadása, új katonai képességek bemutatása."},{"id":11098,"s":"Breaking Defense","sz":"T2","t":"Army Aviation fleet facing more accidents, lower readiness rates: Obadal","th":"Csökkenő készültségi szint és növekvő balesetek az amerikai hadsereg légi flottájánál","u":"https://breakingdefense.com/2026/11/army-aviation-fleet-facing-more-accidents-lower-readiness-rates-obadal/","d":"2026-11-17","x":"Az amerikai hadsereg légi flottája az utóbbi évben csökkenő készültségi számokkal és növekvő baleseti arányokkal néz szembe. Michael Obadal, az amerikai hadsereg helyettes államtitkára elmondta, hogy a pilóták és a legénység elégtelen repülési ideje miatt nőtt a balesetek száma. A hadsereg a készültség javítása érdekében a Weapons 360 platformra támaszkodik, amely valós idejű adatokat biztosít a fő fegyverrendszerekről. Az új repülési képzési program, a Flight School Next, célja a helikopterpilóták alapvető készségeinek fejlesztése. Obadal hangsúlyozta, hogy a hadsereg légierejének javítása alapvető fontosságú.","dom":"AIR","br":"Hadsereg-repülők és helikopterek","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":7,"cm":1,"cid":11098},{"id":11102,"s":"Breaking Defense","sz":"T2","t":"A new Air Force stunt plane, plus a shakeup for special operations","th":"Új légierő akrobatikus repülőgép és változások a különleges műveletek terén","u":"https://breakingdefense.com/2026/11/a-new-air-force-stunt-plane-plus-a-shakeup-for-special-operations/","d":"2026-11-17","x":"Az Egyesült Államok Légierője új akrobatikus repülőgépet, a T-19 Kestrel-t mutatja be, amely magánfinanszírozású és célja, hogy vonzza a jövőbeli pilótákat, valamint lehetőséget adjon a kiválasztott pilóták számára a nagy teljesítményű repülés korai tapasztalatának megszerzésére. Ezen kívül a védelmi miniszter, Pete Hegseth tervei között szerepel, hogy a Pentagon legfontosabb különleges műveleti civilje nagyobb befolyást kapjon a költségvetések és döntéshozatal terén. Néhány változtatás már Hegseth hatáskörébe tartozik, de a legnagyobbakhoz a Kongresszus jóváhagyása szükséges.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":7,"cm":1,"cid":11102},{"id":11207,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"First F-15EX at Kadena Signals End in Sight for Fighter Rotations: ‘Can’t Happen Fast Enough’","th":"Első F-15EX Kadena bázison: a vadászrotációk vége a láthatáron","u":"https://www.airandspaceforces.com/first-f-15ex-kadena-end-in-sight-fighter-rotations/","d":"2026-11-17","x":"A legelső állandóan telepített F-15EX Eagle II érkezése a Kadena légibázisra Japánban nemcsak egy fejlett új vadászgépet jelent, hanem egy lépést is a légierő rotációs egységeinek nyomásának csökkentésében. Az F-15EX-ek teljes flottájának 2028-ra történő megérkezése lehetővé teszi a légierő számára, hogy fenntartsa a szükséges századokat Japánban és Alaszkában. A rotációs egységek megszüntetése lehetővé teszi a modern vadászgépek pilótáinak, hogy komplex képzéseket végezzenek, és javítsák a készségeiket. A permanens telepítés elősegíti a partnerkapcsolatok kiépítését is, különösen a Japán Légierővel. A rotációs telepítések terheinek csökkentése hozzájárulhat a pilóták megtartásához is.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Japan"],"p":8,"cm":1,"cid":11207,"sp2":68,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 5/5 (5 forrás), forrásszint 3/5. Új vadászgép telepítése, de a program már ismert."},{"id":11099,"s":"Breaking Defense","sz":"T2","t":"Biodata, AI and the future of command: Getting it right","th":"Biodata, MI és a parancsnokság jövője: A helyes megoldás megtalálása","u":"https://breakingdefense.com/2026/11/biodata-ai-and-the-future-of-command-getting-it-right/","d":"2026-11-17","x":"A cikk a biodata és a mesterséges intelligencia (MI) katonai alkalmazásának jövőjét vizsgálja, különös figyelmet fordítva a parancsnoki döntésekre. A biodata gyűjtése és értelmezése új kihívásokat jelent a katonai orvostudományban és a parancsnoki felelősségben. A cikk hangsúlyozza, hogy a megfelelően használt biodata segíthet a parancsnokoknak a katonai egységek teljesítményének javításában és a készültség optimalizálásában. Ugyanakkor figyelmeztet arra, hogy a biodata helytelen kezelése sebezhetőségeket tárhat fel, és torzíthatja a döntéseket. A cikk végül a biztonsági és adatvédelmi kérdéseket is érinti, amelyek a biodata használatával kapcsolatosak.","dom":"MDO","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":7,"cm":1,"cid":11099},{"id":11111,"s":"The War Zone","sz":"T2","t":"Trump’s Demand For Steam Catapults On New Carriers Is A “Non-Starter”: Senate Armed Forces Chair","th":"Trump követelése a gőzkatapultok visszaállítására új repülőgép-hordozókon \"nem indokolt\": Szenátusi Fegyveres Erők Bizottság elnöke","u":"https://www.twz.com/sea/trumps-demand-for-steam-catapults-on-new-carriers-is-a-non-starter-senate-armed-forces-chair","d":"2026-11-17","x":"Roger Wicker, a Szenátusi Fegyveres Erők Bizottság elnöke kijelentette, hogy Donald Trump javaslata a gőzüzemű katapultok visszaállítására az amerikai haditengerészet repülőgép-hordozóin \"nem indokolt\". Trump korábban utasította a haditengerészetet, hogy terjesszen elő terveket az elektromágneses katapultok elhagyására. Az elektromágneses repülőgép-indító rendszer (EMALS) és az Advanced Weapons Elevators (AWE) megbízhatósági problémákkal küzdenek, de a cseréjük hatalmas költségekkel és időigényes áttervezéssel járna. A Ford osztályú repülőgép-hordozók, mint a USS Gerald R. Ford, jelenleg üzemelnek, de a tervezett új hajók, mint az USS Doris Miller, késlekednek. Wicker és más szenátorok egyetértenek abban, hogy a gőzüzemű rendszerek visszaállítása nem lenne előnyös.","dom":"MAR","br":"Felszíni harci hajók","sp":["Haderő-modernizáció és erőszerkezet","Beszerzés és védelmi költségvetés"],"oc":["United States"],"p":7,"cm":1,"cid":11111},{"id":11136,"s":"Naval News","sz":"T2","t":"Hanwha Successfully Test-Fires Chunmoo Missile from Maritime Palletized Launcher","th":"A Hanwha sikeresen tesztelte a Chunmoo rakétát tengeri rakétakilövő állványról","u":"https://www.navalnews.com/naval-news/2026/11/hanwha-successfully-test-fires-chunmoo-missile-from-maritime-palletized-launcher/","d":"2026-11-17","x":"A Hanwha Defense USA és a Hanwha Aerospace sikeresen tesztelte a Chunmoo rakétát egy rakétakilövő állványról a Mississippi partjainál. A teszt célja a tengeri alapú fegyverrendszer működésének érvényesítése volt, amely lehetővé teszi a precíziós tengeri csapásmérő képességeket legénységgel és legénység nélküli hajók számára. A teszt során gyűjtött adatok segítenek a jövőbeli tengeri műveletek és expedíciós csapásmérő képességek fejlesztésében. A Hanwha célja, hogy modern csapásmérő képességeket biztosítson a tengeri platformokról, válaszolva az Egyesült Államok Haditengerészetének igényeire.","dom":"MAR","br":"Tengeri pilóta nélküli rendszerek","sp":["Rakéták és hiperszonikus fegyverek","Hajóépítés és haditengerészet"],"oc":["United States","South Korea"],"p":8,"cm":1,"cid":11136,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Rakétateszt, de a rendszer már ismert."},{"id":11215,"s":"Defense News","sz":"T2","t":"Finland’s Iceye bids €2 billion for Italian rocket maker Avio","th":"A finn Iceye 2 milliárd eurót ajánlott az olasz Avio rakétagyártónak","u":"https://www.defensenews.com/global/europe/2026/11/17/finlands-iceye-bids-e2-billion-for-italian-rocket-maker-avio/","d":"2026-11-17","x":"A finn Iceye 2 milliárd eurós készpénzes ajánlatot tett az olasz Avio rakétagyártóra, amely integrálja Európa űrkapacitásait, és lehetővé teszi az Avio amerikai rakétapiacra való terjeszkedését. Az ajánlat célja, hogy csökkentse a külső szolgáltatókra való támaszkodást, és szűkítse a különbséget az iparági vezetőkkel, mint az Egyesült Államok és Kína. Az Iceye 1 milliárd eurót kíván befektetni az Avióba az olaszországi bővítés érdekében. Az Avio már partneri kapcsolatban áll a Raytheonnal és a Lockheed Martinnal, és a közelmúltban bejelentette, hogy új létesítményt épít Virginia államban az amerikai rakétagyártás kapacitásának növelése érdekében. Az Iceye ajánlata 21,3%-os prémiumot kínál az Avio záróárához képest.","dom":"SPA","br":"Világűr- és műholdképességek","sp":["Hajóépítés és haditengerészet","Lőszer és védelmi ipari kapacitás"],"oc":["Finland","Italy"],"p":8,"cm":2,"cid":11096},{"id":11135,"s":"Naval News","sz":"T2","t":"UDT Australia 2026: Conference Discussions to be Catalyst for Converting Australian Debate on Undersea Warfare","th":"UDT Australia 2026: A konferencia vitái katalizátorként szolgálnak az ausztrál tengeralattjáró-háborúzási viták átalakításához","u":"https://www.navalnews.com/naval-news/2026/11/udt-australia-2026-undersea-warfare-debate/","d":"2026-11-17","x":"Az UDT Australia 2026 konferencia célja, hogy a tengeralattjáró-háborúzással kapcsolatos kérdéseket stratégiai szinten vitassa meg, hangsúlyozva a tengeralatti terület fontosságát Ausztrália védelmi politikájában. A konferencia során a résztvevők az autonómiára, a tengerfenéki infrastruktúrára, valamint az adat- és kommunikációs rendszerekre is fókuszálnak. A rendezvény célja, hogy elősegítse a tengeralatti képességek fejlesztését és a munkaerő képzését, mivel a jövő tengeralatti hadviselése az embereken múlik. Az AUKUS partnerség keretében Ausztrália nukleáris meghajtású tengeralattjáró képességét is fejleszti, amely szintén középpontjában áll a konferenciának. A tengeralatti biztonság kérdései kulcsfontosságúak a térség stabilitásának megőrzésében.","dom":"MAR","br":"Tengeralattjárók","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás","MI és autonómia"],"oc":["Australia","United Kingdom","United States"],"p":8,"cm":1,"cid":11135,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Konferencia vita, de nincs konkrét fejlesztés."},{"id":11137,"s":"Naval News","sz":"T2","t":"Eastern Shipbuilding to Build Grand Block Units for Future USS Telesforo Trinidad (DDG 139)","th":"Keleti Hajóépítő Grand Block egységeket épít a jövő USS Telesforo Trinidad (DDG 139) számára","u":"https://www.navalnews.com/naval-news/2026/11/eastern-shipbuilding-to-build-grand-block-units-for-future-uss-telesforo-trinidad-ddg-139/","d":"2026-11-17","x":"A Keleti Hajóépítő Csoport szerződést kapott a HII Ingalls Shipbuilding részlegétől, hogy támogassa a DDG 139, az USS Telesforo Trinidad Flight III Arleigh Burke-osztályú irányított rakétás romboló outfittingját. A szerződés keretében a Keleti Hajóépítő integrálja a főbb gyártási elemeket, beleértve a szerkezetet, HVAC-t, csövezést és elektromos rendszereket, egy teljesen összeszerelt grand blockba. A projekt lehetővé teszi a Keleti Hajóépítő számára, hogy kihasználja a korábbi Arleigh Burke-osztályú egységek szállítása során megszerzett tapasztalatait és gyártási hatékonyságait. A szerződés célja a romboló flotta termelési ütemének növelése.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet"],"oc":["United States"],"p":8,"cm":1,"cid":11137,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Hajóépítési szerződés, de nincs új technológia."},{"id":11227,"s":"Army Technology","sz":"T2","t":"Northrop Grumman secures $1.6bn PAC-3 MSE propulsion order","th":"Northrop Grumman 1,6 milliárd dolláros PAC-3 MSE hajtómű megrendelést biztosít","u":"https://www.army-technology.com/news/northrop-grumman-pac3-missile/","d":"2026-11-17","x":"A Northrop Grumman 1,6 milliárd dolláros szerződést nyert el a PAC-3 MSE rakétákhoz szükséges szilárd hajtóművek és kapcsolódó alkatrészek gyártásának növelésére az Egyesült Államok hadseregének. A többéves megrendelés célja, hogy gyorsabb szállítást biztosítson a rakétavédelmi elemek számára az Egyesült Államok és szövetségesei számára. A PAC-3 MSE rakéta a légvédelmi architektúra kulcsfontosságú eleme, amelynek hajtóművét a Northrop Grumman biztosítja. Az új szerződés része a vállalat korábbi, 3 milliárd dolláros megállapodásának, amely a PAC-3 MSE interceptor programhoz szükséges alkatrészek szállítására vonatkozik. A cég az elmúlt években jelentős beruházásokat végzett a hajtóműipari kapacitás növelésére.","dom":"AIR","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Lőszer és védelmi ipari kapacitás","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":11227,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Nagy értékű szerződés, de a rakétarendszer ismert."},{"id":10916,"s":"ASPI The Strategist","sz":"T1","t":"Collins refurbishment looks like overrunning, hitting availability","th":"A Collins osztályú tengeralattjárók felújítása csúszik, ami a rendelkezésre állást is érinti","u":"https://www.aspistrategist.org.au/collins-refurbishment-looks-like-overrunning-hitting-availability/","d":"2026-11-18","x":"Ausztrália Collins osztályú tengeralattjáróinak élettartamának meghosszabbítására irányuló tervei zökkenőmentesen haladnak, azonban a hat diesel tengeralattjáró operatív rendelkezésre állása csökkenő tendenciát mutat. A program keretében nem modernizáció, hanem csak felújítás várható, ami a flotta jelenlegi képességeit tartja fenn. A felújítási program bonyolultsága és a váratlan problémák miatt a tengeralattjárók karbantartási ütemezése csúszik, ami a legénység képzésére és a jövőbeli nukleáris tengeralattjárók legénységének toborzására is hatással van. A helyzet súlyosbodik, mivel a Collins flotta fenntartásához szükséges munkaerő egyre szűkösebbé válik a párhuzamosan zajló haditengerészeti programok miatt.","dom":"MAR","br":"Tengeralattjárók","sp":["Haderő-modernizáció és erőszerkezet","Beszerzés és védelmi költségvetés"],"oc":["Australia"],"p":7,"cm":1,"cid":10916},{"id":11095,"s":"Breaking Defense","sz":"T2","t":"Lawmakers challenge Trump’s push to bring steam catapults back to Ford-class carriers","th":"Törvényhozók kihívása Trump steam katapultok visszahozatalára a Ford-osztályú repülőgép-hordozókhoz","u":"https://breakingdefense.com/2026/11/lawmakers-challenge-trumps-push-to-bring-steam-catapults-back-to-ford-class/","d":"2026-11-17","x":"A törvényhozók mindkét párt részéről arra kérik a Haditengerészet ügyvezető titkárát, hogy reconsiderálja a steam katapultok visszaállítását a Ford-osztályú repülőgép-hordozókra, Trump utasításai nyomán. A Ford-osztály az Elektromágneses Repülőgép Indító Rendszert (EMALS) alkalmazza, amely elektromágneses energiát használ a repülőgépek indítására. Trump kritikát fogalmazott meg az EMALS-szal szemben, és a hagyományos steam katapultok és hidraulikus repülőgép-elevátorok visszaállítását javasolta. A törvényhozók aggodalmukat fejezték ki a költségek és a komplexitás növekedése miatt, ha a Haditengerészet visszatér a régi technológiához. Az ügyvezető titkár, Hung Cao, elismerte, hogy az EMALS hozzájárul a hordozók késedelmeihez.","dom":"MAR","br":"Felszíni harci hajók","sp":["Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":7,"cm":1,"cid":11095},{"id":11096,"s":"Breaking Defense","sz":"T2","t":"ICEYE makes $2B bid for Italian rocket firm Avio","th":"ICEYE 2 milliárd dolláros ajánlatot tett az olasz Avio rakétacégre","u":"https://breakingdefense.com/2026/11/iceye-makes-2b-bid-for-italian-rocket-firm-avio/","d":"2026-11-17","x":"A finn ICEYE műholdgyártó cég 2 milliárd dolláros ajánlatot tett az olasz Avio rakétacég részvényeire, hogy egy vertikálisan integrált űr- és védelmi vállalatot hozzon létre az európai piacon. Az ICEYE tervei között szerepel, hogy az elkövetkező öt évben további 1 milliárd eurót fektet be Olaszországban, amennyiben az üzlet megvalósul. Az ajánlat célja, hogy a két cég képességeit egyesítve növeljék az európai űr- és védelmi kapacitásokat, válaszolva a növekvő igényekre. Az üzlet támogatásáról a cég vezetője is nyilatkozott, hangsúlyozva a kormányok kritikus űrinfrastruktúrák feletti ellenőrzésének szükségességét.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Hajóépítés és haditengerészet","Világűr- és műholdképességek"],"oc":["Finland","Italy"],"p":8,"cm":2,"cid":11096,"sp2":65,"ind":"Jelentőség 4/5, újdonság 4/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Nagy értékű ajánlat, potenciális európai védelmi kapacitás növelés."},{"id":11097,"s":"Breaking Defense","sz":"T2","t":"Army kicks off ‘manufacturing rodeo’ with focus on small drones","th":"A hadsereg megkezdi a 'gyártási rodeót' a kis drónokra összpontosítva","u":"https://breakingdefense.com/2026/11/army-kicks-off-manufacturing-rodeo-with-focus-on-small-drones/","d":"2026-11-17","x":"A hadsereg első 'gyártási rodeója' a gyorsan építhető és skálázható egyirányú támadó drónokra összpontosít, amelyek költsége nem haladhatja meg a 3000 dollárt. A cél a stratégiai fölény elérése a hosszan tartó harci műveletek során, amelyhez a hadsereg paradigmaváltást sürget. A gyártási rodeó célja a beszállítói lánc tesztelése és a gyártási kapacitás ellenőrzése. A hadsereg 400 darab Group 1 drón és 20 földi harci állomás gyártására keres beszállítókat, akiknek a drónokat február 15-ig kell szállítaniuk tesztelésre. A sikeres rendszerek lehetőséget kapnak a tömeggyártásra, akár 10,000 drónig.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":11097,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új drónprogram, de a koncepció már ismert."},{"id":11103,"s":"Breaking Defense","sz":"T2","t":"NATO kicks off 11-nation Starlift satellite launch program","th":"NATO elindítja a 11 nemzet Starlift műholdindító programját","u":"https://breakingdefense.com/2026/11/nato-kicks-off-11-nation-starlift-satellite-launch-program/","d":"2026-11-17","x":"A NATO megkezdte a multinacionális Starlift űrprogram végrehajtását, amely a katonai műholdindító szolgáltatások biztosítására irányul. A programban részt vevő 10 tagország, valamint Dél-Korea a NATO Támogató és Beszerzési Ügynöksége (NSPA) révén finanszírozza a projektet. A Starlift célja, hogy a részt vevő országok együttműködjenek kereskedelmi indító szolgáltatókkal és űrkikötőkkel, hogy a világűrhez való hozzáférés rugalmasabb, reagálóbb és költséghatékonyabb legyen. A program részeként a NATO a jövőben további szövetségesek és partnerek csatlakozását várja. A program költségeit és a részt vevő országok pénzügyi hozzájárulásait nem hozták nyilvánosságra.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Világűr- és műholdképességek","Beszerzés és védelmi költségvetés"],"oc":["Belgium","Canada","Finland","Germany","Italy","Netherlands","Norway","Sweden","Turkey","United Kingdom","South Korea"],"p":8,"cm":1,"cid":11103,"sp2":65,"ind":"Jelentőség 4/5, újdonság 4/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új multinacionális űrprogram indítása."},{"id":11110,"s":"The War Zone","sz":"T2","t":"Russian Tu-95 Bombers Arrive In Vietnam After Flurry Of Northeast Asia Air Alerts","th":"Orosz Tu-95 Bombázók Érkezése Vietnámba Északkelet-Ázsiai Légi Riasztások Után","u":"https://www.twz.com/air/russian-bombers-arrive-in-vietnam-after-flurry-of-northeast-asia-air-alerts","d":"2026-11-17","x":"Oroszország két Tu-95MS bombázót küldött Vietnámba, amelyek korábban japán légtérbe is behatoltak. A bombázók a Japán-tenger felett 11 órás gyakorlórepülést végeztek, amelyet Il-78M légi utántöltő tankerek támogattak. A repülések a Trump, Xi és Putin közötti trilaterális találkozó előkészületei közepette zajlottak. A japán légierő figyelmeztetéseket adott ki a behatoló orosz gépek miatt, míg Tajvan is észlelte a bombázók ADIZ-be való belépését. A Tu-95MS bombázók végül Da Nangban landoltak, ahol két Il-76MD szállítórepülő kísérte őket.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)","Lőszer és védelmi ipari kapacitás"],"oc":["Russia","Vietnam","Japan","Taiwan"],"p":7,"cm":1,"cid":11110},{"id":11112,"s":"The War Zone","sz":"T2","t":"These Are The Weapons Ukraine Used To Drop The Kerch Bridge","th":"Ezeket a fegyvereket használta Ukrajna a Kercsi híd lebombázásához","u":"https://www.twz.com/news-features/these-are-the-weapons-ukraine-used-to-drop-the-kerch-bridge","d":"2026-11-17","x":"Ukrajna a Kercsi híd lebombázásához egy rendkívül változatos, hazai fejlesztésű fegyverekből álló arzenált, valamint legalább két külföldi beszerzésű eszközt használt. Az akciót az Ukrán Biztonsági Szolgálat (SBU) és a Főparancsnokság koordinálta, és több hét alatt zajlott le. Az ukrán erők a híd mellett orosz légvédelmi rendszereket, radarállomásokat és elektronikus hadviselési berendezéseket is célba vettek. Az utolsó támadás során hosszú hatótávolságú támadó drónokat, cirkálórakétákat és rövidebb hatótávolságú drónokat alkalmaztak. Az akció során több különböző drón és rakéta, köztük a Palianytsia drónok és a Neptune rakéták is részt vettek a támadásban.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Ukraine"],"p":8,"cm":1,"cid":11112,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Támadás részletei, de a híd elleni akció már ismert."},{"id":11113,"s":"The War Zone","sz":"T2","t":"What We Know About Ukraine’s Strikes That Cut Russia’s Kerch Bridge (Updated)","th":"Amit tudunk Ukrajna támadásairól, amelyek megrongálták Oroszország Kerch-hídját","u":"https://www.twz.com/news-features/what-we-know-about-ukraines-strikes-that-cut-russias-kerch-bridge-road-vehicle-span","d":"2026-11-17","x":"Ukrajna rakéta- és dróntámadásai súlyosan megrongálták a Kerch-híd egy kulcsfontosságú szakaszát. Volodimir Zelenszkij ukrán elnök elmondta, hogy a támadások egy többhetes, fokozatos művelet részei voltak, válaszul Oroszország ukrán infrastruktúra ellen irányuló folyamatos támadásaira. A támadások során különböző típusú rakétákat és drónokat használtak, beleértve az FP-5 Flamingo-t is. A híd megrongálása nemcsak szimbolikus jelentőségű, hanem logisztikai szempontból is súlyos következményekkel jár az orosz erők számára, mivel csökkenti a Krímbe vezető ellátási útvonalakat. A támadások során a légvédelmi rendszereket és elektronikus hadviselési eszközöket is semlegesítettek, hogy lehetővé tegyék a végső csapást.","dom":"MDO","br":"Lövész és gépesített lövész csapatok","sp":["Drónok és drónelhárítás","Rakéták és hiperszonikus fegyverek"],"oc":["Ukraine","Russia"],"p":8,"cm":1,"cid":11113,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Támadás részletei, de a híd elleni akció már ismert."},{"id":11145,"s":"Defense One","sz":"T2","t":"NATO aims to spur space industry, help militaries by joining data marketplace","th":"A NATO célja a űripar fellendítése és a hadseregek támogatása az adatpiacra való belépéssel","u":"https://www.defenseone.com/threats/2026/11/nato-aims-spur-space-industry-help-militaries-new-data-marketplace/417283/","d":"2026-11-18","x":"A NATO bejelentette, hogy csatlakozik egy globális adatpiachoz, amely célja az űripar fejlesztése és a hadseregek védelme. Az új platform lehetővé teszi a cégek számára, hogy adatokat értékesítsenek az űrbeli objektumokról, ami segíthet a műholdak biztonságának növelésében. A NATO várakozásai szerint a piac elősegíti a műholdak indításának ütemét, és csökkenti a kereskedelmi rendszerekre leselkedő fenyegetéseket. A STARLIFT program keretében a NATO célja, hogy támogassa a katonai felhasználókat a kereskedelmi rakéták indításában. Az adatmegosztás javítása érdekében a NATO egy információs könyvtárat is létrehozott, amely lehetővé teszi a kereskedelmi és érzékeny adatok összehasonlítását.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Világűr- és műholdképességek","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Turkey","United States"],"p":8,"cm":1,"cid":11145,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. NATO adatpiaci belépés, de a célok már ismertek."},{"id":11146,"s":"Defense One","sz":"T2","t":"OpenAI gives NATO access to most advanced cybersecurity AI","th":"OpenAI hozzáférést biztosít a NATO számára a legfejlettebb kiberbiztonsági MI-hez","u":"https://www.defenseone.com/technology/2026/11/openai-gives-nato-access-most-advanced-cybersecurity-ai/417296/","d":"2026-11-18","x":"A NATO operátorai novemberben AI ügynököket építettek és telepítettek egy gyakorlat során, az OpenAI segítségével. A NATO kormányai mostantól hozzáférhetnek az OpenAI legfejlettebb MI modelljeihez, hogy azonosítsák és javítsák a kibersebezhetőségeket. Az új eszközök használata érdekében a NATO új erőfeszítéseket tett, beleértve az AI ügynököket is. A NATO Kommunikációs és Információs Ügynöksége több mint 3 milliárd dollár értékű szerződéseket fog kiadni az iparnak 2027 végéig, a felhőalapú számítástechnika és a mesterséges intelligencia hangsúlyozásával. Az AI új módszerekkel való alkalmazása a legjobb védelem a kiberfenyegetésekkel szemben, különösen a növekvő orosz kibertámadások fényében.","dom":"CYB","br":"Védelmi kiberműveletek","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Turkey","United States"],"p":8,"cm":1,"cid":11146,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. AI kiberbiztonsági alkalmazás, de a technológia ismert."},{"id":11167,"s":"C4ISRNET","sz":"T2","t":"Watch a large aerial drone evacuate a wounded Ukrainian soldier from the front line","th":"Nézd meg, ahogy egy nagy légi drón evakuál egy sebesült ukrán katonát a frontról","u":"https://www.c4isrnet.com/videos/2026/11/17/watch-a-large-aerial-drone-evacuate-a-wounded-ukrainian-soldier-from-the-front-line/","d":"2026-11-17","x":"Ukrajna bővíti a nagy drónok használatát a harctéri orvosi evakuációk során. A videón látható, ahogy egy ukrán csapat egy légi drónt használ egy sebesült katona szállítására egy előretolt helyszínről egy tábori kórházba.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás"],"oc":["Ukraine"],"p":7,"cm":3,"cid":11167},{"id":11213,"s":"Defense News","sz":"T2","t":"Watch a large aerial drone evacuate a wounded Ukrainian soldier from the front line","th":"Nézd meg, ahogy egy nagy légi drón evakuál egy sebesült ukrán katonát a frontvonalból","u":"https://www.defensenews.com/video/2026/11/17/watch-a-large-aerial-drone-evacuate-a-wounded-ukrainian-soldier-from-the-front-line/","d":"2026-11-17","x":"Ukrajna bővíti a nagy drónok használatát a harctéri orvosi evakuációk során. A videón látható, ahogy egy ukrán csapat légi drónt használ egy sebesült katona szállítására egy előretolt helyszínről egy tábori kórházba. Ez a fejlesztés fontos lépés az orvosi ellátás gyorsításában a harctéren.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás"],"oc":["Ukraine"],"p":7,"cm":3,"cid":11167},{"id":11241,"s":"Military Times","sz":"T2","t":"Watch a large aerial drone evacuate a wounded Ukrainian soldier from the front line","th":"Nézd meg, ahogy egy nagy légi drón evakuál egy sebesült ukrán katonát a frontról","u":"https://www.militarytimes.com/video/2026/11/17/watch-a-large-aerial-drone-evacuate-a-wounded-ukrainian-soldier-from-the-front-line/","d":"2026-11-17","x":"Ukrajna bővíti a nagy drónok használatát a harctéri orvosi evakuálások során. A videón látható, ahogy egy ukrán csapat légi drónt használ egy sebesült katona szállítására egy előretolt helyszínről egy tábori kórházba.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás"],"oc":["Ukraine"],"p":7,"cm":3,"cid":11167},{"id":11177,"s":"DefenseScoop","sz":"T2","t":"Pentagon elevates AI as a ‘fundamental requirement’ for cybersecurity staff training","th":"A Pentagon az AI-t alapvető követelményként emeli ki a kiberbiztonsági személyzet képzésében","u":"https://defensescoop.com/2026/11/17/pentagon-ai-requirement-cybersecurity-training/","d":"2026-11-17","x":"A Pentagon kötelező képzési követelménnyé teszi a mesterséges intelligenciát a kiberbiztonsági munkatársai számára. Mark Gorak, a kiberakadémiai kapcsolatok igazgatója elmondta, hogy az AI mostantól alapvető készségként szerepel a kiberbiztonsági szerepkörökben. A DOD célja, hogy a kiberbiztonsági munkaerő hiányosságait orvosolja, és a jövőbeni munkavállalókat készség alapú kiválasztási folyamaton keresztül tesztelje. Jelenleg 79 kiberbiztonsági pozíció van a minisztériumban, ami a tavalyi 76-hoz képest növekedést jelent. A Pentagon célja, hogy a jövőben megfelelő munkaerőt biztosítson a kiberbiztonsági kihívások kezelésére.","dom":"CYB","br":"Védelmi kiberműveletek","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States"],"p":7,"cm":1,"cid":11177},{"id":11178,"s":"DefenseScoop","sz":"T2","t":"Space industrial base stretched thin amid low-orbit satellite constellation shift, GAO says","th":"A világűr ipari bázisa megfeszül a kis műholdas konstellációk átalakulása miatt, állítja a GAO","u":"https://defensescoop.com/2026/11/17/space-industrial-base-stretched-thin-gao-report/","d":"2026-11-17","x":"A Pentagon a kis műholdak tömeges csoportjainak használatát preferálja az alacsony Föld körüli pályán, hogy ellenálljon a kínai és orosz fenyegetéseknek, ami megfeszíti a specializált ipari bázist. A GAO jelentése szerint a Pentagon várhatóan 33 milliárd dollárt költ az elkövetkező öt évben a világűr rendszerek átalakítására. Az ipari bázis problémái veszélyeztetik a Space Force jövőbeli technológiák beszerzésének képességét. A jelentés javasolja a védelmi miniszternek, hogy központosítsa a beszállítói lánc felügyeletét az Air Force és a NRO között. A PWSA program, amely 15,6 milliárd dollárba kerül, már késlekedésekkel küzd a beszállítói lánc zavarai miatt.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Haderő-modernizáció és erőszerkezet","Világűr- és műholdképességek"],"oc":["United States"],"p":8,"cm":1,"cid":11178,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Kis műholdas konstellációk, de a koncepció ismert."},{"id":11187,"s":"SpaceNews","sz":"T2","t":"How AI is pushing satellites to evolve","th":"Hogyan alakítja át a mesterséges intelligencia a műholdakat","u":"https://spacenews.com/how-ai-is-pushing-satellites-to-evolve/","d":"2026-11-17","x":"A Space Tech Expo Europe első napján Pieter van Duijn, a Loft Orbital technológiai igazgatója beszél a kereskedelmi űriparban a mesterséges intelligencia iránti növekvő bizalomról. A műholdak használata hasonlítható egy autóbérléshez, és a beszélgetés során szóba kerülnek az elfogadás akadályai is. A műholdak innovatív fejlesztései és alkalmazásai új lehetőségeket nyújtanak a jövőbeli űrmissziókhoz. A műholdak és a mesterséges intelligencia kombinációja jelentős előnyöket kínál a megbízhatóság és a hatékonyság terén. A beszélgetés a Space Minds podcast keretein belül zajlott.","dom":"SPA","br":"Műholdas kommunikáció és ISR","sp":["Világűr- és műholdképességek"],"oc":["United States","Denmark"],"p":7,"cm":1,"cid":11187},{"id":11205,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"Senate Appropriators Constrain USAF’s Fighter Plans","th":"A Szenátus Költségvetési Bizottsága Korlátozza az USAF Vadászrepülőgép Terveit","u":"https://www.airandspaceforces.com/senate-appropriators-constrain-usaf-fighter-plans/","d":"2026-11-18","x":"A Szenátus Költségvetési Bizottsága szigorú intézkedéseket hozott az Egyesült Államok Légierőjének (USAF) vadászrepülőgép programjaival kapcsolatban, elutasítva a F-35A és F-15EX többéves beszerzését. A javasolt költségvetés 29 F-35A vadászrepülőgépet tartalmaz 2027-re, míg az F-15EX vásárlását 24-ről 18-ra csökkentették. A bizottság a jövőbeli F-47 vadászrepülő fejlesztésére szánt kutatási és fejlesztési költségvetést is csökkentette. A költségvetési tervezet összesen 11,1 milliárd dollárt irányoz elő az USAF, a Haditengerészet és a Tengerészgyalogság F-35 programjaira, beleértve a beszerzést és a fenntartást is.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":7,"cm":1,"cid":11205},{"id":11206,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"Air Force Graduated 1,518 New Pilots in Fiscal ’26 as New Training Model Takes Off","th":"A Légierő 1,518 új pilótát végzett a 2026-os pénzügyi évben az új képzési modell bevezetésével","u":"https://www.airandspaceforces.com/air-force-new-pilot-graduates-2026-goal-model/","d":"2026-11-18","x":"A Légierő 2026-ban 1,518 új pilótát végzett, ami 35 év óta a legmagasabb szám. A siker a hibrid magán-militarista képzési modellnek köszönhető, amelyet az Air Education and Training Command vezetője, Clark J. Quinn emelt ki. A képzés során a hallgatók 120 repülési órát töltenek el egyetemi keretek között, mielőtt a katonai specifikus elemeket tanulnák meg. A cél a pilótahiány csökkentése, amely 2025 végén körülbelül 2,470 fő volt. A Légierő célja, hogy a jövőben fenntartja a 1,500 fős éves képzési szintet.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Vezetés-irányítás és ISR (C2/ISR)","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":11206,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új képzési modell, de a cél már ismert."},{"id":11208,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"US Fighters Strike Iranian Missile Site After Base in Bahrain Targeted","th":"Az Egyesült Államok harci gépei csapást mértek egy iráni rakétalőhelyre, miután a bahreini bázist célba vették","u":"https://www.airandspaceforces.com/us-fighters-strike-iranian-missile-site/","d":"2026-11-17","x":"Az Egyesült Államok harci gépei, köztük F-16-osok, csapást mértek egy iráni rakétalőhelyre, amelyet az Iszlám Forradalmi Gárda üzemeltetett, önvédelem címén. A támadás válaszként érkezett, miután Irán újabb támadásokat indított a Perzsa-öböl államok bázisai és kereskedelmi hajózása ellen. Az amerikai központi parancsnokság megerősítette, hogy a támadások során több iráni drónt is megsemmisítettek, amelyek Bahrein felé tartottak. Az Egyesült Államok a térségben fokozta a légierő jelenlétét, több harci gépet és egy újabb repülőgép-hordozót telepítve. Az események a közelmúltban feszültté vált helyzetet tükrözik az Egyesült Államok és Irán között.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["United States","Iran"],"p":8,"cm":1,"cid":11208,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Válaszcsapás Irán ellen, új katonai akció."},{"id":11212,"s":"Defense News","sz":"T2","t":"Hanwha transforms ship into floating multi-rocket launcher","th":"A Hanwha hajót alakít át lebegő többsoros rakétavetővé","u":"https://www.defensenews.com/industry/techwatch/2026/11/17/hanwha-transforms-ship-into-floating-multi-rocket-launcher/","d":"2026-11-17","x":"A Hanwha Defense sikeresen indított rakétákat egy raklapra szerelhető többsoros rakétavető rendszerről a tengeren. A Chunmoo rakétarendszer rendkívüli sokoldalúságával különböző rakétákat képes indítani, beleértve a precíziós irányítással rendelkező és anélküli lőszereket is. Az Egyesült Államok Haditengerészete az utóbbi időben a konténerizált fegyverrendszerek iránti igényt hangsúlyozta, amely lehetővé teszi a platformok gyors átkonfigurálását. A Hanwha célja, hogy modern tengeri csapásmérő képességeket fejlesszen ki, amelyek a jövőbeli elosztott tengeri műveletekhez és expedíciós csapásmérő képességekhez járulnak hozzá. A teszt során gyűjtött adatok segítenek a jövőbeli fejlesztések irányának meghatározásában.","dom":"MAR","br":"Felszíni harci hajók","sp":["Rakéták és hiperszonikus fegyverek","Haderő-modernizáció és erőszerkezet"],"oc":["South Korea","United States"],"p":8,"cm":2,"cid":11212,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (2 forrás), forrásszint 3/5. Új rakétarendszer tesztelése, de a technológia már ismert."},{"id":11238,"s":"Military Times","sz":"T2","t":"Hanwha transforms ship into floating multi-rocket launcher","th":"A Hanwha átalakítja a hajót egy lebegő, több rakétát indító rendszerre","u":"https://www.militarytimes.com/news/2026/11/17/hanwha-transforms-ship-into-floating-multi-rocket-launcher/","d":"2026-11-17","x":"A Hanwha Defense sikeresen indított rakétákat egy rakétákkal felszerelt, konténerbe helyezhető indító rendszerről a tengeren. A Chunmoo egy önjáró, több rakétát indító rendszer, amely különböző rakéták kilövésére képes. Az Egyesült Államok Haditengerészete az utóbbi időben a konténerizált fegyverrendszerek iránti igényt hangsúlyozta, amelyek könnyen módosíthatók és telepíthetők. A Hanwha által bemutatott rakétás indító rendszer legénységgel és anélkül is használható, lehetővé téve, hogy autonóm felszíni hajók nehéz tűzerőt képviseljenek. A teszt során gyűjtött adatok segítenek a jövőbeli tengeri műveletek és expedíciós csapásmérő képességek alakításában.","dom":"MAR","br":"Felszíni harci hajók","sp":["Rakéták és hiperszonikus fegyverek","Haderő-modernizáció és erőszerkezet"],"oc":["South Korea","United States"],"p":8,"cm":2,"cid":11212},{"id":11216,"s":"Defense News","sz":"T2","t":"Lithuanian president says US troop rotations will continue beyond latest deployment","th":"A litván elnök szerint az amerikai csapatrotációk a legutóbbi telepítés után is folytatódnak","u":"https://www.defensenews.com/global/europe/2026/11/17/lithuanian-president-says-us-troop-rotations-will-continue-beyond-latest-deployment/","d":"2026-11-17","x":"Gitanas Nauseda litván elnök bejelentette, hogy az Egyesült Államok csapatrotációi folytatódni fognak a legutóbbi kilenc hónapos telepítés után. Az Egyesült Államok 2014 óta van jelen Litvániában, a Krím annexiója után, és azóta fenntartott egy páncélozott zászlóaljat. Az elnök hangsúlyozta, hogy a rotációs terv a jövőre is kiterjed. Az Egyesült Államok célja a védelem és a készültség fenntartása, valamint a szövetségesekkel való együttműködés. Litvánia javasolta az amerikai jelenlét bővítését vagy állandóvá tételét, és vállalta a költségek fedezését.","dom":"LAND","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Lithuania","United States"],"p":7,"cm":2,"cid":11216},{"id":11245,"s":"Military Times","sz":"T2","t":"Lithuanian president says US troop rotations will continue beyond latest deployment","th":"A litván elnök szerint az amerikai csapatrotációk a legutóbbi telepítés után is folytatódnak","u":"https://www.militarytimes.com/news/your-military/2026/11/17/lithuanian-president-says-us-troop-rotations-will-continue-beyond-latest-deployment/","d":"2026-11-17","x":"Gitanas Nauseda litván elnök bejelentette, hogy az Egyesült Államok csapatrotációi folytatódni fognak a legutóbbi kilenc hónapos telepítés után. Az Egyesült Államok 2014 óta van jelen Litvániában, miután Oroszország annektálta a Krím félszigetet. Az Egyesült Államok nagykövete a ceremónián hangsúlyozta a telepítés védelmi célját, amely a készség fenntartására és a szövetségesekkel való együttműködésre irányul. Litvánia javasolta az amerikai jelenlét bővítését, és a költségek fedezésére is hajlandó. Az ország védelmi költségvetése a 2022-es orosz invázió óta megtriplázódott.","dom":"LAND","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Lithuania","United States"],"p":7,"cm":2,"cid":11216},{"id":11223,"s":"The Record (Recorded Future News)","sz":"T2","t":"Chinese state group developing automated attack tool for cyber espionage, Google says","th":"Kínai állami csoport automatizált támadóeszközt fejleszt kibertérben","u":"https://therecord.media/chinese-state-group-developing-automated-attack-tool-espionage","d":"2026-11-17","x":"A Google legfrissebb jelentése szerint a kínai állami csoportok mesterséges intelligenciát használnak kibertérben végzett kémkedési tevékenységeikhez. Az AI-alapú eszközök, mint például az Artex és a CAIRN, lehetővé teszik a többfázisú behatolások végrehajtását. A jelentés szerint a kínai kormányzati csoportok saját verziót fejlesztenek az Artexből, amelyet valószínűleg kémkedési műveletekhez fognak használni. A kutatók megfigyelték, hogy a kínai szereplők AI platformokat használnak adatok ellopására és manipulálására is. A jelentés hangsúlyozza, hogy a kibertámadások sebessége és hatékonysága jelentősen megnőtt az AI eszközök alkalmazásával.","dom":"CYB","br":"Védelmi kiberműveletek","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["China","Russia","Iran","North Korea"],"p":8,"cm":1,"cid":11223,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Kínai kibereszközök, de a fenyegetés ismert."},{"id":11226,"s":"Army Technology","sz":"T2","t":"Ukraine gets $1.9bn from EU to fund drones and air defence","th":"Ukrajna 1,9 milliárd dollárt kap az EU-tól drónok és légvédelem finanszírozására","u":"https://www.army-technology.com/news/ukraine-eu-military-procurement/","d":"2026-11-17","x":"Az Európai Bizottság 1,71 milliárd eurót (1,88 milliárd dollárt) utalt át Ukrajnának katonai beszerzések céljából, hogy erősítse Kijev védelmi képességeit az Oroszországgal folytatott konfliktus közepette. A támogatás drónok, lőszerek és légvédelmi rendszerek, köztük korai figyelmeztető radarrendszerek és rakéták beszerzésére szolgál. Az EU célja, hogy azonnali katonai támogatást nyújtson Ukrajnának, és megerősítse a kapcsolatokat az európai védelmi ipari szektorral. Az eddigi támogatások összesen 18,1 milliárd eurót tettek ki a védelmi célokra, míg Ukrajna védelmi minisztériuma 14,6 milliárd eurót jelentett be. Az EU és tagállamai összesen 237,6 milliárd eurónyi támogatást nyújtottak Ukrajnának az invázió óta.","dom":"AIR","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Drónok és drónelhárítás","Lőszer és védelmi ipari kapacitás"],"oc":["Ukraine","European Union"],"p":8,"cm":1,"cid":11226,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Jelentős EU támogatás Ukrajnának, de a konfliktus ismert."},{"id":10187,"s":"ASPI The Strategist","sz":"T1","t":"Treaty a recognition we need Philippines in China strategy","th":"Szerződés a Fülöp-szigetek szerepének elismeréséről Kína stratégiájában","u":"https://www.aspistrategist.org.au/treaty-a-recognition-we-need-philippines-in-china-strategy/","d":"2026-11-17","x":"Ausztrália és a Fülöp-szigetek közötti védelmi együttműködés kulcsfontosságú Ausztrália védelme szempontjából. A legújabb védelmi együttműködési megállapodás elismeri, hogy Ausztrália védelme, különösen a tengeri kereskedelemre való támaszkodása, regionális partnerségek hálózatát igényli. A Fülöp-szigetek földrajzi elhelyezkedése miatt fontos szereplő a Dél-kínai-tengeren, ahol Ausztrália kereskedelmének jelentős része halad át. A Fülöp-szigetek biztonsága kulcsfontosságú a tengeri hatalom egyensúlyának fenntartásában Délkelet-Ázsiában és a Csendes-óceán nyugati részén. A megállapodás nemcsak a kapcsolat frissítése, hanem annak elismerése is, hogy Ausztrália védelme nem ér véget a partjainál.","dom":"MAR","br":"Felszíni harci hajók","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Australia","Philippines"],"p":8,"cm":1,"cid":10187,"sp2":45,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Védelmi együttműködés elismerése, regionális partnerségek fontossága."},{"id":10339,"s":"Arms Control Association","sz":"T1","t":"What is Project Velocity and why a US nuclear modernisation drive has alarmed safety experts","th":"Mi az a Project Velocity és miért aggasztja a nukleáris modernizációs törekvések a biztonsági szakértőket?","u":"https://www.armscontrol.org/media-citations/firstpost/2026-11-16","d":"2026-11-16","x":"A Project Velocity az Egyesült Államok nukleáris modernizációs programja, amely a biztonsági szakértők aggodalmát váltotta ki. A program célja a meglévő nukleáris fegyverek korszerűsítése és a védelmi képességek javítása. A szakértők szerint a modernizációs törekvések növelhetik a nukleáris fegyverek használatának kockázatát, és destabilizálhatják a globális biztonsági helyzetet. A projekt részletei és a várható hatások továbbra is vitatottak, és a szakmai közösség figyelmesen követi a fejleményeket. A modernizációs program hatásai a nemzetközi kapcsolatokra is kihatással lehetnek.","dom":"MDO","br":"Légvédelem és rakétavédelem (IAMD)","sp":["Haderő-modernizáció és erőszerkezet","Nukleáris elrettentés"],"oc":["United States"],"p":8,"cm":1,"cid":10339,"sp2":53,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 5/5. Nukleáris modernizációs program, biztonsági aggodalmak."},{"id":10367,"s":"Breaking Defense","sz":"T2","t":"Senate appropriators unveil $1.1T Pentagon spending bill, folding in reconciliation priorities","th":"Szenátusi költségvetési javaslat: 1,1 billió dolláros védelmi kiadások","u":"https://breakingdefense.com/2026/11/senate-appropriators-unveil-1-1t-pentagon-spending-bill-folding-in-reconciliation-priorities/","d":"2026-11-17","x":"A szenátusi költségvetési bizottság 1,1 billió dolláros védelmi kiadási javaslatot terjesztett elő a 2027-es pénzügyi évre, amely tartalmazza a Trump-adminisztráció által megfogalmazott prioritásokat is. A javaslatban szerepel 9,4 milliárd dollár a Golden Dome programra és 3 milliárd dollár a Védelmi Autonóm Hadviselési Csoport (DAWG) számára. A költségvetés 47,2 milliárd dollárt irányoz elő lőszerek vásárlására, és a szenátusi bizottság javaslata szerint a hadsereg repülési programjai is jelentős támogatásban részesülnek. A javasolt költségvetés még további fejlesztéseket is tartalmaz, például a Chinook helikopterek és a F-35 vadászgépek beszerzését.","dom":"MDO","br":"Tüzér és tűztámogatás","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":10367,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Jelentős védelmi költségvetési javaslat, prioritások meghatározása."},{"id":10373,"s":"Breaking Defense","sz":"T2","t":"Army’s G-TEAD expands OTA awards to push more vendors to prototyping stage","th":"A hadsereg G-TEAD bővíti az OTA szerződéseket, hogy több beszállítót juttasson a prototípus fejlesztési szakaszba","u":"https://breakingdefense.com/2026/11/armys-g-tead-expands-ota-awards-to-push-more-vendors-to-prototyping-stage/","d":"2026-11-16","x":"A hadsereg G-TEAD, amely a technológia gyors hadrendbe állításáért felelős, növeli az Other Transaction Authority (OTA) szerződések számát, hogy több beszállítót juttasson a prototípus fejlesztési szakaszba. Korábban egy OTA-t ítéltek oda, most öt-hat OTA-t fognak kiosztani, hogy bővítsék az ipari bázist. Az új rendszer lehetőséget ad a kis- és középvállalkozások számára, hogy részt vegyenek a versenyben, és a sikeres ACE-k után OTA-t nyerjenek. Az új OTA-k pénzügyi támogatást nyújtanak a vállalatok számára, hogy 45 napos operatív értékeléseken vegyenek részt, ahol visszajelzést kapnak a katonáktól és vezetőktől. A változás célja, hogy javítsa a hadsereg technológiai képességeit a valós környezetben végzett tesztelések révén.","dom":"LAND","br":"Különleges műveleti erők","sp":["Beszerzés és védelmi költségvetés","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":7,"cm":1,"cid":10373},{"id":10374,"s":"Breaking Defense","sz":"T2","t":"Navy eyes ‘operational employment’ of key UUV programs, admiral says","th":"A haditengerészet közelít a kulcsfontosságú UUV programok operatív alkalmazásához","u":"https://breakingdefense.com/2026/11/navy-eyes-operational-employment-of-key-uuv-programs-admiral-says/","d":"2026-11-16","x":"A haditengerészet közel áll ahhoz, hogy operatívan használja több pilóta nélküli víz alatti járművet (UUV), különösen az Orcát, amelyből a harmadik példányt hamarosan megkapják. A haditengerészet előrehaladást mutat a Combat Autonomous Maritime Platform (CAMP) XLUUV és a Dragonfish nagy diszpozíciós UUV programokban is. Az Orca program célja, hogy tengeri aknákat helyezzen el, és a járművek akár 6,500 tengeri mérföldes hatótávolsággal rendelkeznek, lehetővé téve a hosszú távú küldetéseket. A haditengerészet a közeljövőben befejezi az Orca gyártási terveit, és a program alapot teremt más UUV programok számára is. A haditengerészet célja, hogy az Orcát operatívan alkalmazza és jellemzőit meghatározza.","dom":"MAR","br":"Tengeralattjárók","sp":["Drónok és drónelhárítás","Hajóépítés és haditengerészet"],"oc":["United States"],"p":8,"cm":1,"cid":10374,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. UUV programok operatív alkalmazása, új tengeri képességek."},{"id":10383,"s":"The War Zone","sz":"T2","t":"Russia’s Prized Kerch Bridge Struck In Ukrainian Drone Onslaught (Updated)","th":"Oroszország értékes Kerch hídját ukrán drónok támadták meg","u":"https://www.twz.com/news-features/russias-prized-kerch-bridge-struck-in-ukrainian-drone-onslaught","d":"2026-11-17","x":"A Kerch híd, Oroszország egyik legfontosabb és legjobban védett infrastrukturális eleme, újabb támadást szenvedett el az ukrán drónok által. A legfrissebb támadás során 1,336 hosszú hatótávolságú drón vett részt az éjszakai offenzívában. Az ukrán drónok célba vették a híd ívét, amely jelentős károkat szenvedett el. A támadás különösen figyelemre méltó, mivel a Kerch híd kulcsfontosságú logisztikai kapcsolatot biztosít Oroszország és a Krím félsziget között. A híd védelmét Oroszország megerősítette, de a támadások továbbra is bizonyítják, hogy a híd sebezhető maradt. A híd állapotát a helyi hatóságok vizsgálják, és a forgalom részlegesen újraindult, de a károk mértéke még nem egyértelmű.","dom":"MDO","br":"Tüzér és tűztámogatás","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["Russia","Ukraine"],"p":8,"cm":1,"cid":10383,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Stratégiai híd elleni dróntámadás, logisztikai jelentőség."},{"id":10385,"s":"The War Zone","sz":"T2","t":"U.S. Army Now Wants Concrete Bunkers For Troops In Israel, Saudi Arabia And Lebanon","th":"Az Egyesült Államok hadserege most betonbunkereket szeretne a katonák számára Izraelben, Szaúd-Arábiában és Libanonban","u":"https://www.twz.com/news-features/u-s-army-now-wants-concrete-bunkers-for-troops-in-israel-saudi-arabia-and-lebanon","d":"2026-11-16","x":"Az Egyesült Államok Hadereje (U.S. Army Central) betonbunkereket keres, hogy helyettesítse a konténerekből készült menedékhelyeket Izraelben, Libanonban és Szaúd-Arábiában. A bunkerek célja, hogy védelmet nyújtsanak a katonák számára a potenciálisan ellenséges környezetekben. A tervek szerint a bunkereknek könnyen hozzáférhetőnek kell lenniük, és több helyszínen kell elhelyezni őket. A betonbunkerek építése sürgős, mivel a katonák jelenleg nem szabványos menedékhelyeken tartózkodnak, ami kockázatot jelent számukra. A projekt célja, hogy javítsa a katonai létesítmények védelmét a közelmúltban tapasztalt támadások után.","dom":"LAND","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["Israel","Saudi Arabia","Lebanon"],"p":8,"cm":3,"cid":10385,"sp2":60,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 3/5 (3 forrás), forrásszint 3/5. Betonbunkerek beszerzése, új védelmi infrastruktúra kialakítása."},{"id":10474,"s":"Defense News","sz":"T2","t":"US Army takes ‘urgent’ action to build concrete bunkers across the Middle East","th":"Az Egyesült Államok hadserege sürgős intézkedéseket tesz betonbunkerek építésére a Közel-Keleten","u":"https://www.defensenews.com/global/mideast-africa/2026/11/16/us-army-takes-urgent-action-to-build-concrete-bunkers-across-the-middle-east/","d":"2026-11-16","x":"Az Egyesült Államok hadserege betonbunkerek építését tervezi a Közel-Keleten, hogy megvédje a katonáit az indirekt tűz támadásoktól, mint például a rakéták és drónok. Összesen 17 bunkert kívánnak építeni, 10-et Izraelben, 5-öt Szaúd-Arábiában és 2-t Libanonban. A bunkerek célja, hogy helyettesítsék a jelenlegi, átalakított konténerekből készült védelmi menedékhelyeket. A projekt sürgős, mivel az amerikai bázisokat már korábban támadták iráni rakéták és drónok. Az építkezéshez szükséges vállalatoknak 45 napon belül kell befejezniük a munkát, és a hadsereg gyors válaszokat vár a pályázatokra.","dom":"LAND","br":"Hadsereg-légvédelem (GBAD/SHORAD)","sp":["Haderő-modernizáció és erőszerkezet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United States","Israel","Saudi Arabia","Lebanon"],"p":8,"cm":3,"cid":10385},{"id":10386,"s":"The War Zone","sz":"T2","t":"New Bow Sonar Dome For Heavily Damaged Submarine USS Connecticut Seen For The First Time (Updated)","th":"Új orr szonárdóm a súlyosan megrongált USS Connecticut tengeralattjárón","u":"https://www.twz.com/sea/new-bow-sonar-dome-for-heavily-damaged-submarine-uss-connecticut-seen-for-the-first-time","d":"2026-11-16","x":"Az USS Connecticut tengeralattjáró orr szonárdómjának cseréje a 2021-es baleset óta folyamatban van, és a Navy körülbelül három évre tervezte a csere időtartamát. A Janicki Industries 2024-re elkészítette az új dómot, amelyet 10 hónap alatt gyártottak le. A tengeralattjáró javítási munkálatai eddig csúszásokkal zajlanak, és várhatóan csak 2027 nyarára fejeződnek be. A Navy tervei között szerepel egy újabb orr szonárdóm beszerzése is, hogy felkészüljenek a jövőbeli hasonló balesetekre. Az USS Connecticut a legdrágább támadó tengeralattjárók közé tartozik, és a Navy folyamatosan befektet a visszaállításába, hogy a flotta élvonalában maradhasson.","dom":"MAR","br":"Tengeralattjárók","sp":["Haderő-modernizáció és erőszerkezet","Lőszer és védelmi ipari kapacitás"],"oc":["United States"],"p":8,"cm":1,"cid":10386,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Tengeralattjáró javítása, új szonárdóm beszerzése."},{"id":10407,"s":"Defense One","sz":"T2","t":"Air Force bets on hybrid-electric aircraft for transport","th":"A Légierő hibrid-elektromos repülőgépekre fogad a szállításhoz","u":"https://www.defenseone.com/business/2026/11/air-force-bets-hybrid-electric-aircraft-transport/417268/","d":"2026-11-16","x":"A Légierő közel 5 millió dollárt fektet egy virginiai légiközlekedési cég hibrid-elektromos repülőgépének fejlesztésébe. Az Electra EL9 prototípus repülőgép, amely kilenc üléses, különleges műveletekhez is használható. A repülőgép képes 150 lábnyi távolságból felszállni és landolni, ami hasznos lehet a különleges erők számára. A projekt célja a hibrid-elektromos meghajtás és a repülőgép teljesítményének tesztelése, amely a jövőbeli katonai műveletek során is alkalmazható lehet. Az Electra a Lockheed Martin Skunk Works-szal együttműködve elemzi, hogyan segítheti az EL9 a logisztikai műveleteket a Csendes-óceán térségében.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Haderő-modernizáció és erőszerkezet","Drónok és drónelhárítás"],"oc":["United States"],"p":8,"cm":1,"cid":10407,"sp2":52,"ind":"Jelentőség 3/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Hibrid-elektromos repülőgép fejlesztése, új technológia tesztelése."},{"id":10475,"s":"Defense News","sz":"T2","t":"New tools for troops to gun down drones | Defense News Weekly Full Episode 11.17.26","th":"Új eszközök a csapatok számára a drónok lelövésére","u":"https://www.defensenews.com/video/2026/11/16/new-tools-for-troops-to-gun-down-drones-defense-news-weekly-full-episode-11-17-26/","d":"2026-11-16","x":"Az olcsó drónok, amelyek célzott, irányított személyellenes lőszereket szállítanak, folyamatosan új védelmi rendszerek kifejlesztését ösztönzik. A cikk bemutatja az új eszközöket, amelyek segítenek a csapatoknak a drónok hatékony semlegesítésében. Emellett egy interjú is szerepel egy kitüntetett hőssel. A drónok elleni védekezés egyre fontosabbá válik a modern hadviselésben.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás"],"oc":[],"p":7,"cm":6,"cid":10429},{"id":10503,"s":"Military Times","sz":"T2","t":"New tools for troops to gun down drones | Defense News Weekly Full Episode 11.17.26","th":"Új eszközök a csapatok számára a drónok lelövésére","u":"https://www.militarytimes.com/video/2026/11/16/new-tools-for-troops-to-gun-down-drones-defense-news-weekly-full-episode-11-17-26/","d":"2026-11-16","x":"A olcsó drónok, amelyek célzott, irányított gyalogsági lőszereket szállítanak, folyamatosan új védelmi rendszerek kifejlesztését ösztönzik. Az új eszközök segítenek a csapatoknak a drónok hatékonyabb semlegesítésében. A cikk említi a drónok által jelentett fenyegetést és a védekezés lehetőségeit. A műsorban egy Medal of Honor kitüntetett interjúja is szerepel.","dom":"AIR","br":"Pilóta nélküli légi rendszerek (RPAS)","sp":["Drónok és drónelhárítás"],"oc":[],"p":7,"cm":6,"cid":10429},{"id":10440,"s":"DefenseScoop","sz":"T2","t":"Pentagon IDs companies and systems that will participate in high-energy laser ‘shoot-off’ with eye toward quick purchase orders","th":"A Pentagon azonosította azokat a cégeket és rendszereket, amelyek részt vesznek a nagy energiájú lézer 'lövészeten'","u":"https://defensescoop.com/2026/11/16/counter-drone-high-energy-laser-shoot-off/","d":"2026-11-16","x":"A Pentagon hét beszállítói csapatot választott ki, hogy részt vegyenek a nagy energiájú lézerfegyverek tesztelésében a Dugway Proving Ground területén. A cél a drónok hatékony megsemmisítése, amelyhez a résztvevő rendszerek közé tartozik többek között az AeroVironment LOCUST X1 és a Lockheed Martin Crossbow. A program célja, hogy a sikeres rendszerek azonnali beszerzését lehetővé tegye, így gyorsan bevezethetik őket a hadműveletekbe. A tesztelés során a rendszerek élő célpontok ellen fognak működni, értékelve a célpontok nyomkövetési és megsemmisítési képességeit. A Pentagon jelentős forrást biztosít a direkt energia programok számára, amely a jövőbeli beszerzések alapját képezheti.","dom":"MDO","br":"Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["United States"],"p":8,"cm":1,"cid":10440,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Nagy energiájú lézerfegyverek tesztelése, drónok elleni védelem."},{"id":10384,"s":"The War Zone","sz":"T2","t":"First F-15EXs Arrive At Kadena Air Base In Japan, 25 Now Delivered To The USAF","th":"Megérkeztek az első F-15EX-ek a japán Kadena légitámaszpontra, 25-öt szállítottak le az USAF számára","u":"https://www.twz.com/air/first-f-15exs-arrive-in-okinawa-25-now-delivered-to-the-usaf","d":"2026-11-17","x":"Az Egyesült Államok Légierője mostantól két F-15EX Eagle II vadászgépet állomásoztat a japán Okinawa szigetén található Kadena légitámaszponton. Az 18. Szárny évek óta várta az F-15EX-ek érkezését, hogy helyettesítsék a nyugdíjazott F-15C/D Eagle-eket. A Boeing megerősítette, hogy a legújabb szállítmány az EX22 és EX23 jelű gépeket tartalmazza. A tervek szerint összesen 36 F-15EX-et állomásoztatnak Japánban. Az F-15EX-ek bevezetése lehetőséget teremt a légierő számára, hogy növelje a harci kapacitását a csendes-óceáni térségben, és javítsa a hálózati műveletek hatékonyságát. Az F-15EX-ek nyújtotta képességek különösen fontosak a jövőbeli műveletek során, mivel képesek együttműködni a pilóta nélküli rendszerekkel is.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)"],"oc":["United States","Japan"],"p":8,"cm":5,"cid":10384,"sp2":72,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 4/5 (4 forrás), forrásszint 3/5. Új vadászgépek érkezése Japánba, fontos regionális fejlemény."},{"id":10468,"s":"Air \u0026 Space Forces Magazine","sz":"T2","t":"Kadena Gets First Permanent F-15EX in Boost to USAF’s Pacific Airpower","th":"Kadena megkapta első állandó F-15EX repülőgépét az USAF csendes-óceáni légierejének megerősítése érdekében","u":"https://www.airandspaceforces.com/kadena-first-permanent-f-15ex-arrives/","d":"2026-11-16","x":"A Kadena Légibázis megkapta első állandó F-15EX Eagle II repülőgépét 2026. november 15-én. Az új gép érkezése négy évvel azután történt, hogy az USAF elkezdte visszavonni a régi F-15C/D típusú gépeit. Az F-15EX modern avionikával és elektronikus hadviselési képességekkel rendelkezik, amelyek erősítik az Egyesült Államok légierejét a Csendes-óceán térségében. A gép állandó jelenléte a Kadena bázison megerősíti az Egyesült Államok és Japán közötti szövetséget, és biztosítja a fejlett harci képességek fenntartását a stratégiailag fontos régióban. Az F-15EX a negyedik generációs F-15C/D és F-16 vadászgépek jelentős fejlesztésének számít.","dom":"AIR","br":"Vadász- és csapásmérő légierő","sp":["Haderő-modernizáció és erőszerkezet","Légi felderítés és korai előrejelzés (ISR, AEW\u0026C)"],"oc":["United States","Japan"],"p":8,"cm":5,"cid":10384},{"id":10476,"s":"Defense News","sz":"T2","t":"Europe hunts for Palantir alternatives as militaries seek to limit US dependence","th":"Európa alternatívákat keres a Palantir számára, hogy csökkentse az amerikai függőséget","u":"https://www.defensenews.com/news/2026/11/16/europe-hunts-for-palantir-alternatives-as-militaries-seek-to-limit-us-dependence/","d":"2026-11-16","x":"Európa védelmi minisztériumai az amerikai technológiák és a Palantir Technologies szoftver függőségének csökkentésére törekednek, ezért egyre több helyi cég versenyez a katonai megrendelésekért. A német Helsing legutóbb egy Clarity nevű katonai hírszerző szoftvert mutatott be, amely mesterséges intelligenciát használ a katonai döntéshozatal felgyorsítására. Franciaország egy Arcadia nevű, szuverén AI-alapú katonai platformot fejleszt, amely több beszállítót is magában foglal. A holland hadsereg szintén alternatívát keres a Palantir szoftver helyett, amelyet jelenleg használnak. Az európai országok közötti együttműködés és az interoperabilitás kérdései továbbra is kihívást jelentenek a NATO számára.","dom":"COG","br":"Híradó és informatikai csapatok (CIS)","sp":["Vezetés-irányítás és ISR (C2/ISR)","MI és autonómia"],"oc":["Germany","France","Netherlands","Ukraine"],"p":7,"cm":2,"cid":10476},{"id":10477,"s":"Defense News","sz":"T2","t":"China has ‘normalized’ naval presence near Japan since political spat of 2025","th":"Kína 'normalizálta' tengeri jelenlétét Japán közelében a 2025-ös politikai vita óta","u":"https://www.defensenews.com/global/asia-pacific/2026/11/16/china-has-normalized-naval-presence-near-japan-since-political-spat-of-2025/","d":"2026-11-16","x":"Kína jelentős tengeri jelenlétet alakított ki Japán közelében, miután 2025 novemberében politikai vita robbant ki a japán miniszterelnök, Sanae Takaichi megjegyzései miatt. A kínai haditengerészet flottája, amely több mint 100 hajóból állt, a japán déli szigetek körüli vizekben tevékenykedett, jelezve, hogy Kína nyomást gyakorol Japánra. A haditengerészeti műveletek, beleértve a élő tűzgyakorlatokat és drónmissziókat, célja, hogy Kína fokozza jelenlétét a térségben anélkül, hogy megsértené a nemzetközi tengeri jogot. Japán a védelmi költségvetésének jelentős növelését tervezi, hogy reagáljon a fokozódó biztonsági fenyegetésekre. A helyzet tovább bonyolódik Kína és Oroszország közötti együttműködéssel a térségben.","dom":"MAR","br":"Felszíni harci hajók","sp":["Hajóépítés és haditengerészet","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["China","Japan","Russia","Taiwan"],"p":8,"cm":1,"cid":10477,"sp2":39,"ind":"Jelentőség 2/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Kína tengeri jelenlétének növekedése, politikai feszültségek."},{"id":10480,"s":"Defense News","sz":"T2","t":"Marine Corps doubles, extends contract for M27 rifles","th":"A Tengerészgyalogság megduplázza és meghosszabbítja az M27-es puskákra vonatkozó szerződést","u":"https://www.defensenews.com/industry/2026/11/16/marine-corps-doubles-extends-contract-for-m27-rifles/","d":"2026-11-16","x":"A Tengerészgyalogság több mint megduplázta a Heckler \u0026 Koch fegyvergyártóval kötött M27-es gyalogsági automata puska szerződésének keretét, amely 39,23 millió dollárról 84,6 millió dollárra emelkedett. Az M27-es fegyverrendszert 15 éve tesztelik és használják, és a Tengerészgyalogság a közelharci alakulatok számára jobban megfelelőnek találta, mint a hadsereg M7-es puskáját. Az M27-es puskát a M249-es géppuska helyettesítésére szánták, de végül a Tengerészgyalogság standard fegyverévé vált. A fegyver 5,56 mm-es NATO lőszert használ, és a gyártás többsége Németországban, míg a többi Columbusban, Georgiában történik.","dom":"LAND","br":"Lövész és gépesített lövész csapatok","sp":["Lőszer és védelmi ipari kapacitás","Haderő-modernizáció és erőszerkezet"],"oc":["United States","Germany"],"p":8,"cm":1,"cid":10480,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. M27-es puskák szerződésének bővítése, fegyverrendszer modernizáció."},{"id":10487,"s":"The Record (Recorded Future News)","sz":"T2","t":"King Charles opens new HQ for National Cyber Force, UK’s offensive hacking unit","th":"Károly király megnyitja az új központot a Nemzeti Kibervédelmi Erő számára, az Egyesült Királyság támadó hackercsapatának","u":"https://therecord.media/uk-national-cyber-force-headquarters-opens","d":"2026-11-16","x":"Károly király november 16-án megnyitotta az Egyesült Királyság Nemzeti Kibervédelmi Erőjének új központját, amely a titkos egység, amely az ország támadó kiberműveleteit irányítja. Az új központ, a Ribble House, a Lancashire-i Samlesbury közelében található. A brit kormány 5 milliárd fontot (6,5 milliárd dollárt) költ a NCF-re 2030-ig. A NCF a GCHQ, a Védelmi Minisztérium, a MI6 és a Védelmi Tudományos és Technológiai Laboratórium munkatársait egyesíti. A kibervédelmi erő nyilatkozata szerint a kiberműveletek minden nap zajlanak, és a központ megnyitása fontos lépés az Egyesült Királyság védelmi képességeinek megerősítésében. A nyitóünnepség egybeesett azzal a figyelmeztetéssel, hogy az ország","dom":"CYB","br":"Védelmi kiberműveletek","sp":["MI és autonómia","Vezetés-irányítás és ISR (C2/ISR)"],"oc":["United Kingdom"],"p":8,"cm":1,"cid":10487,"sp2":47,"ind":"Jelentőség 3/5, újdonság 2/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Új kibervédelmi központ megnyitása, támadó képességek fejlesztése."},{"id":10488,"s":"Army Technology","sz":"T2","t":"THEON secures $408m European night vision orders","th":"A THEON 408 millió dolláros európai éjjellátó megrendeléseket biztosít","u":"https://www.army-technology.com/news/theon-night-vision-order/","d":"2026-11-16","x":"A THEON International védelmi technológiai cég új megrendeléseket kapott Európából, összesen körülbelül 370 millió euró (408 millió dollár) értékben, több ezer éjjellátó eszközre. A THEON éjjellátó, hőkamerás, kiterjesztett valóságú és elektro-optikai megfigyelő rendszereket fejleszt a védelem és biztonság területén. A megrendelések a védelmi ipar modernizációját és a haditechnikai kapacitások fejlesztését célozzák. A cég termékei fontos szerepet játszanak a hadsereg híradó és informatikai csapatainak felszerelésében.","dom":"LAND","br":"Híradó és informatikai csapatok (CIS)","sp":["Lőszer és védelmi ipari kapacitás","Haderő-modernizáció és erőszerkezet"],"oc":["Greece","Germany","France","Italy"],"p":8,"cm":1,"cid":10488,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Nagy értékű éjjellátó megrendelések, védelmi kapacitás növelése."},{"id":10489,"s":"Army Technology","sz":"T2","t":"US Army tests drone swarms and armed ground vehicles in Germany","th":"Az Egyesült Államok hadserege drónrajokat és fegyverzettel ellátott földi járműveket tesztel Németországban","u":"https://www.army-technology.com/news/us-army-drone-test-germany/","d":"2026-11-16","x":"Az Egyesült Államok hadserege élő tűzgyakorlatot hajtott végre Németországban, amelyben koordinált dróncsapások, pilóta nélküli földi járművek és meglévő rakétarendszerek vettek részt. A gyakorlat célja a pilóta nélküli légi és földi rendszerek kombinálásának vizsgálata volt, hogy távolsági hatásokat érjenek el, miközben csökkentik a személyzet közvetlen jelenlétének szükségességét a célpontok közelében. A gyakorlat során különböző fegyverekkel felszerelt R3NEGADE járművek is bemutatásra kerültek. Az esemény összhangban állt az Egyesült Államok hadseregének operatív keretrendszerével.","dom":"LAND","br":"Hadsereg-repülők és helikopterek","sp":["Drónok és drónelhárítás","Haderő-modernizáció és erőszerkezet"],"oc":["United States","Germany"],"p":8,"cm":1,"cid":10489,"sp2":60,"ind":"Jelentőség 4/5, újdonság 3/5, megerősítettség 1/5 (1 forrás), forrásszint 3/5. Drónrajok és fegyverzettel ellátott járművek tesztelése, új taktikai képességek."}],"sources":[{"n":"DefenseScoop","sz":"T2","r":15,"c":16},{"n":"The War Zone","sz":"T2","r":34,"c":39},{"n":"Air \u0026 Space Forces Magazine","sz":"T2","r":22,"c":26},{"n":"Army Technology","sz":"T2","r":18,"c":23},{"n":"SpaceNews","sz":"T2","r":7,"c":9},{"n":"Breaking Defense","sz":"T2","r":43,"c":65},{"n":"Defense News","sz":"T2","r":32,"c":56},{"n":"Naval News","sz":"T2","r":24,"c":44},{"n":"Defense One","sz":"T2","r":12,"c":23},{"n":"C4ISRNET","sz":"T2","r":7,"c":14},{"n":"Military Times","sz":"T2","r":31,"c":69},{"n":"ASPI The Strategist","sz":"T1","r":13,"c":30},{"n":"Modern War Institute","sz":"T1","r":3,"c":7},{"n":"War on the Rocks","sz":"T1","r":4,"c":24},{"n":"ICDS","sz":"T1","r":1,"c":6},{"n":"RUSI","sz":"T1","r":3,"c":22},{"n":"Atlantic Council","sz":"T1","r":7,"c":61},{"n":"Lowy Interpreter","sz":"T1","r":4,"c":36},{"n":"The Record (Recorded Future News)","sz":"T2","r":4,"c":41},{"n":"OSW","sz":"T1","r":1,"c":12},{"n":"Arms Control Association","sz":"T1","r":1,"c":13},{"n":"CBO","sz":"T1","r":1,"c":19},{"n":"House of Commons Library","sz":"T1","r":1,"c":51},{"n":"RAND","sz":"T1","r":0,"c":38},{"n":"CFR","sz":"T1","r":0,"c":35},{"n":"PISM","sz":"T1","r":0,"c":29},{"n":"GAO","sz":"T1","r":0,"c":29},{"n":"Jamestown Foundation","sz":"T1","r":0,"c":23},{"n":"NATO","sz":"T1","r":0,"c":19},{"n":"EUISS","sz":"T1","r":0,"c":19},{"n":"International Crisis Group","sz":"T1","r":0,"c":15},{"n":"SWP Berlin","sz":"T1","r":0,"c":13},{"n":"Parameters","sz":"T1","r":0,"c":13},{"n":"Bulletin of the Atomic Scientists","sz":"T1","r":0,"c":12},{"n":"Brookings","sz":"T1","r":0,"c":12},{"n":"Stimson Center","sz":"T1","r":0,"c":11},{"n":"ECFR","sz":"T1","r":0,"c":9},{"n":"Carnegie Endowment","sz":"T1","r":0,"c":6},{"n":"FIIA","sz":"T1","r":0,"c":4},{"n":"IAI","sz":"T1","r":0,"c":3},{"n":"SIPRI","sz":"T1","r":0,"c":2},{"n":"KKI","sz":"T1","r":0,"c":2}],"total":1000,"focus":288,"t2focus":249,"domains":{"MDO":"Többdomainű és ágazatközi","LAND":"Szárazföldi","MAR":"Tengeri","AIR":"Légi","CYB":"Kibertér","SPA":"Világűr","COG":"Információs és kognitív tér"},"built":"2026-11-27","napi":{"datum":"2026-11-27","top":[16195,15440,15437,15474,15478,15563,15476,15349,15436,15438],"nap":15440,"elemzes":[{"cim":"Hiperszonikus fegyverek hadrendbe állítása","szoveg":"Az első Dark Eagle hiperszonikus üteg hadrendbe állítása jelezheti a hiperszonikus fegyverek iránti növekvő globális érdeklődést és a hadsereg és haditengerészet közötti együttműködés fontosságát. Ez a fejlemény utalhat arra, hogy a hiperszonikus technológia egyre inkább a modern hadviselés középpontjába kerül.","tetelek":[15440]},{"cim":"Tengeralattjáró támogatási megállapodás az Egyesült Királyságban","szoveg":"Az Egyesült Királyság Védelmi Minisztériuma és a Babcock közötti megállapodás a brit tengeralattjáró program és a folyamatos tengeri elrettentés támogatását célozza. Ez a megállapodás jelezheti a tengeralattjáró flotta modernizálásának és fenntartásának stratégiai fontosságát az Egyesült Királyság számára.","tetelek":[16195]},{"cim":"Lengyelország és az Egyesült Királyság rakétafejlesztési együttműködése","szoveg":"Lengyelország és az Egyesült Királyság közötti megállapodás a CAMM-MR rakéta közös fejlesztéséről utalhat a nemzetközi együttműködés fontosságára a rakétatechnológia terén. A Miecznik fregattok építése pedig a hazai hajógyártás fellendítését szolgálhatja Lengyelországban.","tetelek":[15478]},{"cim":"Légvédelmi rendszerek fejlesztése Ukrajnában","szoveg":"A Kongsberg és Ukrajna által közösen kifejlesztett Desna légvédelmi rendszer működése jelezheti a légvédelmi képességek fejlesztésének fontosságát Ukrajnában. A rendszer célja, hogy védelmet nyújtson a drónok és egyéb légi fenyegetések ellen, ami a modern hadviselésben egyre nagyobb jelentőséggel bírhat.","tetelek":[15563]}]}};